window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_003"]={"n":"丘逢甲","dyn":"清","poems":[{"t":"鮀江秋意","f":"七言绝句","c":["海上瀛洲已怕谭，浩然离思满天南。","西风一夜芦花雪，鮀浦秋痕上客衫。"]},{"t":"潮州舟次","f":"七言律诗","c":["抱江城郭夕阳红，百口初还五岭东。","关吏钓鳌疑海客，舟人驱鳄话文公。","九秋急警传风鹤，万里愁痕过雪鸿。","独倚柁楼无限恨，故山回首乱云中。"]},{"t":"舟入梅州境","f":"七言律诗","c":["凄绝天涯雁叫群，秋江一棹入斜曛。","阴那山色云中现，篷辣滩声雨里闻。","隔岭树疑孤塔露，得风帆带乱峰奔。","平生去国怀乡感，只合江头醉十分。"]},{"t":"客愁","f":"五言律诗","c":["烽火天涯梦，琴尊劫外身。","新亭空洒泪，故国莽怀人。","文字穷愁贱，交情患难真。","客愁无遣处，沧海尚扬尘。"]},{"t":"题东山杨子仙庙三首 其一","f":"七言绝句","c":["峰阴古庙白云关，蕉岭城开紫翠间。","斜日满林仙袂冷，笛声牛背下空山。"]},{"t":"题东山杨子仙庙三首 其二","f":"七言绝句","c":["秋风天末送归舟，閒共渔樵话钓游。","要乞仙人飞渡术，眼前沧海正横流。"]},{"t":"题东山杨子仙庙三首 其三","f":"七言绝句","c":["鳌头龙首总浮名，何事神仙也世情。","蝴蝶满天蟾满地，莫将隐语赚书生。"]},{"t":"乙未秋日归印山故居，因游仙人桥作二首 其一","f":"七言律诗","c":["海上归来意怆然，石梁重自认秦鞭。","一庵斜日坠红叶，万嶂秋空开碧莲。","家近洞天宜入道，人经浩劫欲逃禅。","松楸古墓枌榆社，早结仙家未了缘。"]},{"t":"乙未秋日归印山故居，因游仙人桥作二首 其二","f":"七言律诗","c":["溪转峰回石气阴，悬崖高阁客登临。","虹腰一角连山合，雪乳千年古洞深。","入穴人疑营窟世，题桥诗总杂仙心。","中年学道时偏早，领略樨香思不禁。"]},{"t":"有书时事者，为赘其卷端 其一","f":"七言绝句","c":["化碧三年血有痕，当年哀感满乾坤。","鹑维剪后天方醉，无路排云叩九阍。"]},{"t":"有书时事者，为赘其卷端 其二","f":"七言绝句","c":["此局全输莫认真，东南风急海扬尘。","世间傥有虬髯客，未必扶馀别属人。"]},{"t":"有书时事者，为赘其卷端 其三","f":"七言绝句","c":["残山剩水冷斜晖，独向西风泪满衣。","皂帽藜床成底事？","全家辽海管宁归。"]},{"t":"有书时事者，为赘其卷端 其四","f":"七言绝句","c":["人间成败论英雄，野史荒唐恐未公。","古柳斜阳围坐听，一时谈笑付盲翁。"]},{"t":"中秋夕乌石冈眺月同三弟崧甫作","f":"七言律诗","c":["秋风送暑夜光寒，高会依然似子桓。","弹指仙凡相隔易，称心人月并圆难。","樨香客里新诗卷，潮满天涯旧将坛。","犹有山河留影在，不妨千里且同看。"]},{"t":"还山书感","f":"七言律诗","c":["万里西风雁叫天，梅江行尽客停船。","仙踪桃熟寻杨子，禅梦茶香證了拳。","南渡衣冠尊旧族，东山丝竹负中年。","疏慵已分渔樵老，时局休谈向酒边。"]},{"t":"小住","f":"五言律诗","c":["小住为佳耳，仙人况好楼。","乡传石窟古，门对铁山秋。","县僻无车马，檐低见斗牛。","中宵犹看剑，杯酒强消愁。"]},{"t":"读白华草堂诗集","f":"七言律诗","c":["嘉道以还论粤派，谭张之外此名家。","瓣香故里尊红杏，养志高堂谱白华。","七字鼓旗雄后劲，一官鼗铎老天涯。","寻秋曾过诗人墓，重检残篇发浩嗟。"]},{"t":"重阳前数日风雨忽集慨然有悲秋之意","f":"七言律诗","c":["四山风紧湿云流，落叶声中客倚楼。","蕙怨兰啼千里梦，蛩烟雁雨一城秋。","伯龙鬼笑谋何拙，洗马人言意始愁。","丛菊空留他日泪，故园烽火未曾收。"]},{"t":"重九日游长潭六首 其一","f":"五言古诗","c":["满城歇风雨，重九天犹阴。","秋阴亦复佳，胜约行相寻。","平畴极城西，凉意生秋襟。","双桥艾坝窄，一径松坪深。","凄凉铁耕楼，无复诗老吟。","沿溪且北溯，残叶秋飘金。","林香醉人魂，潭影清人心。"]},{"t":"重九日游长潭六首 其二","f":"五言古诗","c":["驾言游长潭，长潭在何许？","峡口入滩头，曲折抵十里。","日望长潭云，今棹长潭水。","樵风送歌声，云水濛濛里。","潭云有卷时，潭水无时已。","水深龙所宫，是主云行止。","秋霖徒困人，游客爱晴美。","空潭抱珠卧，勿遽呼龙起。"]},{"t":"重九日游长潭六首 其三","f":"五言古诗","c":["积水潭益深，积石山弥尊。","山石瞰潭水，一一生秋痕。","或翁晒鱼网，或媪负幼孙。","或为仙人驱，桥址留三分。","残梳碎万齿，古阙呀双门。","是皆禀星精，且更为云根。","流水无尽时，石亦亘古存。","拊石怀古昔，高歌动乾坤。"]},{"t":"重九日游长潭六首 其四","f":"五言古诗","c":["岩翠冷欲滴，泉飞破秋烟。","中有碧血痕，终古长涓涓。","九州已无池，一线犹有天。","炼石思补之，天乎俄已颠。","亦欲一叶舟，奉母终天年。","吁嗟厄阳九，不死胡能贤？","人生祗一死，死况忠孝全！","峨峨故衣冠，寒潭写苍颜。","山灵鉴孤贞，宁须史官编。","荒祠清溪曲，遗蜕空山巅。","采菊再拜荐，酹之以寒泉。"]},{"t":"重九日游长潭六首 其五","f":"五言古诗","c":["高台不可上，中有道士庵。","不知何因缘，奔走善女男。","上悬百尺崖，下俯千尺潭。","同行各倦游，我力差能堪。","兴尽且姑止，胜境非不探。","滩头有村店，恰坐人两三。","绿茶香盈瓯，丹橘珠满篮。","是时日加午，鸡声隔烟岚。","小溪何清浅，溅溅来西南。","溪上读书堂，一饭秋茹甘。"]},{"t":"重九日游长潭六首 其六","f":"五言古诗","c":["流水渺然去，陆来乃舟归。","此行非揽胜，清节怀采薇。","颇闻潭中景，印月生清辉。","何不乘夜游？","酌酒临苔矶。","山高秋月小，松露凉琴徽。","此时发浩唱，独鹤秋空飞。","秋空苦积阴，此境安可希！","姑留不尽意，后会良非稀。","长歌归去来，菊香秋满衣。","孤棹出潭口，寒碧山四围。","城笳吹暮云，东峰下斜晖。"]},{"t":"潮州喜晤温慕柳同年别后却寄三首 其一","f":"五言律诗","c":["故人今洞主，雄镇古瀛州。","白鹿经犹讲，红羊劫未收。","秋城明落照，孤塔枕寒流。","独客来天末，相思倚柁楼。"]},{"t":"潮州喜晤温慕柳同年别后却寄三首 其二","f":"五言律诗","c":["七载春明别，重逢五岭东。","共惊须鬓改，暂喜笑言同。","落叶人千里，寒芦雪满篷。","相看遽乖隔，归棹大匆匆。"]},{"t":"潮州喜晤温慕柳同年别后却寄三首 其三","f":"五言律诗","c":["程水愁边溯，韩山望里遥。","秋风吹古渡，落日满浮桥。","沧海使方出，绿林兵未消。","过君江上宅，暮雨怅萧萧。"]},{"t":"送谢四之桃源 其一","f":"五言古诗","c":["谢子患难友，行义侔古贤。","浮海同归来，买山苦无钱。","云有桃源居，先世曾垦田。","今晨暂辞我，借得渔人船。","翘首眺八极，满目多风烟。","但求避世地，宁希拔宅仙。","君沿桃花水，或得古洞天。","仙人多贤达，当与君周旋。","径将今世人，置之太古前。","莫便不归来，令我思渺然。"]},{"t":"送谢四之桃源 其二","f":"五言古诗","c":["昔者陶靖节，为文工寓言。","凿空出渔人，飞花满仙村。","遂使啖名者，处处名桃源。","蓬莱古仙岛，清浅生沙痕。","沧桑一转瞬，变迁安足论？","变迁犹自可，况复成沉沦？","龙伯钓鳌后，三山今无存。","恐君到桃源，已异昔所闻。","租税遍桑麻，丁役及子孙。","桃花斫为薪，渔舟觅无门。","君当废然返，就我同灌园。","送君古渡头，黯然为销魂。","颢气海上来，莽莽风尘昏。"]},{"t":"野菊","f":"七言律诗","c":["入眼惊看秋气新，孤芳难掩出丛榛。","英华岂复关培植，烂熳依然见本真。","淡极君心宜在野，生成傲骨不依人。","陶潜死后无知己，沦落天涯为怆神。"]},{"t":"漫题","f":"五言律诗","c":["云卧沧江晚，浇愁浊酒醒。","霜华飘短鬓，风色急长亭。","木落林光白，郊寒麦气青。","出门吟眺回，戢影愧鸿冥。"]},{"t":"极目","f":"七言律诗","c":["极目风烟接大荒，高歌人减少年狂。","伊凉入破愁闻笛，沧海扬尘话种桑。","五夜哀弦弹落叶，万山寒色赴斜阳。","兰成枯树年来感，不待攀条意已伤。"]},{"t":"山村","f":"七言律诗","c":["重倾浊酒走惊魂，通德来归故里门。","年始二毛逢丧乱，家馀百口倖生存。","眼中精卫无沧海，劫外鹪鹩有小园。","跃马鸣骹豪气在，布衣耕钓自山村。"]},{"t":"采菊歌","f":"古风","c":["清辰采菊东山阳，紫茎绿叶垂幽芳。","世人贵薏贱真菊，弃置在野容堪伤。","萧敷艾荣苦迫压，谁复过问荒丘旁？","秋霜杀物百卉死，若抱晚节天为彰。","空山无人蔚深秀，正色独得中央黄。","流传伪种世竞采，柴色夺正工时妆。","此花隐逸应鲜识，山中开并神芝光。","我生于时得秋气，独寡时好成清狂。","黄金照耀忽满谷，采撷宁使英华藏。","度阡越陌野则获，烟萸露柏珍同囊。","贵之为宝贱则草，齐东野语非吾诳。","要之摧折世俗手，毋如老死荒山荒。","吁嗟乎！","故园有菊看不得，开傍战场空太息。","采花酿酒强作欢，共保风尘好颜色。"]},{"t":"菊枕诗 其一","f":"五言古诗","c":["繄余昔龆龀，嬉戏慈母旁。","开园种秋菊，寒花映书堂。","殷勤慈母心，采菊缝枕囊。","祝儿蠲宿痾，祝儿好容光。","垂垂手中线，宛宛生清香。","人生嬉戏时，此境安可常！","堂北萱草花，萎谢惊秋霜。","峨峨大宛山，阡表齐泷冈。","前年菊花时，登高作重阳。","墓门一瞻拜，宰木寒烟苍。","去年菊花时，奔走为戎装。","枕戈待旦心，力筹保鲲洋。","今年菊花时，故园成战场。","不及哭墓行，寸草心徒伤。","空山此高卧，哀泪沾秋裳。"]},{"t":"菊枕诗 其二","f":"五言古诗","c":["昔游净翠园，同赋菊枕诗。","维时灌阳公，初出为监司。","两迁遂持节，风雅照海湄。","从容军政暇，坛坫叠鼓旗。","客并富才俊，主更雄文词。","秋光剪入卷，裒集名诗畸。","苦心极镌刻，谓可千秋垂。","夷氛海上来，倚枕闻惊鼙。","是时菊正花，黄金甲纷披。","秋风一场战，应保危台危。","朱崖地遽弃，百计不得施。","馀生脱虎口，寤寐空相思。","昔为称意花，今作断肠枝。","兵火万卷尽，梨枣灾可知。","蠹篇纵倖存，零落生蛛丝。","安知秋斋中，清芬犹昔时。","寒宵有远梦，相觅应天涯。"]},{"t":"补裘","f":"七言律诗","c":["一领蒙茸敝莫论，皮毛缀缉幸犹存。","寒闺灯火忙纤手，客路风霜护绽痕。","事到弥缝原费力，士当穷困易为温。","时艰衮职应多阙，冷落江湖愧负恩。"]},{"t":"天涯","f":"七言律诗","c":["天涯雁断少书还，梦入虚无缥渺间。","兵火馀生心易碎，愁人未老鬓先斑。","没蕃亲故沦沧海，归汉郎官遁故山。","已分生离同死别，不堪挥涕说台湾。"]},{"t":"秋雁歌","f":"七言古诗","c":["西风吹雁秋南翔，天高野阔稀稻粱。","一雁下从野凫去，群雁思之不能置。","天涯目断寒云飞，误入罗网何时归？"]},{"t":"景忠祠吊故明孝廉林丹九先生一桂二首 其一","f":"七言律诗","c":["崖壁斑斑碧血痕，先生当日此成仁。","三闽四广支离局，一息千秋草莽臣。","乱世科名娱老母，荒山须发表完人。","扁舟欲访悲歌处，冷月空潭泻古春。"]},{"t":"景忠祠吊故明孝廉林丹九先生一桂二首 其二","f":"七言律诗","c":["三书却聘至今传，高节清风尚凛然。","列传补书宜国史，此邦议祀合乡贤。","荒祠日冷双门阙，遗寨云封一线天。","断句零章待搜缉，蠹馀留续谷音编。"]},{"t":"镇平城北近校场半里许有奇石离立山谷间，邑人所名为石伯公者也，予援南宫故事，字之曰石丈，并缀以诗 其一","f":"七言绝句","c":["奇峰特起势玲珑，石丈亲呼向谷中。","不让米颠誇韵事，空山袍笏拜松风。"]},{"t":"镇平城北近校场半里许有奇石离立山谷间，邑人所名为石伯公者也，予援南宫故事，字之曰石丈，并缀以诗 其二","f":"七言绝句","c":["杨柳春旗马射还，搜奇人坐藓痕斑。","韩陵一片愁相语，萧瑟江南庾子山。"]},{"t":"当歌","f":"七言律诗","c":["落落当歌槊自横，九州无地著狂生。","枯枰潦草棋收局，残席喧呶酒罢兵。","劫火馀灰腾谤燄，恨天遗石筑愁城。","凄凉法典唐天宝，唱到关山入破声。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其一","f":"七言绝句","c":["邻江边粤俯闽关，楼橹参差桂岭间。","欲拨寒芜寻古戍，疏林斜日半城山。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其二","f":"七言绝句","c":["断瓦零砖废苑秋，行人犹识镇山楼。","万方多难伤心客，无地登临写暮愁。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其三","f":"七言绝句","c":["带岭襟溪万雉连，筑城当日为安边。","剜苔细数残砖字，止隔明亡十二年。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其四","f":"七言绝句","c":["谯楼旧筑郁嵯峨，望远犹堪托啸歌。","一角孤城山影里，趁墟人散夕阳多。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其五","f":"七言绝句","c":["五幡青犊散馀氛，废垒连营郁战云。","班草莫谈元二劫，荒郊有鬼哭秋坟。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其六","f":"七言绝句","c":["林叶萧疏夜有霜，城阴荒草散牛羊。","市声不到墟烟冷，万冢高低送夕阳。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其七","f":"七言绝句","c":["断碣题名字半残，古松阴里好盘桓。","半间废寺无香火，佛卧空山落叶寒。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其八","f":"七言绝句","c":["冷烟寒日挂疏林，荒草迷离古径深。","樵女归来秋郭晚，山歌声出万松阴。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其九","f":"七言绝句","c":["天南舒啸失长风，沦落閒身五岭东。","一片雄心无处著，孤城斗大万山中。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其十","f":"七言绝句","c":["浮生富贵等微尘，欲觅山林寄此身。","但是故乡归便好，不妨衣白作山人。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其十一","f":"七言绝句","c":["曾费诚斋策马来，临溪处处见花开。","一庵拟筑蓝田曲，补种诗中十里梅。"]},{"t":"寻镇山楼故址，因登城四眺，越日遂游城北诸山十二首 其十二","f":"七言绝句","c":["龙楼凤阁倚天尊，肃立群山万骑屯。","戎马书生豪气在，三台高处望中原。"]},{"t":"倦客","f":"七言律诗","c":["鼎鼎年华去若流，天涯倦客怯登楼。","飘零落叶思朋好，憔悴梅花入客愁。","小醉试尝新煮酒，薄寒先上旧徵裘。","干戈满眼平生恨，梦里犹应痛昔游。"]},{"t":"钟髯歌赠钟生","f":"七言古诗","c":["英雄困厄竖子贵，丈夫灭尽须眉气。","钟生乃独以髯豪，况复奋髯敢论事。","少年浩歌苍梧怨，地老天荒写幽恨。","掉头不住出国门，濩落故山髯尚健。","髯参不为为髯仙，沧桑转眼年复年。","金丹未成髯已戟，儿女牵挽难登天。","掀髯大笑世人惑，流传髯论极豪墨。","髯乎其善保此髯，勿与纤儿争白黑。","世间不见虬髯公，扶馀坐失无英雄。","超伦轶群有髯在，令我神往沧溟东。"]},{"t":"放生鹅歌","f":"古风","c":["有鹅不送陈大夫，恐杀而食登诸厨。","有鹅不送王将军，恐笼而去伤其群。","胡子之鹅丧厥偶，俪以他雌傲不受。","孤立无党众欲杀，护之使生意良厚。","昨闻钟子放生说，今读胡子送鹅诗。","众人赞叹杨子笑，谓钟也黠胡也痴。","以说饵鹅得鹅想，以诗媵鹅误鹅往。","欲夺鹅还餍众欲，毋令鹢鹢得独享。","我闻钟子学道人，仙厨行当脯凤麟。","宁以一鹅贻口实，杨子过论疑非真。","自昔书生工凿空，幻中有幻出鹅笼。","固知杨子取为我，众人未免色为动。","众口铄金况一鹅！","道高固应生群魔。","痴者非黠黠非黠，大众勿喧听我歌。","我闻兵解亦成仙，是鹅劫尽果乃全。","伐毛洗髓用我法，立随鸡犬共升天。","生之于天放乃大，说者笑者两无害。","不然诗肠亦姑润，勿讶仙人徒狡狯。","吁嗟乎！","东南蜃气天苍黄，沙虫百万同日亡。","一鹅之生复何有？","不能成阵军声张。","男儿生当万羊膳，手扶鳌极平龙战。","嗷嗷四海安厥生，櫜弓笑赴头鹅宴。"]},{"t":"次韵答伯群二首 其一","f":"七言律诗","c":["又向山林作隐君，天涯胡马正成群。","故乡归计从今决，旧族遗风异昔闻。","入海溪声千里梦，读书灯影一家分。","卜居荏苒三秋过，久累西头住陆云。"]},{"t":"次韵答伯群二首 其二","f":"七言律诗","c":["阳关笛里变声多，戎马书生罢枕戈。","身似伯鸾犹赁庑，人因康节有行窝。","山中泉石千秋在，海上风云一梦过。","沦落祗今君勿笑，不能绛灌不随何。"]},{"t":"村居书感，次崧甫韵 其一","f":"七言律诗","c":["寥落田园隔虏尘，买山聊此息劳人。","昔贤原少閒忧乐，吾道何曾绌贱贫？","入传且栽元亮柳，行歌肯负买臣薪？","补天填海都无益，空洒东风泪满巾。"]},{"t":"村居书感，次崧甫韵 其二","f":"七言律诗","c":["乾坤苍莽正风尘，力挽狂澜仗要人。","岂有桃源堪避世，不妨蔬水且安贫。","天阊辽阻愁呵壁，时局艰危痛厝薪。","祗恐南阳难稳卧，中原戎马待纶巾。"]},{"t":"岁暮作","f":"七言律诗","c":["消尽年光是客愁，倚阑斜日下山楼。","还乡羽羡双黄鹄，入世心惊万火牛。","故纸风云供刻画，野人木石慰居游。","壮怀未遂身将老，满眼寒山早白头。"]},{"t":"除夕次颂臣韵","f":"五言绝句","c":["明日又新年，愁心隔海天。","空山寒雨里，相对不成眠。"]},{"t":"山居诗五首 其一","f":"五言古诗","c":["白云海上来，飘摇无归期。","微风起天末，吹寄兹山陲。","悦山本云性，草木生妍姿。","山中有轶士，独往人寡知。","末世何皇皇？","寸心勉自持。","故国何迢迢？","右手难将移。","临风托远意，自与云相怡。","无心出已非，万物有息时。","眷念出者劳，何用行雨为？"]},{"t":"山居诗五首 其二","f":"五言古诗","c":["我本山水人，深知山水意。","卜居山水间，山水发灵秘。","维山不厌清，毋为浊流累。","维山不厌深，毋为俗士至。","梦中古桃源，思之辄心醉。","奇遭此佳境，一往快夙志。","抚琴入泉韵，布席落岚翠。","静言养生理，中岁慰悴憔。","平生坠世网，每忆魂犹悸。","固宜古贤人，栖迟乐衡泌。"]},{"t":"山居诗五首 其三","f":"五言古诗","c":["哑哑返哺乌，得食不果腹。","一枝有安巢，山飞复山宿。","念兹心衋然，得养不在禄。","山田瘠可耕，馀事及樵牧。","东风秀百草，春山上黄犊。","苍苍者寿松，青青者慈竹。","山高蓄灵秀，自结云中屋。","采得千年芝，持为高堂祝。"]},{"t":"山居诗五首 其四","f":"五言古诗","c":["鸿灵春北归，归飞不失群。","天生此羽翼，太息世强分。","我家深山中，聊用谢世纷。","吾弟各异才，出作同习勤。","荷锄影相随，伐木声相闻。","向晦入晏息，一灯夜论文。","微言绎圣牒，奥语搜皇坟。","琅琅金石声，遥出山中云。","因之虽乱离，其乐仍欣欣。","有兄独远出，踪迹隔虏氛。","东风万里来，同念仓海君。"]},{"t":"山居诗五首 其五","f":"五言古诗","c":["德公司马徽，流寓同襄阳。","峨峨鹿门山，近接水镜庄。","幼安昔避地，亦复偕彦方。","吾友有谢生，夙昔同行藏。","黻佩不可期，负戴聊徜徉。","携家此偕隐，远渡婆娑洋。","岂不思东归，故里今犬羊。","买山共卜筑，耕凿炉峰旁。","垆峰一何高？","上有松苍苍。","上枝古藤虬，下根茯苓香。","山深富灵药，同采佐糗粮。","何须出雒市，名播如韩康？"]},{"t":"杂诗 其一","f":"五言古诗","c":["羲和驭日轮，赫赫鉴八荒。","游氛积为阴，上翳阳无光。","太白窃神威，睒睒昼有芒。","斗垣森严地，飞星敢干行。","谁实操天权，得毋失厥纲。","寂寂河鼓鸣，惨惨参旗扬。","天弧不能弦，纵恣来贪狼。","下界虮虱臣，惴惴心忧伤。","欲将灾异书，上吁通天阊。","紫霄昼沉沉，钧天乐方张。","王母宴诸天，游戏容东方。","天公色然醉，玉女倾霞觞。","列侍诸仙官，冕旋各飞扬。","方谋剪鹑首，持之赐秦王。"]},{"t":"杂诗 其二","f":"五言古诗","c":["共工触天柱，西北遂倾坠。","重烦五色石，复得天定位。","神娲抑何心？","补天不补地。","东南大海中，遂令日生事。","灵鳌实天遗，受钓误贪饵。","岱舆与员峤，坐失神山二。","蓬莱固无恙，左股复割弃。","为天谋者谁？","敢道无遗议？","诸仙各神通，坐视果何意？","閒愁落万古，茫茫渺难计。","徒劳炎帝女，填海作精卫。"]},{"t":"杂诗 其三","f":"五言古诗","c":["天鸡不能雄，牝鸡代为鸣。","膊膊复腷腷，岂云非恶声？","壮士误起舞，慨然赴功名。","失身一非时，其辱宁为荣。","枕戈夜未旦，素月当天行。","团团此皎魄，中有妖蟆生。","得地遽僭妄，吞噬亏阴精。","诸仙并束手，坐令天偏盲。","凭日复有乌，翳日失其晶。","安知豢养物，乃起为祸萌。","蒙蔽苟不知，安用天聪明？","知之不能去，容使终古横。"]},{"t":"微雨","f":"七言绝句","c":["微雨轻云扫墓天，东风消息又经年。","棠梨花发千林雪，独对春山意惘然。"]},{"t":"见雁","f":"五言律诗","c":["雁与人同去，雁归人未归。","剧怜沧海阔，独傍故山飞。","云水愁相失，风尘计已非。","天涯足矰缴，休恋稻粱肥。"]},{"t":"苦雨行","f":"七言古诗","c":["雨师昼夜驱龙行，一雨三月无停声。","乌沉兔没不敢出，仰视天日长冥冥。","冬寒凛烈春未已，浸淫木气浑归水。","稚阳欲茁老阴遏，乃张母权侵厥子。","寒风吹天不肯高，阴云四压天周遭。","娲皇补处今毕漏，石炼五色难坚牢。","尽倾海水向天半，惊波怒涛满空散。","竟无一片乾净土，著足大地成泥烂。","雄雷噤齘鸣雌雷，百虫朒缩户不开。","花藏柳匿避雨气，虽有羯鼓安能催？","物过为淫极必反，下士谈天叹天远。","恐将降魃来止雨，倒行逆施两俱损。","不然不日复不月，地晦天昏寒水发。","几疑世将入混沌，待起盘古冢中骨。","欲书绿章上青帝，请收政权屏阴翳。","膏雨和风各听令，万方重纪岁华丽。"]},{"t":"李花","f":"七言绝句","c":["蛎粉墙西易夕阳，讨春消息为春伤。","李花开落东风里，惆怅离人自断肠。"]},{"t":"雨中漫成长句","f":"七言律诗","c":["高田下田麦欲枯，前山后山雨模糊。","濛濛水气生春芜，平皋极目疑江湖。","一春闭户少游趣，饥雀窥窗自来去。","閒庭花落宾客稀，东风已绿邻家树。"]},{"t":"陈孝廉见访山中赋赠","f":"五言律诗","c":["只手回西日，都成志未申。","相逢休涕泪，吾道惜风尘。","松菊娱今是，山林閟古春。","祝君无别语，珍重待时身。"]},{"t":"愁云","f":"七言律诗","c":["愁云极目昼成阴，飞鸟犹知恋故林。","破碎河山收战气，飘零身世损春心。","封侯未遂空投笔，结客无成枉散金。","梦里陈书仍痛哭，纵横残泪枕痕深。"]},{"t":"庐山谣答刘生芷庭","f":"古风","c":["匡庐名自匡君遗，福庐乃出叶少师。","匡庐自大福庐小，名山要待人扶持。","五岭东来郁雄秀，群山冠剑森威仪。","纷趋到海尽南纪，与海争地雄鼓旗。","天藏地閟留隐秀，有山亦以庐名垂。","州因鋗姓乡旼姓，兹山未著庐者谁。","我归自东未宁宇，越鸟固应巢南枝。","不为神仙不宰相，入山将恐山灵嗤。","前身太华老道士，游仙旧梦参希夷。","误信神山在海上，失足?佩人间嬉。","九十九峰发霞燄，手持芙蓉哦新诗。","要令海国变风雅，开山初祖天人师。","青柯故侣苦相惜，小劫摧落云龙姿。","东方狼星忽悬燄，天弧久弛无神威。","扶桑岛窄奋乌足，香蕈洋浅张黥鬐。","黑风摧海水四立，阴云惨澹台山危。","沙虫百万势将化，末劫不救非慈悲。","生作愚公死精卫，谓海可塞山能移。","开屯径欲试神手，炮雷枪雨供驱驰。","玉门第八金匮九，安知变故多参差。","值天方醉剪鹑首，呵壁欲问宁非痴。","岂有扶馀王剑侠？","虬髯一传词尤支。","不如归去亦一策，山中血泪啼子规。","朱崖虽弃汉地大，公卿固应从捐之。","独恨平生失微尚，请缨请剑忘官卑。","南阳已矣不得卧，兼累羽扇无能挥。","辽东幼安本侨寓，欲去犹恋将奚为？","撒手台山惨将别，直等死别非生离。","全家轻舟径西渡，旧游回首成天涯。","闽山将尽粤山见，青山万里安舆随。","五花战袍失光彩，剩有馀耀生莱衣。","东迁四世过百载，故居乔木苍烟霏。","恐如丁仙化鹤返，感慨城郭人民非。","圆山之间印山下，厥邑隶镇乡文基。","自从宋元此聚族，小宗别祀多分祠。","朱门白屋万家聚，岁时伏腊陈牲牺。","弟兄伯叔各欢序，唐山直惜吾归迟。","摩挲故谱寻老屋，半废为圃芜不治。","故钉遗瓦存者仅，不如别卜陈蓍龟。","惟乡之西协吉卜，宗老告我庐山宜。","一邱一壑本吾愿，名山况复如相期。","忆昨泉山小留滞，清源紫帽神挚维。","阴那老僧速归驾，许我佳地当非欺。","梦中之境忽真得，此事或亦神能司。","乃携寻山绿玉杖，古径手自荆榛披。","一峰卓立出云表，苍然秀色轩人眉。","如玉屏张宝帐合，如宝驮象球弄狮。","群山众壑竞奔赴，势若拱卫来逶迤。","乃登极顶旷四瞩，玉华金简生光辉。","仙桥俯瞰飞渡迹，天马旁若凌风嘶。","目卑三台小九子，君山肃立毋敢欹。","鞭云策霞互吐纳，沐日浴月相蔽亏。","四时花开长不谢，万年松老生清飔。","洞天福地不在远，佳处要岂人境违。","四山环合若庐舍，山中地忽成平夷。","有圃宜蔬田宜稻，买山以隐宁靳赀？","乃测周圭景以正，乃用傅版功斯施。","惟堂有宦阁有簃，开门山影绿满池。","乡人载酒欲吾贺，言待其落陈金卮。","就中吾友有刘子，清言古谊吾所推。","山村易名曰澹定，刘子妙解为之词。","今晨缄书更报我，开函奇字蟠蛟螭。","庐山之谣又继作，青莲逸轨遥相追。","上为兹山发厥秀，下为吾庐言其私。","中间慷慨论时事，若屈奇诡梁哀噫。","山中展诵发浩叹，神妙欲告山灵知。","惟山如诗贵真面，得其真者名乃归。","惟楚有山称九嶷，惟蜀有山称峨嵋。","粤山罗浮实称首，同向南戒争崟崎。","兹山又别钟粤秀，如光初曜华方滋。","吾爱吾庐更爱山，以山相属吾宁辞？","山中之云出无时，青天舒卷人难羁。","山中之泉清且漪，我归自濯缁尘缁。","名庐以山庐乃结，因山得庐山尤奇。","襟江带闽此胜境，鼎足匡福宁须疑。","和君谣罢一长啸，松间双鹤高空飞。"]},{"t":"送颂臣之台湾 其一","f":"五言律诗","c":["涕泪看离棹，河山息战尘。","故乡成异域，归客作行人。","鲲海三更梦，鸥天万里春。","分明来路近，未信遽迷津。"]},{"t":"送颂臣之台湾 其二","f":"五言律诗","c":["小别宁须惜，天涯叹此行。","家书沈远道，兵火脱馀生。","东渡龙无气，南飞鹊有声。","送君惟梦寐，同到刺桐城。"]},{"t":"送颂臣之台湾 其三","f":"五言律诗","c":["此去仍乡里，家山拥画鞍。","未颁新政令，犹见旧衣冠。","落日鸥盟改，寒云雁影单。","相逢翻一笑，已作汉人看。"]},{"t":"送颂臣之台湾 其四","f":"五言律诗","c":["漫作居夷想，何妨海且浮。","冠裳虾建国，金碧蜃嘘楼。","沦落怜交旧，迟回问钓游。","都将留恋意，扶泪上归舟。"]},{"t":"送颂臣之台湾 其五","f":"五言律诗","c":["残垒过南崁，孤城枕北江。","鬼雄多死别，人士半生降。","战气花间堞，夷歌柳外艭。","伤痍犹满目，愁煞倚篷窗。"]},{"t":"送颂臣之台湾 其六","f":"五言律诗","c":["亲友如相问，吾庐榜念台。","全输非定局，已溺有燃灰。","弃地原非策，呼天傥见哀。","十年如未死，捲土定重来。"]},{"t":"送颂臣之台湾 其七","f":"五言律诗","c":["王气中原在，英雄识所归。","为言乡父老，须记汉官仪。","故国空禾黍，残山少蕨薇。","渡江论俊物，终属旧乌衣。"]},{"t":"送颂臣之台湾 其八","f":"五言律诗","c":["预计君来路，榴花照眼中。","山光仍故国，海气满征篷。","鳌背看红日，鲲身静黑风。","洗尘尊酒在，收泪话瀛东。"]},{"t":"古别离行，送颂臣","f":"古风","c":["乍愿君如天上之月出海复东来，不愿君如东流之水到海不复回。","有情之月无情水，黯然消魂别而已。","况复一家判胡越？","百年去乡里，关门断雁河绝鲤。","万金不买书一纸。","噫嘻乎嗟哉！","远游子，春风三月戒行李。","留不住箫上声，拭不灭玉上名。","千尘万劫，销不得屋梁落月之相思、河梁落日之离情。","山中水，出山不复清；","海中月，出海还复明。","不惜君远别，惜君长决绝。","知君来不来，看取重圆月。"]},{"t":"重送颂臣","f":"五言古诗","c":["恻恻重恻恻，行人适异域。","华夷忽易地，何处为乡国？","车马多离声，川原带行色。","同来不同往，欲语涕沾臆。","论交本世好，古谊吾所式。","结发论文字，廿载忘形迹。","海氛忽东来，义愤不可抑。","出君箧中符，时艰共戮力。","书生忽戎装，誓保台南北。","当时好意气，灭虏期可刻。","何期汉公卿，师古多让德。","忽行割地议，志士气为塞。","刺血三上书，呼天不得直。","北垣遽中乱，满地淆兵贼。","此间非死所，能不变计亟。","亲在谋所安，况乃虏烽迫。","乾坤已中变，万怪竞荒惑。","人情易翻覆，交旧成鬼蜮。","君亦挈家来，航海期不忒。","得君意中慰，归粤途始即。","卜居家再迁，山中事稼穑。","与君此偕隐，山水况奇特。","君言暂归视，尚有旧庐室。","来如潮有期，信在期不失。","闻君言未毕，哀泪弗能拭。","翘首沧海东，苍波渺无极。","昔时乾净土，卵育长鲸匿。","吾兄去秋往，三春阻消息。","因君速归驾，异类安可慝？","愿君信如雁，勿竟誓成浽。","归途逼炎景，珍重慎眠食。","到时常寄书，千里若门阈。","书来君不来，累我长相忆。","形影为君单，语言为君默。","我欲从君往，天不假羽翼。","时因西风夕，吹梦到君侧。","送君诗盈幅，难展肠结轖。","诗成复自写，不辨泪和墨。","愿君置怀袖，长鉴此悃愊。"]},{"t":"春第相从有年，去岁复间关渡海随予来粤，今乃请携家归台，并以绢乞诗为永念，怆然赋此","f":"五言律诗","c":["此去成乖隔，相从十载馀。","病劳调药物，閒仗护琴书。","离别他乡苦，交情患难疏。","将诗与吟诵，天末傥怀余。"]},{"t":"春愁","f":"七言绝句","c":["春愁难遣强看山，往事惊心泪欲潸。","四百万人同一哭，去年今日割台湾。"]},{"t":"梅州喜晤梁辑五光禄话旧五首 其一","f":"七言绝句","c":["重向程江续坠欢，八年潦倒别长安。","中天列宿寒无燄，等是中朝冗散官。"]},{"t":"梅州喜晤梁辑五光禄话旧五首 其二","f":"七言绝句","c":["当君读礼归田日，是我哀歌渡海年。","一副千秋家国泪，不堪齐洒岭云边。"]},{"t":"梅州喜晤梁辑五光禄话旧五首 其三","f":"七言绝句","c":["一笑全输此局棋，神州苍莽欲何之？","虬髯红拂无消息，身愧三原李药师。"]},{"t":"梅州喜晤梁辑五光禄话旧五首 其四","f":"七言绝句","c":["如画江山古敬州，潭龙殿虎各千秋。","孤城角冷梅花月，慷慨谈兵客倚楼。"]},{"t":"梅州喜晤梁辑五光禄话旧五首 其五","f":"七言绝句","c":["恩仇未了剑无光，迫窄乾坤论莫狂。","尚有神仙容退步，待将丹诀问云房。"]},{"t":"铁汉楼怀古","f":"七言律诗","c":["瘴云飞不到城头，庵圮楼荒客独游。","并世已无真铁汉，群山犹绕古梅州。","封章故国回天恨，梦寐中原割地愁。","欲倚危栏酹杯酒，程江呜咽正东流。"]},{"t":"凌风楼怀古","f":"七言律诗","c":["依旧危城隐雾中，丽谯残榜署凌风。","逃亡君相成行国，破碎河山失故宫。","地似西台宜痛哭，客归南峤怆孤忠。","欲移卦竹栽千本，遍洒天涯血泪红。"]},{"t":"题画山水","f":"七言绝句","c":["乾坤无地著英雄，满目江山夕照中。","欲觅西施作偕隐，五湖烟水一帆风。"]},{"t":"金山吊宋安抚使摧锋寨正将马发墓","f":"七言律诗","c":["一州斗大负将军，龙去崖门冷阵云。","并代汗青丞相节，全家葬碧使君坟。","艰难残局英雄泪，零落遗碑吊客文。","千古韩江呜咽水，凤城东畔送斜曛。"]},{"t":"往事","f":"五言律诗","c":["往事何堪说，徵衫血泪斑。","龙归天外雨，鳌没海中山。","银烛鏖诗罢，牙旗校猎还。","不知成异域，夜夜梦台湾。"]},{"t":"客邸晚怀 其一","f":"七言律诗","c":["西山残照下城阴，萧瑟天涯客思深。","风雨暖寒诸弟梦，关河眠食老亲心。","消磨侠胆犹看剑，留恋同声未碎琴。","绕遍南枝何处借？","夜乌啼急正投林。"]},{"t":"客邸晚怀 其二","f":"七言律诗","c":["百粤山河霸气凉，干戈初定客还乡。","愁心似海犹添水，短鬓惊秋早欲霜。","醉尉径能欺李广，冷曹应共笑冯唐。","豪情倜傥销难得，又听城笳送夕阳。"]},{"t":"大风雨歌","f":"七言古诗","c":["乌轮晦光兔魄死，海上群龙方戏水。","力撼乾纽摇坤维，骇听东南大风起。","大风吹云云飞扬，八荒一气云茫茫。","绝无天地但有海，祗恐人物沉汪洋。","谁鞭电鞭鼓雷鼓？","忽起蛟龙满空舞。","池中方困人不知，世眼惊看得云雨。","一风三日不得停，云昏雨黑宵冥冥。","直疑天老易混沌，万古无复长空青。","谁知淫烈有时定，妄用推测群相惊。","风收云歇天地静，归龙捲雨微闻腥。","大海无波平如镜，沐浴日月还晶明。","山中道人蕴道妙，六根清净容长少。","风声雨声寂不闻，独抚乾坤发长啸。"]},{"t":"答王晓沧","f":"七言律诗","c":["曾见王郎海上行，十年重晤凤皇城。","消磨花月新诗卷，沉郁风云旧酒兵。","往事欲谈宜痛哭，此生贻误是浮名。","尊前豪语劳君记，孤负移山志不成。"]},{"t":"谒潮州韩文公祠 其一","f":"七言律诗","c":["一疏真教佛可焚，中朝无地得容君。","孤臣去国关初雪，逐客呼天岳不云。","金石流传鹦鹉赋，风雷趋奉鳄鱼文。","寻碑独向城东路，古木萧萧冷夕曛。"]},{"t":"谒潮州韩文公祠 其二","f":"七言律诗","c":["江山得姓总公遗，有客观潮发古思。","失路英雄凭吏笑，投荒心迹岂僧知？","千秋道学重开统，八代文章始起衰。","北斗声华南斗命，海天来拜使君祠。"]},{"t":"去岁秋初抵鮀江，今仍客游至此，思之怃然 其一","f":"七言绝句","c":["琴剑萧然尚客游，海天容易又经秋。","渡江人物消沉尽，谁识当时第一流？"]},{"t":"去岁秋初抵鮀江，今仍客游至此，思之怃然 其二","f":"七言绝句","c":["沦落天涯气自豪，故山东望海云高。","西风一掬哀时泪，流向秋江作怒涛。"]},{"t":"香港书感 其一","f":"五言律诗","c":["海色不可极，西风吹鬓丝。","中朝正全盛，此地已居夷。","异服鱼龙杂，高巢燕雀危。","平生陆沉感，独自发哀噫。"]},{"t":"香港书感 其二","f":"五言律诗","c":["玫瑰纷流劫，芙蓉此煽妖。","效灵无海若，得志有天骄。","奇丽开荒岛，凭陵叹小朝。","秋风散凉意，热血苦难消。"]},{"t":"乞陈颐山作画","f":"七言绝句","c":["百粤河山霸气孤，英雄遗迹冷秋芜。","先生自有千秋笔，乞写朝台吊古图。"]},{"t":"菊坡精舍作","f":"七言律诗","c":["古木萧森护讲堂，当年曾是午桥庄。","园开丞相秋花晚，席冷经师宿草荒。","山色尽收全粤壮，潮声遥送一城凉。","风尘满眼文章贱，倚剑危栏夕照黄。"]},{"t":"九眼井 其一","f":"七言绝句","c":["歌舞冈前汲道新，闭关容作老夫臣。","陈亡项灭韩彭死，只许君王是寿人。"]},{"t":"九眼井 其二","f":"七言绝句","c":["凿井秦人老塞烟，抱孙雄踞海南天。","江山不改遗民尽，独坐秋风自品泉。"]},{"t":"鲍姑祠","f":"七言绝句","c":["满目江山海气阴，鲍姑祠畔客登临。","欲寻越井冈头艾，多恐神龙病已深。"]},{"t":"镇海楼二首 其一","f":"七言律诗","c":["独上层楼唱越风，尉佗城郭夕阳中。","九州南尽馀沧海，万里秋高作寓公。","旌节雄藩秦塞改，衣冠故国楚庭空。","倚栏欲写兴亡感，依旧江山霸气雄。"]},{"t":"镇海楼二首 其二","f":"七言律诗","c":["高踞仙城最上头，万方多难此登楼。","金汤空抱筹边略，觞咏难消吊古愁。","绝岛风尘狮海暮，大江云树虎门秋。","苍茫自洒英雄泪，不为凭阑忆故侯。"]},{"t":"古诗 其一","f":"五言古诗","c":["富贵果何物？","遭者罔不诎。","腼然衣冠徒，奔走愧行乞。","平生干镆锋，安能顿使屈？","乾坤值震荡，眼底鲜英物。","不恨见越公，恨不遇红拂。","知己得美人，散此万古郁。"]},{"t":"古诗 其二","f":"五言古诗","c":["黄羲忽然没，太古不可复。","古有伤心人，所遇但痛哭。","人各赋性情，天生是使独。","天乎何不仁！","挤与世相逐。","鸟兽岂吾群？","纷然况满目！","誓将万古泪，上报彼苍酷。","天有时而倾，地有时而缩。","放声同一哀，海水化平陆。"]},{"t":"古诗 其三","f":"五言古诗","c":["神鱼砀失水，跛鳖相瑕疵。","威凤无桐巢，笼雀揶揄之。","按剑遭不平，慷然生古悲。","苍茫自天意，窥者安能知？","我怀古达士，所履皆其夷。","岂无非意干？","飘风当坠枝。","偶然出游戏，播弄随纤儿。","手抚铁如意，一笑方支颐。"]},{"t":"古诗 其四","f":"五言古诗","c":["沧海方横流，志士无安居。","皇皇太自苦，露处王尼车。","车亦不得息，志亦不得舒。","摧车抑其志，自火用世书。","不合固其常，何不慎所如？","躬耕可苟全，且觅南阳庐。"]},{"t":"古诗 其五","f":"五言古诗","c":["凉风剥高林，万树忽全裸。","英华不可恃，荣者已先堕。","人生怀百忧，所见毋乃左！","乾坤忽流劫，万汇尽一火。","死者为哀燐，存者仅硕果。","出门念交旧，万里剩孤我。","嗟哉何酷毒，此罪天应坐。","留此七尺躯，马革不得裹。","畀为愁城主，所值无一可。","闻有古化人，天不能福祸。","我欲往从之，道远多坎坷。","采桂持作楫，纫兰持作柁。","茫茫此愁海，远泛凌风舸。"]},{"t":"珠江书感","f":"七言绝句","c":["窄袖轻衫装束新，珠江风月漾胡尘。","谁知宠柳娇花地，别有闻歌感慨人。"]},{"t":"珠江行乐词","f":"古风","c":["马鞍山头紫云起，脂香粉腻珠江水。","英雄儿女满襟泪，只合王郎为情死。","江头日日呼画船，珠歌翠舞年复年。","安知海上东风起，摧花折柳尘迷天。","尊前莫话风波恶，豪竹哀丝方间作。","自是风流魏晋人，醉死梦生恣行乐。","生不愿作蛮夷大长汉老臣，亦不愿作朱明洞主秦仙人；","但愿珠江排日泛花舫，花光照海海不尘。","噫嘻乎！","人生悲欢离合无不有，江上看花速呼酒。"]},{"t":"长句赠许仙屏中丞并乞书心太平草庐额，时将归潮州","f":"古风","c":["江波不作河安流，春风岭海建节楼。","筹边赖有重臣在，朝廷南顾今无忧。","自从互市启海禁，一衣带水连五洲。","驱雷策电驭水火，碎裂大地分全球。","恃其吊诡肆要挟，但有盘敦无共球。","纵横捭阖等战国，势将迫我为宗周。","况乃东粤本始衅，门庭伏寇森戈矛。","迩来飙车欲西动，更虞瞰我从上游。","威之不畏德不感，中枢术已穷怀柔。","海南万里得安堵，所恃元老能壮猷。","方今议者利变法，我法不用宁非羞？","况有治人无治法，若为国计宜人求。","惟公抗古独持论，会当入告宣嘉谋。","有客哀歌动天地，蹈海不死生犹偷。","南来谒公辱庭见，五羊城郭方清秋。","天涯沦落苦无著，荷公还我东扬州。","卖文傥得买山价，草庐拟筑山之幽。","前身太华老道士，黄庭一卷供清修。","以心太平署庐榜，乞公大笔千秋留。","闻公课吏言所志，补义取我琼山丘。","治平要自儒者事，岂在西法趋从欧。","太平无事傥有日，定许閒暇娱清游。","此事难期此心在，乾坤浩荡消边愁。","吁嗟乎！","丈夫生当为八督州、取万户侯；","不然，儒冠世方厌，径须学道寻罗浮。","乞公之书为公讴，狂奴之态公勿笑，江湖此去行扁舟。","公致太平傥我见，且看东南剑气凌斗牛。"]},{"t":"羊城中秋 其一","f":"七言律诗","c":["长啸天南念远游，尉佗台畔作中秋。","酒杯借我酬佳节，明月随人到广州。","说饼但馀名士气，飞觞终取虏王头。","大江东去连沧海，且听珠娘发棹讴。"]},{"t":"羊城中秋 其二","f":"七言律诗","c":["故乡风景想依然，月满东南半壁天。","海外阴晴终有定，人间圆缺古难全。","重完破碎山河影，与结光明世界缘。","甲帐珠襦寻旧梦，不知今夕是何年？"]},{"t":"羊城中秋 其三","f":"七言律诗","c":["西风梧叶下空冈，歌舞承平霸业荒。","沧海潮生珠有泪，贲隅秋老桂初香。","万家愁喜圆今月，一尉东南忆故王。","玉宇高寒归未得，待将消息问吴刚。"]},{"t":"广州晤刘葆贞编修","f":"七言律诗","c":["漠漠连天海气昏，越王台上望中原。","何人更下新亭泪，有客同倾浊酒尊。","月旦汝南逢许劭，人才江左数刘琨。","与君欲作闻鸡舞，夜半寒涛撼虎门。"]},{"t":"仙屏中丞手书“扫除万事付诸命、卓荦高才独见君”楹帖见赠赋谢","f":"七言律诗","c":["南极文章照上台，琼瑶飞降戟门开。","谁知挥洒烟云处，别具评量月旦来。","君相果然能造命，英雄从古必怜才。","句奇语重吾能喻，从此王郎歌莫哀。"]},{"t":"赠梁诗五孝廉二首 其一","f":"五言律诗","c":["五十不卿相，公才负黑头。","艰难困衣食，著述慰穷愁。","天意方难测，人材世鲜求。","谁知梁叔敬，生待取封侯。"]},{"t":"赠梁诗五孝廉二首 其二","f":"五言律诗","c":["潦倒天南客，登台吊尉佗。","相逢剧如故，当哭有长歌。","西日天方暝，东风海正波。","何当奋雄略，找剑斫蛟鼍。"]},{"t":"珠江重有感叠前韵 其一","f":"七言绝句","c":["璧月秋江歌舞新，满船花气荡香尘。","赵佗死后无英物，收拾江山付美人。"]},{"t":"珠江重有感叠前韵 其二","f":"七言绝句","c":["十斛明珠一曲新，英雄儿女黯风尘。","重来祗恐江山换，记取沙鸥是故人。"]},{"t":"秋暑酷甚戏咏","f":"七言律诗","c":["西风南来秋力微，颢气晓敛张炎晖。","火德已衰更中起，酷吏将去犹能威。","门前褦襶复辞客，树阴槃礡乃解衣。","九龄羽扇未可弃，尚当为君效一挥。"]},{"t":"秋怀 其一","f":"七言律诗","c":["如此乾坤付越吟，剩将诗卷遣光阴。","镜中白发愁来早，衣上缁尘劫后深。","半壁河山沉海气，满城风雨入秋心。","留侯博浪椎无用，笑抚残书酒独斟。"]},{"t":"秋怀 其二","f":"七言律诗","c":["古戍斜阳断角哀，望乡何处筑高台。","没蕃亲故无消息，失路英雄有酒杯。","入海江声流梦去，抱城山色送秋来。","天涯自洒看花泪，丛菊于今已两开。"]},{"t":"秋怀 其三","f":"七言律诗","c":["策策西风吹晚凉，惊秋人共雁南翔。","海山缥缈半烟雾，泽国萧条初雨霜。","谁许半千论古阵，且逢重九醉他乡。","莫嗟欲济无舟楫，待起鼋鼍与架梁。"]},{"t":"秋怀 其四","f":"七言律诗","c":["笺天谁为写离忧，愁大翻怜隘九州。","明鬼径须从墨翟，望洋聊与说庄周。","等身书卷供行路，故国山河入倚楼。","怕向天涯舒倦眼，伏风阑雨不成秋。"]},{"t":"秋怀 其五","f":"七言律诗","c":["暂息边烽强自宽，出门西笑说长安。","金缯商保太平局，冰炭磨成清要官。","南峤流移伤百越，东藩沦陷痛三韩。","驱车欲去仍留滞，风雪关河怯早寒。"]},{"t":"秋怀 其六","f":"七言律诗","c":["连天衰草怅萧辰，憔悴秋风泪满巾。","果下近游思贳马，芦中小隐任呼人。","渡江早虑胡分晋，蹈海终挠赵帝秦。","收拾钤韬付儿辈，乾坤潦倒腐儒身。"]},{"t":"秋怀 其七","f":"七言律诗","c":["莫笑谈瀛胆气粗，眼前时局古来无。","未容樊哙誇功狗，终遣林宗叹屋乌。","浮海已怜吾道废，移山谁悯此公愚。","江湖且作扁舟计，满地秋容雪点芦。"]},{"t":"秋怀 其八","f":"七言律诗","c":["菊恨兰悲閟众芬，天南牢落怅离群。","客愁竟夕怜江月，乡梦千重隔岭云。","长笛且吹新道调，短衣谁识故将军。","雄心消尽閒情在，四海无家独卖文。"]},{"t":"韩山书院新栽小松 其一","f":"七言绝句","c":["郁郁贞蕤夜拂霜，十年预计比人长。","要从韩木凋零后，留取清阴覆讲堂。"]},{"t":"韩山书院新栽小松 其二","f":"七言绝句","c":["不惜阶前尺地宽，孤根未稳护持难。","何须定作三公梦，且养贞心共岁寒。"]},{"t":"韩山书院新栽小松 其三","f":"七言绝句","c":["森森高节自分明，莫学胥涛作愤声。","大厦将倾支不易，栋梁材好惜迟生。"]},{"t":"韩山书院新栽小松 其四","f":"七言绝句","c":["出林鳞鬣尚参差，已觉干霄势崛奇。","只恐庭阶留不得，万山风雨化龙时。"]},{"t":"次韵陈衡仲招饮可园","f":"七言律诗","c":["销兵聊当太平年，小饮林亭意豁然。","大海潮声来笔底，满城山色落尊前。","酒能益寿姑谋醉，诗恐伤时不放颠。","如此消閒宜夜宴，待呼冷月照炎天。"]},{"t":"对月放歌答友人","f":"七言古诗","c":["振华楼头看今月，今月冰人销侠骨。","令人却忆古月光，恨我生不逢羲皇。","君胡怀今不怀古？","锻月入诗寄阏父。","阏父落拓今诗颠，将诗诉月愁南天。","南天入秦始受吏，秦月曾照龙川尉。","却怜今月无古光，独倚楼栏看剑气。"]},{"t":"寄怀许仙屏中丞 其一","f":"七言律诗","c":["万里惊涛赋壮游，天南回首穗城秋。","使君正运桓公甓，归客新乘少伯舟。","五岭关河通骆越，百灵风雨会罗浮。","相逢抵掌谈时事，曾许筹边上节楼。"]},{"t":"寄怀许仙屏中丞 其二","f":"七言律诗","c":["锁钥南畺倚重臣，叩关琛赆竞飞轮。","朝台纛去无黄屋，瀛海舟来有白民。","自是绥怀关要略，不妨觞咏集诗人。","陈琳已老刘桢少，最忆翩翩座上宾。"]},{"t":"寄怀许仙屏中丞 其三","f":"七言律诗","c":["归飞越鸟恋南枝，劫后馀生叹数奇。","破例山公初启事，投荒韩渥尚吟诗。","注书已厌谈孙武，变姓仍难隐子皮。","早岁钤韬且收拾，横渠依旧拥皋比。"]},{"t":"寄怀许仙屏中丞 其四","f":"七言律诗","c":["旌门载别又经年，菊秀兰芳八月天。","每赋秋容怀潞国，偶谈边计托樊川。","呼鸾道远思瑶节，化象潭清制锦笺。","手写新诗寄钤阁，报章遥盼雁来前。"]},{"t":"家芝田市菊数盆见赠，时已冬十月矣，感其晚芳，摛我郁抱，聊赋拙什以质芝田 其一","f":"七言律诗","c":["寒雨潇潇下凤城，秋光残后见金英。","失时未贬文章价，入市难逃隐逸名。","香国久推黄种贵，蛮花休慕黑洋生。","吟芳冷抱无穷感，过酒墙头且共倾。"]},{"t":"家芝田市菊数盆见赠，时已冬十月矣，感其晚芳，摛我郁抱，聊赋拙什以质芝田 其二","f":"七言律诗","c":["两开空忆故园芳，开处都因傍战场。","仙客采馀舟已去，先生归后径全荒。","黄金旧赋高皇甲，紫绶新飘岛国章。","风景不殊人事改，有花便合作重阳。"]},{"t":"家芝田市菊数盆见赠，时已冬十月矣，感其晚芳，摛我郁抱，聊赋拙什以质芝田 其三","f":"七言律诗","c":["一帘秋色顿萧疏，如为餐英赋卜居。","鱼市人家斜照里，凤城花事晚寒初。","群阴蒙覆容高傲，百卉凋零等扫除。","莫怪闭门今不出，幽香深处读奇书。"]},{"t":"寄家菽园孝廉新架坡二首 其一","f":"七言律诗","c":["韩苏笔力不到处，石破天惊自著书。","未悔居夷从凤鸟，真看横海掣鲸鱼。","河山烟点齐州外，文字雷屯草昧初。","闻说鸡林争购集，百蛮齐拜孝廉车。"]},{"t":"寄家菽园孝廉新架坡二首 其二","f":"七言律诗","c":["中原有客正悲歌，事去曾挥指日戈。","谁解闻鼙思将帅，誓将倾篑障江河。","诗篇涕泪唐天宝，梦寐贤良汉特科。","遥寄尺书沧海曲，古来义士岛人多。"]},{"t":"题梅花帐额 其一","f":"七言绝句","c":["半壁河山慰卧游，凤城寒色满徵裘。","谁知铁石心肠客，閒赋梅花自写愁。"]},{"t":"题梅花帐额 其二","f":"七言绝句","c":["莽莽边尘暗海南，中宵倚剑对横参。","不如竟作罗浮隐，翠羽梅花客梦酣。"]},{"t":"岁暮杂感 其一","f":"七言律诗","c":["极目寒山落照迟，边风猎猎捲牙旗。","黄犀入贡非今日，白马驮经异昔时。","山海龙呼愁变夏，春秋麟泣戒书夷。","千年妖火弥张燄，太息流传景教碑。"]},{"t":"岁暮杂感 其二","f":"七言律诗","c":["电骇雷惊局屡新，梦中愁见海扬尘。","九夷何地容嬉凤，两曜兼旬厄斗麟。","赤县鸿流堙息壤，紫垣狼燄迫勾陈。","邹生漫诧谈天口，吹律先回黍谷春。"]},{"t":"岁暮杂感 其三","f":"七言律诗","c":["云中鸡犬换流年，尘世讹闻劫火燃。","玉斧全功收画地，金轮馀燄起遮天。","元王故国愁宫黍，白帝新都问岳莲。","终见神符兴赤九，不应流泪到铜仙。"]},{"t":"岁暮杂感 其四","f":"七言律诗","c":["轮转坤舆急景催，冻风天末送愁来。","栖残彩凤宫梧老，卖断卢龙塞草衰。","驿远江南梅未落，园荒河北李仍开。","月寒日暖忧煎寿，且劝飞光酒一杯。"]},{"t":"岁暮杂感 其五","f":"七言律诗","c":["昆崙馀干走沧溟，考异须占极外星。","杀运百年兵气白，飞机万里石云青。","鳌沉难定三神位，龙战将移五岳形。","尘秽海洲谈国势，消寒閒检赤霆经。"]},{"t":"岁暮杂感 其六","f":"七言律诗","c":["一曲升平泪万行，风尘戎马厄潜郎。","民愁竞造黄天说，岁熟如逢赤地荒。","七贵五侯金穴富，白山黑水铁车忙。","老生苦记文忠语，多恐中原见鹫章。"]},{"t":"岁暮杂感 其七","f":"七言律诗","c":["五洲云扰角群雄，幻出楼台蜃气中。","环起杀机愁易宿，饫闻怪事懒书空。","八风裂竹乖伦律，九日争桑拒羿弓。","说佛不妨妨说鬼，飞燐早已逐韩公。"]},{"t":"岁暮杂感 其八","f":"七言律诗","c":["牢落高阳旧酒徒，缶声悽绝唱乌乌。","极知王屋移非计，坐惜神丛借已枯。","老骥负车鸣折坂，饥鹰驱雀下平芜。","人间剥复关天运，醉看梅花九九图。"]},{"t":"岁暮杂感 其九","f":"七言律诗","c":["寒宵读史一灯深，眼底浮云变古今。","卒懦无狐篝楚火，士愚有狗斗秦金。","故应积气天难坠，何致清谈陆便沉。","上界不知人事苦，但闻开宴奏元音。"]},{"t":"岁暮杂感 其十","f":"七言律诗","c":["卜居何处是南村，说虎翻怜市语喧。","铜鼓嶂高山雪盛，红罗沙近海云昏。","太阴守岁愁兵气，故国逢春怆梦痕。","熳烂桃花过残腊，人閒无路访仙源。"]},{"t":"家琼楼、晴溪过访，兼赠阳明碑刻寒支文集，即送归上杭 其一","f":"五言律诗","c":["远道劳相访，承筐毕古仪。","残碑出新建，遗集得寒支。","勋业衰朝大，文章异代悲。","昔贤今不作，相对起遐思。"]},{"t":"家琼楼、晴溪过访，兼赠阳明碑刻寒支文集，即送归上杭 其二","f":"五言律诗","c":["好语吾宗彦，流移羡乐郊。","族从元宋聚，地扼粤闽交。","丁令成归鹤，周侯悔斩蛟。","琴岗最佳处，为我卜衡茅。"]},{"t":"除夕诗 其一","f":"七言古诗","c":["百年鼎鼎三去一，百事不能能执笔。","规天抚地愿未毕，坐废一万二千日，徒费精神了无益。","手携诗卷行天涯，百事不成成者诗。","诗能穷尔尔不知，可怜除夕复祭之，有脯在俎酒在卮。","梅花一笑回春姿，弄笔尚自吟南枝。"]},{"t":"除夕诗 其二","f":"七言古诗","c":["长蛇东来饥而贪，我欲斩之力不堪。","坐令闾井歧商参，故居缥渺海色蓝。","羁栖复筑山中庵，此身乃虱江城南。","今夕何夕陈酒果，一家分照围炉火。","海阔山遥定思我，今夕不寐寐应可。","东风吹梦云万朵，剑光入海长蛇堕，长啸故山侍亲坐。"]},{"t":"除夕诗 其三","f":"七言古诗","c":["岁何可守乃守岁，老大尚为儿女事。","岁去重关不能闭，岁何须饯乃饯岁。","一尊甫陈万感至，醒眼闷看司命醉。","平生媚灶苦不工，坐令三十弥困穷。","何人设祀黄羊丰，家拥金穴身三公。","仰天愁睇青濛濛，但见斗柄春回东。"]},{"t":"戊戌元旦试笔","f":"五言律诗","c":["麟笔书春后，将铭绝世功。","驰书谕殊域，草檄下群雄。","沧海波全定，神州日再中。","东西朔南暨，齐颂黑头公。"]},{"t":"水仙花诗奉家君命作 其一","f":"七言律诗","c":["廿番芳信报新年，海上愁春下谪仙。","入世花偏蜕凡骨，捲帘人自荐寒泉。","双钩写韵珍遗绢，一操飞香冷素弦。","流落纵教天不管，何曾飘坠向风前。"]},{"t":"水仙花诗奉家君命作 其二","f":"七言律诗","c":["白石清泉足雅供，赏春休倚醉颜红。","满堂金玉饶仙福，近水楼台总化工。","高绝声华香茗附，等閒出处素兰同。","年年一现天人影，不在凡花色相中。"]},{"t":"日蚀诗","f":"七言古诗","c":["天鸡唱晓声琅琅，六螭驾日升榑桑。","朱麟忽斗阻日驭，赤乌饥啄金轮旁。","佛方灭度魔未伏，天龙八部何披猖？","罗㬋左手出障日，中天竺国全无光。","须弥山影陡闇黑，当昼星见垂妖芒。","南赡部州古圣国，羲鞭猛著当空忙。","魔云走逐复不舍，虽欲远避难为藏。","尚留半镜不全缺，奋目赖有开天皇。","羿弓昔射九乌死，一乌留使终朝翔。","岂容魔力夺所舍？","坐令万古无阴阳。","岁星过处玉犬吠，魁杓方指苍龙苍。","于时下方正岁旦，太史占日书灾祥。","中朝天子用中法，乃罢酒醴停笙簧。","陈兵典已命司马，萦社术复稽公羊。","龙舆不御避正殿，麟鼓载击通天阊。","有经救护出佛口，亦遣梵诵僧衣黄。","黄冠复令道所道，步虚声里飞金章。","预传丹诏戒群吏，郡朝县舍同遑遑。","百神闻之奏天帝，迩来叠肆群魔狂。","丰隆祗今赐休假，太皞莅职方治装。","时惟三方庆高会，列仙竞进朱霞觞。","径欺天醉巧抵隙，举手更肆魔氛强。","前犹障月此障日，未可天度仍包荒。","祛罗行且涌海天，药叉罗刹争跳梁。","迦楼罗动鹏翮猛，乾闼婆耸龙头昂。","帝车窃据弄斗柄，妖党朋煽联天狼。","神州况复有伏莽？","徵妖召怪难为防。","共工头坚柱且折，蚩尤气横旂频扬。","治之不早使潜结，将易天姓纷刘张。","以魔应魔竞强倔，戎首实自罗㬋倡。","下方日月号天眼，任蚀不治讹天盲。","赤云飞夹白虹贯，效尤而起安可常？","甚将裂日作三两，蚀而不已日且亡。","收之桑榆未为晚，百神伫待张天纲。","维帝曰嗟予其治，维尔神并扶阳刚。","乃诏郁仪饬内政，结璘阴教为匡襄。","赐之天弧威不服，参旂井钺光煌煌。","魔将束手伏鬼国，寰宇无复妖氛飏。","彼虽障日日固在，但用魔法胡能长？","天工自古贵人亮，此理维圣为能详。","昔垂佛日使西照，天龙八部走且僵。","况今苍精且御宇，将游化日如陶唐。","要须中国圣人出，前驱麒麟后凤凰。","大九州成大一统，万法并灭宗素王。","四天下皆共一日，永无薄蚀无灾伤。","不然测日有辩口，魔法复幻来西方。","直教天变不足畏，流祸且恐过焚坑。","不惟两儿困尼父，顽辩如盂如探汤。","彼乃有帝解造日，将惑黄种归亚当。","谁欤觉者解厥惑，力拒魔说毋遗殃！","下方有臣心向日，捧日愿大无能偿。","梦排阊阖闻帝语，天空海阔歌慨慷。","海风浩浩夜未央，天鸡再唱云入房。"]},{"t":"广济桥四首 其一","f":"七言律诗","c":["垒洲廿四水西东，十八红船铁索中。","世变屡新潮汐改，驿程依旧粤闽通。","五州鱼菜行官帖，两岸莺花集妓篷。","莫怪桥名工附会，江山原已属韩公。"]},{"t":"广济桥四首 其二","f":"七言律诗","c":["城东锁钥俨天然，雁齿虹腰递接连。","一水官如分界守，四朝人不及桥坚。","长消难准仙无碣，开闭当关吏有权。","何处骑牛寻醉汉，凤凰山上日云烟。"]},{"t":"广济桥四首 其三","f":"七言律诗","c":["花里秦云事岂诬，中桥有庙祀清夫。","此江驱鳄关文字，终古飞虹化险途。","石鲤春浮洲浪活，铁犀夜立舫灯孤。","题诗莫误传仙笔，湘子桥头一钓徒。"]},{"t":"广济桥四首 其四","f":"七言律诗","c":["汀赣循梅万派强，济川终赖此津梁。","涨痕雨急三门信，夹道风喧百果香。","江水岂能流石转，神仙原为渡人忙。","乘潮怕有潜蛟起，独立飞亭看剑光。"]},{"t":"答台中友人 其一","f":"七言律诗","c":["极目风涛怆梦思，故山迢递雁书迟。","渡江文士成伧父，归国降人谤义师。","老泪纵横同甫策，雄心消耗稼轩词。","月明海上劳相忆，凄绝天涯共此时。"]},{"t":"答台中友人 其二","f":"七言律诗","c":["抱石申屠剧可怜，一庵待死伴枯禅。","湛身难诉遗民苦，殉义谁彰故部贤。","碧血纵埋非汉土，赤心不死尚唐年。","扁舟但益飘零感，过海何曾便是仙！"]},{"t":"答台中友人 其三","f":"七言律诗","c":["归来谁与话酸辛，满目茫茫劫后尘。","末俗嚣凌欺客户，长官尊重薄流民。","本无旷土容安插，难恃高文济困贫。","冷守平生心迹在，朝衫零落泣孤臣。"]},{"t":"王姑庵绝句十六首 其一","f":"七言绝句","c":["龙飞皇觉领诸天，衣钵曾留逊国年。","谁料凤阳陵哭后，家风传到女婵娟。"]},{"t":"王姑庵绝句十六首 其二","f":"七言绝句","c":["法雨香霏洗额黄，伽瑜自换故宫妆。","北风吹坠南枝月，泣对梅花礼梵王。"]},{"t":"王姑庵绝句十六首 其三","f":"七言绝句","c":["芳心飘泊总思明，日曜亲书作法名。","帝牒不如僧牒永，女墙残照下钟声。"]},{"t":"王姑庵绝句十六首 其四","f":"七言绝句","c":["汴城宫殿郁嵯峨，已逐禅心委逝波。","若化冤禽号朱鸟，不填沧海定填河。"]},{"t":"王姑庵绝句十六首 其五","f":"七言绝句","c":["殊恩异代降香车，未许长平竟出家。","不及天南怀帝后，转经遥祝海棠花。"]},{"t":"王姑庵绝句十六首 其六","f":"七言绝句","c":["禅房春冷佛灯微，玉叶金枝事已非。","夜半闻鹃停梵诵，泪花红溅水田衣。"]},{"t":"王姑庵绝句十六首 其七","f":"七言绝句","c":["故事凄凉说粉侯，西风梧落梵宫秋。","无穷家国兴亡感，诉向莲台佛也愁。"]},{"t":"王姑庵绝句十六首 其八","f":"七言绝句","c":["劫馀龙种少生存，云护孤雌入梵门。","毕竟千金凭佛保，天涯哀遍女王孙。"]},{"t":"王姑庵绝句十六首 其九","f":"七言绝句","c":["故国敲残梦里钟，黄河流恨走开封。","丹青空貌天人影，难写宫愁上梵容。"]},{"t":"王姑庵绝句十六首 其十","f":"七言绝句","c":["望云残榜篆模糊，想见思亲泪眼枯。","南北两都无寸土，一庵今尚属王姑。"]},{"t":"王姑庵绝句十六首 其十一","f":"七言绝句","c":["凤城宝马碾香尘，花亸春游善女人。","水月空庵齐膜拜，妙庄王女是前身。"]},{"t":"王姑庵绝句十六首 其十二","f":"七言绝句","c":["瘦石零花半塔欹，萧条香蜕葬江湄。","尚书老死遗民尽，谁署天潢小裔碑。"]},{"t":"王姑庵绝句十六首 其十三","f":"七言绝句","c":["秀容入后瑶光废，法侣飘零闭绮窗。","应有香魂归吊月，佛楼寒火碧秋幢。"]},{"t":"王姑庵绝句十六首 其十四","f":"七言绝句","c":["二百年来一帧完，九莲遗迹已飘残。","老尼也识沧桑感，不作寻常绣佛看。"]},{"t":"王姑庵绝句十六首 其十五","f":"七言绝句","c":["胜朝遗老半为僧，短发萧萧百感增。","谁识天家留佚女，比丘尼派衍南能。"]},{"t":"王姑庵绝句十六首 其十六","f":"七言绝句","c":["西山曾访王姑寺，吊古南来又此庵。","一样女儿身说法，满天花雨落优昙。"]},{"t":"元夕无月 其一","f":"七言绝句","c":["满城灯市荡春烟，宝月沉沉隔海天。","看到六鳌仙有泪，神山沦没已三年。"]},{"t":"元夕无月 其二","f":"七言绝句","c":["三年此夕月无光，明月多应在故乡。","欲向海天寻月去，五更飞梦渡鲲洋。"]},{"t":"元夕无月 其三","f":"七言绝句","c":["鲲云梦断夜潮寒，佳节偏怜见月难。","十二楼台春寂寂，满身花露倚栏干。"]},{"t":"元夕无月 其四","f":"七言绝句","c":["倚阑痴待月华来，万斛春愁酒一杯。","恨煞蛮云遮隔住，东风无力为吹开。"]},{"t":"元夕无月 其五","f":"七言绝句","c":["蛮云黯黯海天昏，冷对春灯忆梦痕。","今月纵明输古月，更无人说夺昆崙。"]},{"t":"千秋曲","f":"五言古诗","c":["古人习轻趫，因之作绳戏。","意与蹋鞠同，本用事武备。","何时入宫禁，乃令娱姬侍。","宫中岂教战？","美人竟身试。","名之曰千秋，祝词意何媚？","讹转为鞦韆，颠倒因文字。","春风动帘帷，兰闺寂无事。","嬉春藉苏困，不惜委珠翠。","遂疑作戏初，专为妇人置。","何期岭外州，戏乃有古义。","闾左侠少年，习武广场地。","双绳下系板，朱竿矗若植。","各斗好身手，高自鸣得意。","仙乎疑肉飞，人也俨著翅。","斯技固甚微，斗力非斗智。","当其分明角，势亦殊钝利。","形劳逸其神，乃不虞陨坠。","技成惜无用，徒党自标异。","方今重防边，朝右资阃寄。","何当下军书，壮士毕罗致。","上之为飞将，下亦备突骑。","绳度而梯缘，猛迅扫丑类。","不龟且可封，拍张亦高位。","此乃真千秋，名实两兼至。","毋终如处女，巾帼羞遗懿。","萧娘吕姥徒，虽贵愧将帅。","勖哉闾左人，同奋千秋志。"]},{"t":"黄田山行","f":"古风","c":["黄田山下寒飙肃，白发老妪当道哭。","问妪何事何愁蹙？","妪言有儿昨伐木，遇虎于山饱虎腹。","兹山往昔安樵牧，年来有虎伤人畜。","啸侣呼群食而宿，狼藉满山飞血肉。","犬豕未能餍所欲，近村噬人今五六。","谈者色变谁能逐？","空山辗转穷无告，残年自悲成老独。","嗟哉妪悲良足悲，惜尔不遇陈公网鳄时！","鳄杀儿，诉公知，公杀鳄，偿孤儿，鳄且可杀，虎何能为？","妪乎！","今则将安之？","妪悲妪徒悲，不如勿悲妪且归。","妪若不归虎将来，寒云黯黯白日颓。"]},{"t":"说潮五古十七首 其一","f":"五言古诗","c":["大江日夜东，流尽古今事。","安知古恶溪，今乃名善地。","严城滨江立，置守称郡治。","城北为金山，银山自西至。","日夜金银中，最难得廉吏。","西北气肃杀，害常寓于利。","韩山何峨峨？","隔江若相避。","千古侍郎亭，独无金银气。"]},{"t":"说潮五古十七首 其二","f":"古风","c":["一疏晨叩阙，夕贬大海南。","安知辟佛人，乃喜留僧谈。","苛论出后儒，公德宁遗惭。","蒙庄固多诬，妄说孔赞?。","拒墨见夷之，此意良足参。","颠也实异僧，在世为奇男。","悯其醉佛久，将为醒沈酣。","想闻公语时，心已怕瞿昙。","仆仆八月间，来往至再三。","惜乎公遗书，意未申所含。","留衣人其人，微旨谁能谙？","中天北斗光，夜照叩齿庵。"]},{"t":"说潮五古十七首 其三","f":"五言古诗","c":["文翁昔化蜀，相如为之师。","放诞犊鼻人，高文千秋垂。","韩公启潮教，赵子寔所资。","平生磊落况，见公所遗诗。","翻然大海南，持文弄珠嬉。","维海气为潮，变化生雄奇。","公文得其气，遂起八代衰。","况乃生其间，御气出骤驰。","径当走籍湜，上与公追随。","惜哉不从公，匿采沈海湄。","遗文遂零落，片羽世尚疑。","闇然凌云气，天子不能知。","教虽仅期月，潮人至今思。","蕉黄荔子丹，时荐天水祠。","何处下马陵，补镌有道碑？"]},{"t":"说潮五古十七首 其四","f":"五言古诗","c":["世变日以亟，文告不足申。","鳄鱼实冥顽，杀之非不仁。","遥遥千百年，继韩仅有陈。","南荒富物怪，不独鳄病人。","我闻有独鬼，凭城殃潮民。","昔有贤使君，为文告之神。","驱去旋复来，不能歼厥身。","用独已可惊，况乃用其群！","嚣然来鬼国，飞燐张双轮。","攫人以为餐，朋踞大海滨。","天威不肃杀，安得回阳春？"]},{"t":"说潮五古十七首 其五","f":"五言古诗","c":["藩镇与羽党，交起而亡唐。","嗟哉赞皇公，实为党魁伤。","斯人朋非党，将相材兼良。","已筑筹边楼，乃治平泉庄。","白马竟为厄，投身落南荒。","公当燕閒日，曾受丹砂方。","富贵而神仙，中道乃偕亡。","穷愁下恶水，扁舟岭梅香。","胡为未到潮，说潮神不扬？","海气今益昏，接天水茫茫。","时艰思将相，吊古心慨慷。","救世即真仙，服食安可常？","冷冷化象潭，金玉飞宝光。"]},{"t":"说潮五古十七首 其六","f":"五言古诗","c":["峨峨贵人山，下有贵人村。","桓桓陈将军，将乃出将门。","七闽拓为八，千里张军屯。","至今漳之人，庙祀丰鸡豚。","英灵及台岛，歌舞陈清樽。","我昔瞻遗像，冕旒抑何尊？","想见辟土时，仗钺群蛮奔。","抚绥闽越人，舆台皆感恩。","方今重阃寄，边海开雄藩。","海风自西来，山气日氤氲。","欲访山下人，或有将种存。"]},{"t":"说潮五古十七首 其七","f":"五言古诗","c":["宋南遂不北，有将而无相。","哀哉赵元镇，牢落南荒放。","误识猢狲王，谪禦鹦鹉瘴。","五年住潮州，间复遭谗谤。","此老终倔强，气作山河壮。","潮人爱居士，既去犹景向。","大书得全字，揭榜讲堂上。","遗址今何存？","烟蔓苦难访。","睒睒箕尾光，中夕劳怅望。"]},{"t":"说潮五古十七首 其八","f":"五言古诗","c":["莫大于恢复，莫雠于金虏。","莫急于用人，莫难于用武。","觥觥王尚书，谋国心何苦！","讲学张赵间，所得非小补。","论语致太平，况乃精易数。","惜哉公著述，零落无完部。","邦人重科第，巍访九衢树。","安知古名贤，风期足千古。","龟湖春水生，丙舍隐林坞。","欲读胡公铭，郁郁但黄土。","好为语畬民，松柏勿樵斧。"]},{"t":"说潮五古十七首 其九","f":"五言古诗","c":["道学倡东南，维潮亦兴起。","卓哉郑与郭，学为晦翁喜。","题诗飞泉岭，想见侍杖履。","晦翁生南度，志锐雪国耻。","登朝曾几日，侃侃论国是。","斯岂腐儒能？","何乃丛众毁？","宋亡于道学，妄者尚集矢。","安知翁之徒，磊落多国士。","斥逐未能用，炎精乃不祀。","统在道自尊，人心终不死。","鸣泉落汉声，至今震里耳。","平生愧失学，用晦契微旨。","何当搆拙窝，吾从子朱子。"]},{"t":"说潮五古十七首 其十","f":"五言古诗","c":["东山气清肃，中乃祠三忠。","我怀文文山，夙昔梦寐通。","携我烟霄间，俯瞰青濛濛。","乾坤正倾侧，玉简宁为功。","梦觉谨志之，浩然思无穷。","思公艰危日，九死来岭东。","哀歌沁园春，古木残阳红。","悲哉五坡岭，报国志未终。","岭梅最高品，著花冰雪中。","安知有南枝，向暖私春风。"]},{"t":"说潮五古十七首 其十一","f":"五言古诗","c":["南澳海上山，缥缈隔烟雾。","凄凉陆丞相，中有衣冠墓。","我昔舟过之，苍郁见宰树。","韩山拜公祠，正笏俨相度。","想见海中魂，哀痛失玉步。","东皋访遗裔，堂宇已非故。","斯祠亦就荒，俎豆日不具。","罔两尔何知？","英灵尚呵护。"]},{"t":"说潮五古十七首 其十二","f":"五言古诗","c":["郁郁金城山，上有千岁松。","峨峨马公墓，遇者怀孤忠。","全家碧血葬，遗碣苍苔封。","我来吊昔贤，林影斜阳红。","登山旷四瞩，遥接沧海东。","山石俨伏虎，铭者为俞公。","公当有明时，平倭著奇功。","载观没羽字，如见挥戈雄。","死者不复生，生者多庸庸。","至今沧海上，日夜生夷风。"]},{"t":"说潮五古十七首 其十三","f":"五言古诗","c":["南风吹不竞，洲上妾送郎。","北风多杀声，妾心为郎伤。","黯然天水碧，海色明斜阳。","悲歌平元曲，变徵何慨慷！","至今红螺洲，春草为不芳。","男儿不报国，愧死陈璧娘。"]},{"t":"说潮五古十七首 其十四","f":"五言古诗","c":["阳明昔抚虔，且战且讲学。","中离薛先生，举家侍讲幄。","犹子方登朝，死谏节已卓。","惜哉真铁汉，一疏官复削。","青衣拜节归，京尘手亲濯。","中离溪汤汤，中离山岳岳。","夜半闻钟声，谁欤实先觉。","维时讲良知，仁夫尤卓荦。","建策平交南，持节巩边朔。","斯诚阳明徒，边材独腾踔。","竟忤仇严归，风节更雄倬。","沧海今扬尘，边警喧鼓角。","不能事兵戎，何以兴礼乐？","斯材不可得，令我思悠邈。","斯材纵可得，欲出伤谣诼。","河流自西来，颓波日以浊。","三河河上坟，丰碑半残驳。"]},{"t":"说潮五古十七首 其十五","f":"五言古诗","c":["人生不得志，至为邑宰客。","客中太有人，埋没殊可惜。","有明板荡鞦，宗社墟闯逆。","草间偷活人，巍巍愧冠帻。","邑客尔何为？","孤生奋一掷。","忠烈本性生，宁复关通秝？","至今古潮阳，义士名赫赫。","名流井泉香，血化井泉碧。"]},{"t":"说潮五古十七首 其十六","f":"五言古诗","c":["英雄未遇时，牢落无不有。","铁丐尔何来？","孑身南北走。","问丐何姓名，仰天指其口。","陈平计固在，谁识相时久。","伟哉查孝廉，雪中呼与酒。","姓名不必知，知丐才不偶。","赠裘可以典，赠金可以受。","知我非常人，此意不可负。","一梦忽登天，大风吹尘垢。","双狮压腹背，金印忽在肘。","韩王得意事，第一报漂母。","施者虽无求，受者固不苟。","丐乎尔诚能，将迎亲拥帚。","昔时猎酒徒，衣绣此居守。","史祸为君脱，觞歌为君寿。","黄金不足报，报之以石友。","千古此两人，金石同不朽。","一曲雪中人，高唱铅山叟。"]},{"t":"说潮五古十七首 其十七","f":"五言古诗","c":["中原忽龙战，九族开闽关。","吾丘自固始，举族来莆田。","有宋鸿胪卿，数典乃吾先。","巍巍枢密公，于潮为始迁。","梅溪铭公墓，琴山霭春烟。","有子梅州守，归养娱亲前。","若赵若王古，投赠多诗篇。","想见与居游，论道皆名贤。","三传韶佥判，宗牒曾手编。","碧血老殉义，宋日沈虞渊。","维时方乱离，族散闽越间。","或近籍保昌，或远居琼山。","吾祖佥判弟，实隐鄞江边。","孙枝日以茂，江楚多绵延。","吾宗著石窟，一水梅潮连。","精舍寻金山，扫墓来故阡。","遥遥三十世，已阅七百年。","别派出承旨，棣萼春风联。","述祖非无人，谱牒多不全。","安知台海客，东风引回船。","居潮而言潮，稽古为悠然。","先畴尚可服，旧德犹能传。","东南此雄镇，保世心拳拳。"]},{"t":"春日游别峰寺 其一","f":"五言律诗","c":["不作参禅客，看山合此行。","移舟泊春麓，回磴瞰江城。","亭僻兼云憩，畬荒罢火耕。","隔林知寺近，花外度经声。"]},{"t":"春日游别峰寺 其二","f":"五言律诗","c":["山路到庵尽，依山见梵楼。","隔江屏远翠，走石笕潜流。","僧野能吴语，樵归答粤讴。","浮生閒半日，已共佛无愁。"]},{"t":"春日游别峰寺 其三","f":"五言律诗","c":["寺小群山合，林深万木春。","烟霞僧供养，香火佛生辰。","南国多游女，西方拜美人。","道旁求布施，凄绝是饥民。"]},{"t":"春日游别峰寺 其四","f":"五言律诗","c":["好静寻山去，山中笑佛忙。","不须杯珓祝，且證木樨香。","幢影摇春霭，钟声送夕阳。","匆匆下归棹，回首万峰苍。"]},{"t":"西上","f":"七言绝句","c":["西上扁舟客梦孤，浇愁村酒拨云沽。","春帆细雨梅州路，花落春山叫鹧鸪。"]},{"t":"杀鹗行","f":"七言古诗","c":["城根潮齧树半枯，天阴月黑啼训狐。","飞瞰屋山嚇黄小，徵凶召眚声呜呜。","潮州老守行春政，一纸朝颁磔枭令。","万户无声春柝严，夜伏空山依破镜。","嗟哉人中亦有鸮，东山风雨愁飘摇。","人间惜少恶溪檄，畀出浊水公为妖。","丹山凤去梧桐老，海上纷来九头鸟。","安得枉矢挂阴弓，风毛雨血沧溟东。"]},{"t":"闻海客谈澎湖事","f":"七言律诗","c":["绝岛周星两受兵，可怜蛮触叠纷争。","春风血涨珊瑚海，夜月燐飞牡蛎城。","故帅拜泉留井记，孤臣掀案哭雷声。","不堪重话平台事，西屿残霞怆客情。"]},{"t":"寄怀刘幼丹先生成都 其一","f":"七言律诗","c":["一麾出守向巴巫，谏草焚馀绾郡符。","中泽泛舟苏集雁，空山飞檄缚鸣狐。","五行灾异消江壅，八阵孤虚考石图。","落日秋城添别思，裤襦歌又起成都。"]},{"t":"寄怀刘幼丹先生成都 其二","f":"七言律诗","c":["玉垒铜梁气象雄，天涯西望忆文翁。","双鱼寄远江流上，五马班春井络中。","峡雨梦回夔子国，边尘愁入蜀王宫。","简书猿鸟应犹昔，筹笔终收上相功。"]},{"t":"寄怀刘幼丹先生成都 其三","f":"七言律诗","c":["眼底浮云变古今，西南通道极滇黔。","贾胡留恋成长技，天府丰饶启敌心。","窥井可能炎汉火，凿山谁遣受秦金？","蓬婆雪外三城在，重费哀时杜老吟。"]},{"t":"寄怀刘幼丹先生成都 其四","f":"七言律诗","c":["曾辱昌黎荐士篇，觚棱回首梦如烟。","宦游遥羡遨头宴，师说偏留琐尾笺。","邛竹通夷愁远道，岭梅破腊迫新年。","云龙韩孟何时会？","极目春风剑外天。"]},{"t":"春日杂诗 其一","f":"七言绝句","c":["乱红成阵满天涯，黯黯春帆细雨斜。","何处仙源容避世，赚人毕竟是桃花。"]},{"t":"春日杂诗 其二","f":"七言绝句","c":["雨丝风片暗清明，乡梦惊回杜宇鸣。","无限春愁似原草，到无人处更丛生。"]},{"t":"得颂臣台湾书却寄","f":"七言律诗","c":["故人消息隔乡关，花发春城客思閒。","一纸平安天外信，三年梦寐海中山。","波涛道险鱼难寄，城郭人非鹤未还。","去日儿童今渐长，灯前都解问台湾。"]},{"t":"寄怀维卿师桂林七首 其一","f":"七言律诗","c":["极目苍苍八桂林，春风迢递客愁深。","峰回独秀孤云远，江入相离别梦沉。","阅岁但增归鹤感，窥天难测剪鹑心！","刺船人去波涛急，凄绝成连海上琴。"]},{"t":"寄怀维卿师桂林七首 其二","f":"七言律诗","c":["鼍愤龙愁战气昏，东来应有未招魂。","平安梅峤迟双鲤，变幻桑田痛七鲲。","珠薏馀生安下泽，金瓯全局哭中原。","不曾竟落权奸手，归养林泉是国恩。"]},{"t":"寄怀维卿师桂林七首 其三","f":"七言律诗","c":["未能独乐赋园居，归洛温公讲学初。","八阵钤韬开虎豹，百家笺注谢虫鱼。","陈经共下宣尼拜，明箕旁求冉子书。","应念凤凰山下客，天涯寻约待脂车。"]},{"t":"寄怀维卿师桂林七首 其四","f":"七言律诗","c":["轮铁南交走电軿，苍梧西上又扬舲。","河山破碎羊肠险，楼阁空濛蜃气腥。","百粤安危关互市，五洲消息迫重溟。","谢公高卧应难稳，丝竹中年带泪听。"]},{"t":"寄怀维卿师桂林七首 其五","f":"七言律诗","c":["消耗雄心强自宽，家园春宴正承欢。","閒居境偶同潘岳，大事人终逊吕端。","落日闻鼙思上将，空山观弈感长安。","可能再为苍生出，莽莽神州海色寒。"]},{"t":"寄怀维卿师桂林七首 其六","f":"七言律诗","c":["十年剑佩记追随，鹿耳惊涛怆梦思。","铁马金戈春教战，锦袍银烛夜谈诗。","荒山镵影悲今日，残月钟声异昔时。","欲写哀歌寄天末，红棉飞遍越王祠。"]},{"t":"寄怀维卿师桂林七首 其七","f":"七言律诗","c":["牙旗玉帐卷东风，绝岛同归患难中。","故国愁春三月闰，遥天寻梦一星终。","铁衣绣雨蛮花碧，铜鼓椎潮劫火红。","袖手南洲观战局，山林未许老英雄。"]},{"t":"寄怀陈省三、许韫白游宦广州二首 其一","f":"五言律诗","c":["同作浮家客，多君尚宦游。","天涯惊物序，海色入乡愁。","鸡凤争栖日，龙蛇起陆秋。","东风千里目，怀远此登楼。"]},{"t":"寄怀陈省三、许韫白游宦广州二首 其二","f":"五言律诗","c":["谁可陈藩匹，吾尤念许虔。","几同岭外谪，等是汝南贤。","仙令丹砂地，蛮王左纛天。","何时渡江客，聚语永嘉年。"]},{"t":"潮州春思 其一","f":"七言绝句","c":["银花宝树影重重，衬出春光别样浓。","歌管满城灯似海，珠帘齐捲拜青龙。"]},{"t":"潮州春思 其二","f":"七言绝句","c":["南国消沉霸气雄，依然花草媚春风。","踏青齐上刘王埒，满地香勾印落红。"]},{"t":"潮州春思 其三","f":"七言绝句","c":["波光虹影接春城，泥梦时光半雨晴。","鸡卜庙边春市晓，隔帘香送卖花声。"]},{"t":"潮州春思 其四","f":"七言绝句","c":["送青水榭小陶然，零落春痕五十年。","老铁风流谁得似？","美人虹气惘尊前。"]},{"t":"潮州春思 其五","f":"七言绝句","c":["滑笏春波凤水香，春愁揉碎托瑶章。","桃花红雨梨花雪，不见题诗谢五娘。"]},{"t":"潮州春思 其六","f":"七言绝句","c":["曲院春风啜茗天，竹炉榄炭手亲煎。","小砂壶瀹新鹪嘴，来试湖山处女泉。"]},{"t":"次韵答陶生","f":"五言律诗","c":["戴晋无王猛，亡秦有李斯。","海鱼容自化，山鬼漫前知。","天道终难测，人心傥未离。","中兴由一旅，慎勿负心期。"]},{"t":"潮阳东山张、许二公祠为文丞相题沁园春词处，旁即丞相祠也，秋日过谒，敬赋二律 其一","f":"七言律诗","c":["夜半元旌出岭东，文山曾此拜双忠。","百年胡运氛何恶？","一旅王师气尚雄。","沧海梦寒天水碧，沁园歌断夕阳红。","荒郊马冢寻遗碣，秋草萧萧白露中。"]},{"t":"潮阳东山张、许二公祠为文丞相题沁园春词处，旁即丞相祠也，秋日过谒，敬赋二律 其二","f":"七言律诗","c":["石阙苔荒一径深，悲秋怀古此登临。","九州难画华夷限，万死思回天地心。","南客旅愁观海大，东山云气压城阴。","斜阳照起英雄恨，枯木寒鸦泪满襟。"]},{"t":"水帘亭","f":"七言古诗","c":["路转峰回叠磴遥，携筇人上翠微腰。","一亭嵌水古流曲，万石镵云秋气骄。","寒洞声喧山阁雨，大江目极海门潮。","岳阳胜概休相忆，横槊雄心郁未消。","同游陈艮山同年，时极谈洞庭之胜。"]},{"t":"岩泉义士祠","f":"七言律诗","c":["望帝魂归怨海棠，哀歌有客殉潮阳。","虞渊落日青衫泪，古井寒泉碧血香。","胜国衣冠留异代，秀才性命答先皇。","辘轳坏尽遗祠在，独拜秋衙老树旁。"]},{"t":"秋溪即目 其一","f":"七言绝句","c":["绿减蕉阴夜有霜，园柑林柿间丹黄。","扁舟坐爱秋溪晚，七曲屏山半夕阳。"]},{"t":"秋溪即目 其二","f":"七言绝句","c":["园林村舍接双堤，十里烟波一棹迷。","昨日斜阳今细雨，菊花时节过秋溪。"]},{"t":"对月书感 其一","f":"五言律诗","c":["明月出沧海，我家沧海东。","独怜今夜见，犹与故乡同。","丧乱山河改，流亡邑里空。","相思祗垂泪，顾影愧归鸿。"]},{"t":"对月书感 其二","f":"五言律诗","c":["把酒酹明月，客怀殊不欢。","流光当此夕，照梦到长安。","水落龙愁夜，山空鹤语寒。","中天宫阙迥，孤对岭梅看。"]},{"t":"次韵答王晓沧广文","f":"七言律诗","c":["漫说曾驱十万师，河湟收复竟无期。","秋风老骥思千里，故国鹪鹩困一枝。","醇酒悲凉公子泪，麻鞋奔走小臣诗。","劳君尚记虬髯传，心冷全输此局棋。"]},{"t":"次韵晓沧秋雨感怀","f":"七言律诗","c":["黯黯湘帘窣地垂，茂陵卧病枉寻思。","全军左袒无周勃，逐客留书有李斯。","孺子阴符空北面，故人高会罢南皮。","寻常车马今萧寂，酹酒秋原唤可儿。"]},{"t":"次韵答晓沧冬日见过草庐","f":"七言律诗","c":["罗雀门庭客退閒，漫天风雪入愁颜。","良朋命驾每千里，置厦庇人空万间。","满座酒尊怀北海，中年丝竹负东山。","与君怕作河桥别，衰柳飘零不可攀。"]},{"t":"书怀次晓沧韵","f":"七言律诗","c":["韩江凉讯接循梅，蚊语中宵尚聚雷。","万里南荒饶物怪，百年西域困边材。","土风变后多新调，家酿兵馀失旧醅。","解识婆娑弄珠意，海鸥从此不须猜。"]},{"t":"寄怀萧伯瑶布衣","f":"五言律诗","c":["绝代萧夫子，十年羁岭东。","牢愁满沧海，文字困英雄。","岁月磨头白，关山落照红。","相思渺烟水，天末怅冥鸿。"]},{"t":"十四夜月","f":"五言律诗","c":["四万八千户，将完玉斧功。","看成地球椭，摄起暮潮雄。","势已群星避，光先四海同。","山河终一统，留影大瀛东。"]},{"t":"十六夜月","f":"五言律诗","c":["上缺象微变，老阴光尚全。","何曾旧魄减，已与太阳偏。","圆相异前夕，寒芒犹满天。","嫦娥怨幽独，惆怅破瓜年。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其一","f":"七言绝句","c":["莽莽乾坤岁又周，尊前人减旧风流。","江山满目都非昔，不待人言意始愁。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其二","f":"七言绝句","c":["哀丝豪竹负中年，弃甲南来异锦旋。","十载风尘双鬓雪，剪灯情话更悽然。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其三","f":"七言绝句","c":["涕泪何曾为酒悲，干戈满地怆离思。","流亡南渡谁收恤？","愁说江淮唱义时。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其四","f":"七言绝句","c":["冠裳全异昔时观，筹保东藩力已殚。","海上贡貂稀閒使，诏书行不到三韩。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其五","f":"七言绝句","c":["风雪关河有梦还，海天漠漠对孤鹇。","暗香疏影寒溪月，万树梅花忆故山。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其六","f":"七言绝句","c":["海国诗坛旧主盟，登台坐对玉山清。","斐亭钟绝风流散，落日寒芜赤嵌城。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其七","f":"七言绝句","c":["热血填胸郁不凉，骑麟披发走南荒。","未酬戎马书生志，依旧吾庐榜自强。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其八","f":"七言绝句","c":["行踪曾为荔支留，琴剑西风记昔游。","独上朝台吊斜日，短衣匹马过南州。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其九","f":"七言绝句","c":["坠欢重续凤城西，坐久长河影渐低。","话到家山约偕隐，扁舟钓月老梅溪。"]},{"t":"忆旧述今，次晓沧见赠十绝句 其十","f":"七言绝句","c":["东南閒说未櫜弓，对酒豪情与昔同。","毕竟卢龙不曾卖，田畴宾客在无终。"]},{"t":"书事叠前韵","f":"七言古诗","c":["逍遥文字谢庄周，墨潘都成涕泪流。","凄绝三闾香草意，秋江人赋畔牢愁。","接天烽火迫残年，孤负铙歌制凯旋。","依旧元戎窦车骑，更无人与勒燕然。","何事悲天祗自悲，寒斋倚枕苦寻思。","书生怅作封侯梦，愁煞黄粱饭熟时。","都卢场辟万人观，民力东南近已殚。","不惜水衡钱浪掷，汉家恩赐结呼韩。","故人塞外有书还，惆怅江天对白鹇。","见说汉边瓯脱尽，秋风胡马满阴山。","黄河如带负前盟，满地洪流秋未清。","东海茫茫尽鱼鳖，可悲不独是彭城。","薤露声哀秋气凉，出关有客更投荒。","刊章钓尽甘陵党，流祸居然到吕强。","剑外音书屡滞留，西风愁说锦江游。","黄巾破败连三郡，更遣刘焉牧益州。","战云黯黯遍天西，江上行吟夕照低。","还向夔巫苦奔走，草堂空筑浣花溪。","漫诧榑桑旧挂弓，残棋欲著与谁同？","东风吟冷英雄泪，海外扶馀局未终。"]},{"t":"江楼秋感","f":"五言律诗","c":["不尽神州感，登楼客纵谈。","江声流日夜，秋色满东南。","宝集群胡市，尘蒙老佛龛。","金城摇落意，愁见柳毵毵。"]},{"t":"疾风甚雨，海山苍茫，遂有斯作","f":"七言律诗","c":["大阴黑入日华消，鳌足难安八极摇。","震地瓦声飞汉屋，雨空鞭血断秦桥。","蛟云覆海潮神泣，麟火烧天飓母骄。","满目鸿流方澒洞，童山无树与悬瓢。"]},{"t":"嗟哉行","f":"古风","c":["钢是铁所为，铮铮抑何美！","安知经火炼，竟化柔绕指。","噫吁乎嗟哉，行百者半九十里，晚节末路之难乃如此。","君不见扶风大儒宫中才子，当时果以投荒死，岂不贤名溢青史？","左手抚图右引剑，人生变节须臾耳。","适从何来集于此，逼人富贵徒为尔。","大衔赫赫书铭旌，相公竟葬咸阳矣。","邓绾好官曾几时？","人笑褚公今冷齿。"]},{"t":"黄香铁先生故宅有楼翼然，今斥为酒家矣，与客饮此，追话遗事，感赋六绝句 其一","f":"七言绝句","c":["西风吹散美人虹，七子才名冷粤中。","落日满城邻笛怨，酒垆人更吊黄公。"]},{"t":"黄香铁先生故宅有楼翼然，今斥为酒家矣，与客饮此，追话遗事，感赋六绝句 其二","f":"七言绝句","c":["为筑高楼贮绿珠，玉山醉倒遣花扶。","买丝合把吴公绣，如此怜才旷代无。"]},{"t":"黄香铁先生故宅有楼翼然，今斥为酒家矣，与客饮此，追话遗事，感赋六绝句 其三","f":"七言绝句","c":["草堂遗集尽风流，欲问诗中几酒楼。","依旧壶卢山色好，不妨才语谶千秋。"]},{"t":"黄香铁先生故宅有楼翼然，今斥为酒家矣，与客饮此，追话遗事，感赋六绝句 其四","f":"七言绝句","c":["青帘风紧酒微波，更遣吴姬压酒歌。","莫问黄鹂巷边宅，山塘杨柳倍愁多。"]},{"t":"黄香铁先生故宅有楼翼然，今斥为酒家矣，与客饮此，追话遗事，感赋六绝句 其五","f":"七言绝句","c":["赎宅何须费百千，楼头酒客正酣眠。","西州曾洒山丘泪，零落羊昙更十年。"]},{"t":"黄香铁先生故宅有楼翼然，今斥为酒家矣，与客饮此，追话遗事，感赋六绝句 其六","f":"七言绝句","c":["诗人老去半逃形，割宅空怜乞佛灵。","舍与酒徒还更胜，秋楼吊月酹刘伶。"]},{"t":"凤皇台放歌","f":"七言古诗","c":["凤皇山下凤皇水，流绕凤城水光紫。","东流分出凤皇洲，凤皇台踞洲上头。","我来登台揽八极，海阔天空足寒色。","凤皇已去不我留，落日栖鸦阵云黑。","我闻帝世鸣归昌，三层阿阁红云光。","黄农虞夏忽已没，遂令瑞羽逃南荒。","南荒祗今日生事，凤皇亦觉巢无地。","山空水寂遗此台，题额空悬凤皇字。","此字曾额金陵台，山东李白吟诗来。","长安不见见江水，浮云蔽日心何哀？","我生自是东海客，万里行吟海天碧。","无端又共青莲愁，凤去台空怆今昔。","人间谁识百鸟王？","故应丹穴犹孤翔。","怪毛邪羽世争诧，钦鴀误作真凤皇。","竹花不实桐叶冻，况复蛮中哀脯凤。","九霄夜踏五色云，白衣偶入才人梦。","荒洲芦荻风萧萧，鲤鱼吹浪寒湘桥。","若教帝囿念灵侣，龙宫零落愁江潮。","此台犹藉青鸟语，不惜千金费江渚。","群鸦早晚纷来朝，如此当时凤栖处。","凤皇山高生玉烟，凤皇之水流珠泉。","迢迢此台自终古，会见骖凤来群仙。"]},{"t":"题王晓沧广文鹧鸪村人诗稿 其一","f":"五言古诗","c":["晏坐深巷中，门少车马迹。","穷愁借诗遣，八极困挥斥。","故人有王子，时作坐上客。","王子之于诗，嗜酷久成癖。","饥寒不自念，渊响出金石。","昨持牛腰卷，示我平生获。","开卷王孟语，神似非刻画。","有时写酒意，几闯元亮席。","咏叹发长言，间竟入元白。","短章不经意，乃坠宋贤格。","寒斋把卷诵，斜阳澹将夕。","墙头数点山，时露海天碧。"]},{"t":"题王晓沧广文鹧鸪村人诗稿 其二","f":"五言古诗","c":["十年走吴越，万里行幽燕。","射策屡不售，剩有空囊悬。","一官落儋耳，渡海轩吟肩。","官卑人自高，学正斋乃偏。","炎天不飞雪，寒在先生毡。","松醪酌椰瓢，持以酹三贤。","此时诗益佳，骨格殊苍然。","岂惟吟土风，民瘼尤拳拳。","平生稷契怀，自信穷益坚。","曰归曾几时，世界屡变迁。","颇闻炎海中，奇甸垂蛟涎。","灶鼍不可梁，欲济何能前？","故山久栖迟，将老诗人间。","一卷聊自娱，堂堂惜流年。","手热海南沉，烟结郁不宣。"]},{"t":"题王晓沧广文鹧鸪村人诗稿 其三","f":"五言古诗","c":["何许鹧鸪村？","乃在梅花国。","花落梅子青，生为鹧鸪食。","鹧鸪工越吟，自唱南不北。","诗人发乡思，对尔泪沾臆。","归山岁之暮，寒巢敛羽翼。","手持鹧鸪诗，自写梅花侧。","京雒多黄尘，白日闇将匿。","海风吹九垠，雷雨大阴黑。","出门旷四瞩，天地满荆棘。","此时鹧鸪声，更唱行不得。","山田瘠可耕，且艺尔黍稷。","无以释穷愁，将诗慰食息。","岭南论流派，独得古雄直。","混茫接元气，造化入馋刻。","百年古梅州，生才况雄特。","宋公执牛耳，光燄不可逼。","堂堂黄与李，亦各具神力。","我欲往从之，自愧僵籍湜。","耆旧今凋零，思之每心恻。","诵君鹧鸪诗，令我恍动色。","梅花落空山，风雪途未塞。","展卷此留题，飞香洒寒墨。"]},{"t":"赠马总戎四首 其一","f":"五言律诗","c":["岭海古雄镇，将军今伏波。","威名铜柱大，战血铁衣多。","专阃屡推毂，忧时还枕戈。","北风近方劲，雨雪满关河。"]},{"t":"赠马总戎四首 其二","f":"五言律诗","c":["战气不可极，黯然沧海东。","九州谁健者！","万里靖边戎。","南海新除重，西林旧部雄。","黄金印如斗，终待立奇功。"]},{"t":"赠马总戎四首 其三","f":"五言律诗","c":["兵法在整暇，治书如治军。","纵横飞白字，变化点苍云。","壮采溢毫素，雄心逼篆分。","金山伏虎石，重见勒奇文。"]},{"t":"赠马总戎四首 其四","f":"五言律诗","c":["我亦相时者，结交多伟人。","平生好男子，不帝虎狼秦。","入世心肝古，谈兵天地春。","相逢各珍重，八极正风尘。"]},{"t":"题康步崖中翰出塞集七首 其一","f":"七言绝句","c":["出关人拜令公祠，南客才名塞上知。","赢得弓衣齐绣遍，春风杨柳小蛮诗。"]},{"t":"题康步崖中翰出塞集七首 其二","f":"七言绝句","c":["王大司空盖虎牙，英雄故里客停车。","渔阳突骑都非昔，惆怅云台说汉家。"]},{"t":"题康步崖中翰出塞集七首 其三","f":"七言绝句","c":["寻秋独上白狼山，涕泪思乡客袖斑。","匕首千金诗一卷，秋风匹马入榆关。"]},{"t":"题康步崖中翰出塞集七首 其四","f":"七言绝句","c":["凤阁新除侍从臣，彩毫还带塞垣春。","长安不少鸡林贾，都识能诗白舍人。"]},{"t":"题康步崖中翰出塞集七首 其五","f":"七言绝句","c":["十载幽并跃马行，久拚关吏笑书生。","云骧阁上闻鸡夜，风雪漫天梦柳城。"]},{"t":"题康步崖中翰出塞集七首 其六","f":"七言绝句","c":["九边烽火迫金台，客唱新添塞上哀。","更筑长城防不得，鹫章南下老羌来。"]},{"t":"题康步崖中翰出塞集七首 其七","f":"七言绝句","c":["展卷如闻敕勒歌，登临不负好诗多。","剪灯便作秋边色，夜半天风叫鴐鹅。"]},{"t":"题带经而锄图","f":"古风","c":["生不愿作读书万卷髯东坡，富贵竟付春梦婆；","黄州锄麦不得饱，儋州借笠空行歌。","亦不愿作白木长镵杜陵叟，饥驱茧足荒山走；","戴笠吟诗太瘦生，许身稷契终何有？","图中者谁笠盖头，岸然道貌清且修。","带经而锄偶然耳，宁必便与古人古事争千秋？","笠圆象天锄治地，手中之书道人事。","大布单衣不掩骭，独立苍茫岂无意？","萧萧落木寒岩冬，眼看雷雨回春容。","躬耕南阳诵梁父，莫道当今无卧龙。"]},{"t":"次韵和马总戎都龙纪胜四绝句 其一","f":"七言绝句","c":["猎猎西风旧战场，星碉云堡靖山梁。","纪功合有磨崖笔，曾受蛮师十万降。"]},{"t":"次韵和马总戎都龙纪胜四绝句 其二","f":"七言绝句","c":["万里滇云筑将台，班师久奏凯歌回。","九山天半青如故，又费将军倚马才。"]},{"t":"次韵和马总戎都龙纪胜四绝句 其三","f":"七言绝句","c":["战火连山夜击刁，边功人说霍嫖姚。","攻心毕竟推诸葛，万古威名倚碧霄。"]},{"t":"次韵和马总戎都龙纪胜四绝句 其四","f":"七言绝句","c":["飞车消息近何如，海上妖云誓扫除。","立马东南望天象，狼星魔燄眼中无。"]},{"t":"题画竹 其一","f":"五言绝句","c":["西风入幽篁，寒声何策策？","空山寂无人，落日秋痕碧。"]},{"t":"题画竹 其二","f":"五言绝句","c":["寒崖茁孤筱，见石不见地。","屈曲自盘根，难掩凌云气。"]},{"t":"题画竹 其三","f":"五言绝句","c":["拔地气不挠，参天节何劲？","平生观物心，独对秋篁影。"]},{"t":"题画竹 其四","f":"五言绝句","c":["此君在今日，大觉无不可。","风雨震诸天，空山自龙卧。"]},{"t":"闻河决题画竹","f":"古风","c":["瓠子尚未塞，淇园已全伐。","图中写此数竿秋，留向海天扫寒月。"]},{"t":"说剑堂集题词，为独立山人作","f":"古风","c":["剑龙出海辞延津，千年龙性犹难驯。","南天星斗避紫气，下有按剑独立之山人。","山人亦自号老剑，海山苍茫起光燄。","手收剑气入诗卷，万朵芙蓉剑花艳。","九霄太乙窥铸词，山人说剑当说诗。","诗中亦有东来法，七万里外称西师。","柏林城小诗坛大，西方美人坛下拜。","偶将剑诀传处女，花雨漫天动光怪。","归来香海修诗楼，山人说剑楼上头。","直开前古不到境，笔力横绝东西球。","山人之才无不可，但博诗名计何左？","岂知即诗亦难及，腾跃百家中有我。","只今耆旧无张黄，中原旗鼓谁能强？","粤诗独得古雄直，赖此巨刃摩天扬。","祗怜说剑无人解，老泪如潮溢沧海。","况复雷雨驱双龙，雌剑升天雄剑在。","吁嗟乎！","手提三尺歌大风，千秋绝唱隆准公。","青蛇袖里朗吟去，便须首数仙才雄。","公孙剑器语虽妙，祗许诗人诧高调。","此外异说空纷纭，十万横磨帝豝笑。","山人说剑剑胆粗，倚天手把玉鹿卢。","罗浮风雨自离合，空山卧抱诗龙珠。","竟隐珠光腾剑气，不顾世眼骇相畏。","繄余剑侠入道人，独抚瑶华解珍贵。","九龙城隔沧溟青，倚楼想见吟寒星。","何时携剑就说法，诸天云立群龙听。"]},{"t":"题风月琴尊图，为菽园作","f":"古风","c":["天风吹琴作变声，举尊喝月月倒行。","是何年少发奇想，海天漠漠扁舟横。","七弦谁遣补文武，九酝谁教变仪杜？","人间又见怀葛民，此琴此尊两太古。","古风不作古月沉，青天碧海愁人心。","诗中说酒十八九，寄愁更抚无弦琴。","琴斫寒崖老桐干，焦尾先闻爨下叹。","手中之尊何丹黄，谁知半作沟中断！","五湖久厌扁舟游，眼前突兀大九州。","有风月处便小泊，素琴自鼓青尊留。","君弦忽新臣弦旧，宫声顿哑数穷九。","舍风不禦月不捉，悲歌扣舷速呼酒。","此时之风雌不雄，月生月死天梦梦。","眼看海水忽四立，黑风驱月西回东。","振徽未忍琴碎玉，皇羲授我新翻曲。","一弹再鼓八风靖，月照瑶尊酒光绿。","携琴不上歌风台，纷纷猛士皆粗才。","即看赋月亦词赘，琐屑文寔张尊罍。","何如移尊酌沧海，夜半琴声行大蟹。","风轮转地月转天，万里云霓发奇彩。","呼风入琴月入尊，挥斥八极开天阍。","封姨对花不能虐，羿妻窃药不敢奔。","琴不必响泉作记，尊不必洼中铭字。","风月新常遍留印，席地幕天知许事。","谁欤图者酸道人，谁欤歌者仓海君。","闻歌九天下广乐，披图四海生酒云。","吁嗟乎！","男儿生当缴大风，射妖月，听奏钧天醉天阙。","下赞虞琴，鼓瑶陛，手酌衢尊万方悦。","不然吟风弄月亦可嗤。","径当浮海从宣尼。","海山学鼓猗兰操，百觚侍饮随凤嬉。","安能郁郁久居此，琴弦不张尊酒止。","惊风烈烈月睒睒，老我愁心大海水。","誓刃海若縻天吴，道人得我道不孤。","鸣弦著我酒船里，更写平分风月图。"]},{"t":"意溪访陆处士故居四首 其一","f":"七言绝句","c":["青山江上足烟霞，三百年前处士家。","比似西湖和靖宅，惜无人与种梅花。"]},{"t":"意溪访陆处士故居四首 其二","f":"七言绝句","c":["江头扶醉想高歌，菊径松庐野意多。","毕竟红尘无路隔，此溪曾过郭青螺。"]},{"t":"意溪访陆处士故居四首 其三","f":"七言绝句","c":["孤忠异代挹清芬，落拓生涯号隐君。","半亩墓田孙傍祖，菜花黄上相公坟。"]},{"t":"意溪访陆处士故居四首 其四","f":"七言绝句","c":["有客思寻片石谈，携筇来访旧精蓝。","寒芜漠漠江村夕，一角斜阳尺隐庵。"]},{"t":"小春泛舟北溪作","f":"七言绝句","c":["东风双桨打潮忙，漠漠墟烟送夕阳。","满载寒香北溪舫，梅花万树过官塘。"]},{"t":"莲花山吟","f":"七言古诗","c":["须弥山势趋中华，南来到海奇而葩。","不知何年碧海上，变现出此青莲花。","罡风吹花忽山立，山灵直取花为家。","群山万叶护花起，濛濛海气生青霞。","玲珑藕孔达海眼，中辟洞穴藏龙蛇。","偶传花妖骇世耳，时见仙药胎灵芽。","筠篮采药有山客，洞天琪草寻三桠。","山深往往遇灵境，异果或得安期瓜。","仙翁在山工造梦，纷纷鼠穴行牛车。","峰头布席作重九，幕天夜转星河斜。","人间万梦一夕聚，蝶愁蚁喜争相哗。","山灵醒眼观幻相，岁岁见惯宁嗟呀。","空青终古此山色，众星遍阅恒河沙。","或云文山昔登此，帝舟南望天之涯。","花中世界忽破碎，胡尘满眼空咨嗟。","力图南徼存帝统，荒山走处人争誇。","千年来者少此客，薜萝山鬼应相揶。","我归于潮已四载，看山未得探幽遐。","近游偶泛北溪棹，海风淅淅吹蒹葭。","苍山忽现菡萏色，直倚天半云难遮。","青鞋布袜意先往，泊舟径欲穷嵢岈。","千村万落出山下，山光青尽连桑麻。","一庵傍麓佛貌古，老僧云气生袈裟。","香厨石泉沁寒碧，松枝閒拾烹山茶。","绕庵微径转愈上，山农冬暖方烧畬。","岩苔半脱过虎迹，林香未散喧蜂衙。","于时身入莲花里，眼中山势尤盘拿。","天空海阔见真面，独立万古何槎枒！","登山未半全势出，祗觉雄秀无能加。","天池玉井俨在目，奇石离立如辟邪。","慨将灵秘贶我觌，此意既拜山灵嘉。","竟让文山凌绝顶，山灵亦恐吾疵瑕。","林间选石久坐眺，苍然暮色催栖鸦。","下山回望留后约，山月送客明归槎。","梦神趾离夕引我，洞天仙乐陈皇娲。","须臾緤马碧云顶，山河历历隆而洼。","云中缥缈瞰人世，目厌战气腾蛮蜗。","愿化莲花作台坐，海上与佛同结跏。"]},{"t":"岁暮与晓沧游西湖山作六首 其一","f":"七言绝句","c":["城外西湖湖上山，嵌空楼观古崖间。","满城乞尽仙人药，留取梅花伴客閒。"]},{"t":"岁暮与晓沧游西湖山作六首 其二","f":"七言绝句","c":["紫竹庵空剩碧漪，游人还说放生池。","空明一片湖心水，枯柳残荷太守碑。"]},{"t":"岁暮与晓沧游西湖山作六首 其三","f":"七言绝句","c":["古洞沉沉访老君，换鹅谁写五千文。","一丸泥塞函关路，花冷青牛卧石云。"]},{"t":"岁暮与晓沧游西湖山作六首 其四","f":"七言绝句","c":["刘王埒近草芊芊，满目江山荡夕烟。","修路莫寻南汉记，空崖苔蚀兔丝年。"]},{"t":"岁暮与晓沧游西湖山作六首 其五","f":"七言绝句","c":["一角寒岚照碧波，园亭无奈废兴何！","七分荒冢三分庙，如此湖山鬼占多。"]},{"t":"岁暮与晓沧游西湖山作六首 其六","f":"七言绝句","c":["十万人家山作屏，濛濛入望海云青。","更无老铁风流笔，冷坐乘风待月亭。"]},{"t":"小除日与晓沧游开元寺，遂西过叩齿庵，傍城根园池抵南门，登楼晚眺作 其一","f":"七言绝句","c":["江城春气晓冥冥，腊鼓声中酒未醒。","扶醉寻碑唐代寺，碧桃花蚀石幢经。"]},{"t":"小除日与晓沧游开元寺，遂西过叩齿庵，傍城根园池抵南门，登楼晚眺作 其二","f":"七言绝句","c":["叩齿庵空客话禅，东风酿暖祭诗天。","竟输岛佛才名瘦，懒把黄金铸大颠。"]},{"t":"小除日与晓沧游开元寺，遂西过叩齿庵，傍城根园池抵南门，登楼晚眺作 其三","f":"七言绝句","c":["满城忙趣迫年终，翻笑禅门兴俗同。","小结閒缘谈半日，种花园叟钓鱼翁。"]},{"t":"小除日与晓沧游开元寺，遂西过叩齿庵，傍城根园池抵南门，登楼晚眺作 其四","f":"七言绝句","c":["眼看烂漫好年光，城上高楼野趣长。","斜日细吟南涧句，蓣藷花紫菜花黄。"]},{"t":"岁除日与晓沧登金山","f":"七言律诗","c":["一年三百六十日，祗馀此日谁能閒！","城人十万閒者两，短衣杖策登金山。","寒光万里动西极，青山也作岁除色。","中原一发苍茫间，独有雄心除不得。"]},{"t":"除夕示五弟时甫三绝句 其一","f":"七言绝句","c":["江城残腊客思亲，爆竹声中历又新。","忽忆四年前此夕，柏庄家宴满堂春。"]},{"t":"除夕示五弟时甫三绝句 其二","f":"七言绝句","c":["草草杯盘饯岁筵，莫嫌风味逊从前。","满城多少贫儿屋，难过钱荒米贵年。"]},{"t":"除夕示五弟时甫三绝句 其三","f":"七言绝句","c":["一尊今夕弟兄同，镜里愁颜醉转童。","自笑呆痴老难卖，横戈还想立奇功。"]},{"t":"绮疏","f":"七言律诗","c":["绮疏面面拓云蓝，吹彻银笙酒半酣。","倾国名花春第一，新年眉月夜初三。","吉金铸镜镌心语，暖玉敲枰试手谈。","烂熳东风桃杏嫁，满天红雨梦江南。"]},{"t":"吴秀才赠水仙花赋谢 其一","f":"七言绝句","c":["生花妙手夺春工，莫笑金银气太浓。","网得西施肯相赠，风裳水佩出吴宫。"]},{"t":"吴秀才赠水仙花赋谢 其二","f":"七言绝句","c":["矾弟兰兄总绝尘，入门便作十分春。","珊珊一片凌波影，更遣陈王赋洛神。"]},{"t":"为林生题拜梅图 其一","f":"七言绝句","c":["冰雪空山绝点尘，王维笔下妙生春。","男儿自保黄金膝，除却梅花不拜人。"]},{"t":"为林生题拜梅图 其二","f":"七言绝句","c":["逋仙风格本来尊，冷抱梅花自闭门。","只合三公向妻跪，不曾轻去谒刘孙。"]},{"t":"春寒","f":"七言绝句","c":["宝帐春寒夜不眠，卸妆入坐绮窗前。","玉屏花影珠帘月，一勺香泉浸水仙。"]},{"t":"雨中春望","f":"七言绝句","c":["骤暖还寒昨夜风，江城东望晓溟蒙。","不知春色在何处？","三十二峰烟雨中。"]},{"t":"元夕无月感赋 其一","f":"七言绝句","c":["江楼听雨散春声，家国茫茫百感生。","四载故山今夜月，不曾流照到金城。"]},{"t":"元夕无月感赋 其二","f":"七言绝句","c":["火树银花句懒吟，望京楼畔客愁深。","他年见月应回忆，寒雨春灯此夕心。"]},{"t":"送王晓沧之汀州","f":"七言绝句","c":["韩江别思满扁舟，春水新添五尺流。","一路青山送眉妩，鹧鸪声里到汀州。"]},{"t":"赠柳参军","f":"七言绝句","c":["一官留滞凤凰城，十载能诗旧有名。","江上新词传唱遍，晓风残月柳耆卿。"]},{"t":"和平里行","f":"七言古诗","c":["莲花峰头望帝舟，双忠祠前吟古愁。","日星河岳浩然气，大笔更向蚝墩留。","里人敬忠宝遗字，未入南中金石志。","我来下马读残碑，吊古茫茫满襟泪。","三闽四广何苍黄，胡尘上掩天无光。","力支残局赖丞相，间关万里来潮阳。","双髻峰高练江曲，长桥小市驻行纛。","破碎河山小补完，警枕中宵睡初熟。","于时人心方翕然，盗魁擒馘尸军前。","四方响应大和会，祥兴天子平胡年。","里改今名定斯义，岂为南中好天气！","幕府流离半死生，可惜无人述公意。","更取千秋名镇名，军中凤叔为留铭。","当时赤手扶天意，誓欲畀勿东南倾。","五坡岭边鼓声死，丞相北行残局已。","复壁犹藏痛哭人，此邑民原多义士。","东山谁筑丞相祠？","英风如见提师时。","手酹睢阳守臣酒，口吟杜陵野老诗。","残疆更祝和平福，自为里人画此幅。","墨沈淋漓玉带生，镌上穹碑石痕绿。","屡经劫火碑难烧，碑趺赑屃临虹桥。","江流桥下天水碧，行客能言炎宋朝。","大峰北宋公南宋，凄凉君国弥增恸。","此桥曾过勤王师，斜日寒潮满桥洞。","鲁戈回日难中天，潮生潮落穹碑前。","粤潮有信杭无信，空嗟三日签降笺。","南来未尽支天策，碧血丹心留片石。","壮哉里门有此观，大书三字碑七尺。","字高二尺奇而雄，笔力直迫颜鲁公。","旁书九字庐陵某，过者千古怀孤忠。","碑阴何人识何语？","询之里人不能举。","独有公书永不磨，卓立四朝阅风雨。","蚝何为者避公书，帖然徙去如鳄鱼。","尔虽么䯢识忠义，愧彼卖国降虏奴。","安得石阑周四角，上覆以亭备榱桷。","公书纵道神物护，亦恐年深或斑剥。","平生我忝忠义人，浪萍还剩浮沉身。","壶卢墩畔思故里，义师散尽哀孤臣。","凌风楼头为公吊，振华楼头梦公召。","眼前突兀见公书，古道居然颜色照。","斗牛下瞰风云扶，愿打千本归临摹。","何时和平真慰愿，五洲一统胡尘无。"]},{"t":"牡丹诗二十首 其一","f":"七言绝句","c":["倚竹何人问永嘉，满城锦幄护香霞。","自从谢客标名后，已占春风第一花。"]},{"t":"牡丹诗二十首 其二","f":"七言绝句","c":["何事天香欲吐难，百花方奉武皇欢。","洛阳一贬名尤重，不媚金轮独牡丹。"]},{"t":"牡丹诗二十首 其三","f":"七言绝句","c":["唤回三十六宫春，万种千名色顿新。","种遍长安无旧品，果然单父是花神。"]},{"t":"牡丹诗二十首 其四","f":"七言绝句","c":["一捻留红笑玉环，渔阳鼙鼓迫潼关。","天教仙鹿先衔去，不许看花到荦山。"]},{"t":"牡丹诗二十首 其五","f":"七言绝句","c":["花发唐宫御宴稀，娇红如泣怨斜晖。","临轩莫念元舆赋，更遣君王泪满衣。"]},{"t":"牡丹诗二十首 其六","f":"七言绝句","c":["春光占断几番风，更道花开顷刻中。","谁信泥金书碧瓣？","岭云关雪谶文公。"]},{"t":"牡丹诗二十首 其七","f":"七言绝句","c":["赏花人倚玉阑干，丽质天生欲品难。","雪岭墨池才子笔，枉教来比李端端。"]},{"t":"牡丹诗二十首 其八","f":"七言绝句","c":["玛瑙盘盛金镂杯，重看浓艳锦城开。","尚书只惯修降表，底事和酥赠客来？"]},{"t":"牡丹诗二十首 其九","f":"七言绝句","c":["带酒朝看国色酣，群芳管领此花堪。","梃边惊艳降王长，无复强词说小南。"]},{"t":"牡丹诗二十首 其十","f":"七言绝句","c":["赏春不惜醉婆娑，琼岛奇花此一窠。","留与子孙看亦得，偏教眼福老来多。"]},{"t":"牡丹诗二十首 其十一","f":"七言绝句","c":["汴京纳土说钱王，陌上看花兴未忘。","留得家风忠孝在，相公裁表进姚黄。"]},{"t":"牡丹诗二十首 其十二","f":"七言绝句","c":["漫买胭脂乱抹涂，吴公精鉴世间无。","花阴一线猫儿眼，妙绝谁知午景图？"]},{"t":"牡丹诗二十首 其十三","f":"七言绝句","c":["锦绣天街盆景新，十分红闹帝京尘。","人间富贵终嫌骤，便作堂花不耐春。"]},{"t":"牡丹诗二十首 其十四","f":"七言绝句","c":["看到奇花眼欲迷，不须惊走笑山妻。","天津桥上闻鹃客，忍断残香付马蹄。"]},{"t":"牡丹诗二十首 其十五","f":"七言绝句","c":["五云捧出缕金黄，欲遣陈州胜洛阳。","自辟花中新世界，可怜人枉说妖祥。"]},{"t":"牡丹诗二十首 其十六","f":"七言绝句","c":["绝代才人集影园，宫袍黄染墨香温。","扬州风月群花笑，争捧金罍上状元。"]},{"t":"牡丹诗二十首 其十七","f":"七言绝句","c":["爱教花里筑妆楼，霞彩云芳艳影留。","传与姑苏新样好，春风扶上美人头。"]},{"t":"牡丹诗二十首 其十八","f":"七言绝句","c":["花落花开怨别离，锦屏人更惜芳时。","珊珊亭畔寻香梦，重唱风流玉茗词。"]},{"t":"牡丹诗二十首 其十九","f":"七言绝句","c":["东来花种满西园，谁与乘槎客细论。","从此全球作香国，五洲花拜一王尊。"]},{"t":"牡丹诗二十首 其二十","f":"七言绝句","c":["漫说中人赋十家，春风争买走香车。","梦中彩笔新传得，要代欧阳更品花。"]},{"t":"题画","f":"七言绝句","c":["两山眉黛送春娇，十里平湖晓长潮。","红入桃花青入柳，东风人立赤阑桥。"]},{"t":"西园重见诗畸刻本，为之黯然","f":"七言律诗","c":["斐亭钟断阵云阴，杳杳相思八桂林。","一卷琳琅才子语，十年锁钥老臣心。","传人妄计先灾木，割地谁知竟赂金。","重检残编春院夕，五更红烛泪痕深。"]},{"t":"拜大忠祠回咏木棉花 其一","f":"七言律诗","c":["枯木寒鸦吊大忠，力回阳九气熊熊。","化身待挽芙蓉劫，洒血疑开杜宇宫。","铜鼓哀歌春庙古，铁椎奸魄满庵红。","扫除冰雪持炎运，合率群花拜祝融。"]},{"t":"拜大忠祠回咏木棉花 其二","f":"七言律诗","c":["阳枢星化木森森，撑拄南天夜不阴。","赤制待除花九锡，紫琼分琢玉千林。","五云拥护朝天面，万烛光明坠地心。","锦绣江山春一统，西台朱鸟莫哀吟。"]},{"t":"游白牛岩二首 其一","f":"七言绝句","c":["有客婆娑大海南，白牛岩畔访禅庵。","颠僧老死文公去，细雨松花扑石龛。"]},{"t":"游白牛岩二首 其二","f":"七言绝句","c":["海色山光文起楼，才人遗墨壁间留。","春林石气漾寒碧，落日倚栏云满头。"]},{"t":"乡间人有误以予为武进士者，戏纪以诗","f":"七言律诗","c":["书生面目太槎牙，太息封侯念已差。","漫说旧衔同武爵，颇闻外论比文虾。","老兵欲唤桓元子，故将谁知李左车。","刁斗能铭矛解用，丈夫何事愧刘巴！"]},{"t":"废园","f":"七言律诗","c":["林泉萧瑟是谁家，人去庭空感物华。","病树有枝巢贱鸟，荒池无水俸私蛙。","黄枯秋圃公孙橘，红瘦春篱姊妹花。","头白园丁更惆怅，残畦种菜老生涯。"]},{"t":"寄怀林生葵阳","f":"七言律诗","c":["东风吹客送吟鞭，桃李满城花正妍。","晕碧楼台沧海气，踏青裙屐丽人天。","梦回京国八千里，唤起神童五百年。","欲托春心惟望帝，不须重问月公禅。"]},{"t":"乞萧生作东山丝竹图 其一","f":"七言绝句","c":["但无丝竹有东山，要乞丹青补黛鬟。","莫被比邻文信国，满前姬侍笑儒酸。"]},{"t":"乞萧生作东山丝竹图 其二","f":"七言绝句","c":["中年哀乐宜丝竹，此意惟应逸少知。","恰好流觞逢曲水，管弦添写在山时。"]},{"t":"游西岩作 其一","f":"七言律诗","c":["路曲林幽别有天，出城岩翠接春田。","孤云出树疑残塔，大海回潮应伏泉。","扫墓人来东晋族，开山僧说盛唐年。","宝通药地传灯冷，零落南宗六祖禅。"]},{"t":"游西岩作 其二","f":"七言律诗","c":["沧洲东望昼冥冥，一角荒山仗佛灵。","夹径花霏连理树，断碑苔没读书亭。","六时钟磬林光碧，万里帆樯海气青。","坐对石头无法说，将诗吟与蛰龙听。"]},{"t":"得伯质太守书，知乞归未得，赋寄","f":"七言律诗","c":["一载仍容借寇恂，双旌山畔粤江春。","封章郑重循良绩，归计迟留畎亩身。","海舶利成旁落势，陆梁风起近边民。","艰难正仗匡时手，未许扁舟理钓纶。"]},{"t":"答潘兰史、丘菽园用王晓沧韵","f":"七言律诗","c":["龙血玄黄战正酣，海山何处筑诗龛？","权书枉著苏明允，心史空留郑所南。","斫地有歌哀骥老，攀天无路阻鸾骖。","蛮云黯黯愁思阔，聊写新词当麈谈。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其一 紫藤花馆","f":"七言绝句","c":["名园高馆最玲珑，藤影花光护绮栊。","璎珞四垂珠万串，一春长住紫云中。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其二 碧漪池","f":"七言绝句","c":["海色天容共一池，群花寒浸碧涟漪。","临流化尽春衫影，绝似唐宫浣露时。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其三 流春桥","f":"七言绝句","c":["垂虹影落碧波寒，流尽春花春欲阑。","独有春愁流不去，中原一发倚阑看。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其四 涵碧亭","f":"七言绝句","c":["收尽云光夜见星，临波面面敞珠棂。","眼中碧海无风浪，人卧乾坤一草亭。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其五 淡白径","f":"七言绝句","c":["漠漠梨云出梦迟，春风花径独行时。","别开冷艳幽香境，来写吾家左掖诗。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其六 壁花轩","f":"七言绝句","c":["琴酒名园载月过，开轩花气漾文波。","不妨四立相如壁，消受芙蓉艳福多。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其七 浣风台","f":"七言绝句","c":["雄风赋罢气飞腾，还似兰台快共登。","沧海不尘天若洗，观星人立最高层。"]},{"t":"丘园八咏为顺德龙山家仲迟驾部作八首 其八 绛雪楼","f":"七言绝句","c":["天半寒光幻绮霞，倚楼人正赋尖叉。","屏风写出赚山景，万树燕支六出花。"]},{"t":"东山春思 其一","f":"七言绝句","c":["春泉流涧晓潺潺，古院无人尽日閒。","落尽碧桃归未得，望仙桥畔望家山。"]},{"t":"东山春思 其二","f":"七言绝句","c":["云壑风泉入画图，水帘亭畔客怀孤。","海桐花发山桑熟，细雨春林叫鹁鸪。"]},{"t":"春暮游揭阳作 其一","f":"七言律诗","c":["三月春江放棹行，水田漠漠万车声。","空山废堠秦人戍，落日平芜汉代城。","印铸彻侯封粤令，帆回海道阻闽兵。","古怀赢纵东风目，散尽閒愁看野耕。"]},{"t":"春暮游揭阳作 其二","f":"七言律诗","c":["玉滘潮生打桨忙，绿阴夹道水松凉。","北来岭势连山越，南徼民风故陆梁。","乔木村居名将冷，落花坟上美人香。","江城如画吴中景，愁入昏昏海气黄。"]},{"t":"鮀浦喜晤萧伯瑶夜话","f":"七言古诗","c":["惊风倒吹瘦蛟舞，海底鲛人泣珠雨。","客楼一夕千秋语，憧憧灯影须眉古。","天涯等是沦落人，笔花黯淡愁不春。","不堪更诉虫沙劫，九州举目皆鲲身。","长剑倚天悲未遇，流布人间剩诗句。","乾颠坤摇卧不稳，睡龙夜瞰风云气。"]},{"t":"得伯瑶和章叠前韵","f":"七言古诗","c":["华灯夜照柘枝舞，满地香云散花雨。","豪竹哀丝送眉语，红氍毹捧宫妆古。","安知座有伤心人，东风吹律声不春。","满堂花作可怜色，浩劫欲化无边身。","归倚客窗愁目遇，震魄惊魂吟大句。","舍兵无法向人说，大九州方沉战气。"]},{"t":"赠夏季平殿撰二首 其一","f":"七言律诗","c":["周南留滞得归迟，三策天人圣主知。","四海喜闻新政日，六街争看状元时。","小臣下土纵横涕，世事长安反覆棋。","回首觚棱俱远梦，天涯相对怅秋期。"]},{"t":"赠夏季平殿撰二首 其二","f":"七言律诗","c":["海天龙雨走惊雷，黯黯蛮云瘴不开。","万里梦回庄蹻国，千金装问赵佗台。","本无温饱平生志，待济艰难旷代才。","约吊文山酹尊酒，世忠亭畔看潮来。"]},{"t":"风雨中与季平游东山，谒双忠、大忠祠，兼寻水帘亭、紫云岩诸胜，叠与伯瑶夜话韵","f":"七言古诗","c":["万石捧云郁飞舞，神龙出布状元雨。","寒鸦无语杜鹃语，心悯大忠来吊古。","等是金鳌背上人，悲歌重写沁园春。","河山一统初破碎，繄余更属浮萍身。","零丁洋边与君遇，灵威庙前诵遗句。","同揩远目青山间，一发中原夕阳气。"]},{"t":"叠韵答夏季平见赠","f":"七言古诗","c":["群胡竞作天魔舞，㣼利天宫下兵雨。","空山月黑翁仲语，欲灭皇风扫三古。","满目女娲抟土人，濛濛梦入蟪蛄春。","直甘大地作布施，何惜恒河沙等身？","是何世界今顿遇，一切法消偈四句。","相期出挽阳九厄，日轮天转黄人气。"]},{"t":"柳汀赠诗述及台事，叠韵答之","f":"七言古诗","c":["东海饿蛟作人舞，万里炮云挟枪雨。","相公款关奉盟语，玉斧一挥恨终古。","天南流落忠义人，披发呼天天不春。","臣军请缨云请剑，疏草劫烬馀吟身。","伤心岂独士不遇，涕泪花前吟赠句。","妇人醇酒足此生，老天不喜英雄气。"]},{"t":"游东岩叠韵答柳汀","f":"七言古诗","c":["留衣废亭石云舞，卓锡古泉冷飞雨。","持赠山僧有才语，畀与大颠共千古。","渡海来为南粤人，五年伤别兼伤春。","生似昌黎厄磨蝎，终日坎壈缠其身。","名山幸与名贤遇，留镇山门藉诗句。","千年重出起衰手，睒睒中天北斗气。"]},{"t":"叠韵赠林生","f":"七言古诗","c":["庭院无人燕交舞，手订别风證淮雨。","渊渊如闻金石语，皋比兀坐形容古。","君是羲皇以上人，胸中碑板蕴古春。","侍儿亦作古妆束，翩翩玉立何长身？","练浦秋风始君遇，一春屡诵惊人句。","手书直迫瘗鹤铭，上皇山樵饶道气。"]},{"t":"祝文信国公生日日，得伯瑶风雨中见怀诗答寄，叠前韵 其一","f":"七言古诗","c":["七忠祠前陈羽舞，闪闪云旗降风雨。","荒山夜出英灵语，如闻此会足千古。","谁其尸者狮山人，万里来话琼林春。","会者齐吴楚闽粤，来祝带血啼鹃身。","此会惜君未得遇，五日江风阻诗句。","西台莫唱朱鸟吟，东山尚蟠冷龙气。"]},{"t":"祝文信国公生日日，得伯瑶风雨中见怀诗答寄，叠前韵 其二","f":"七言古诗","c":["痴龙兀挟云阵舞，海天十日九风雨。","脉脉隔江不得语，冒雨寻僧禅趣古。","何期海上听潮人，心花怒发天地春。","豪吟杜陵洗兵马，天涯慰我哀时身。","开缄喜若与君遇，顿释愁怀诵佳句。","云阴蔽天无斗牛，漫倚楼阑看剑气。"]},{"t":"游白牛岩用前游韵 其一","f":"七言绝句","c":["云气溟蒙大海南，看山人再访禅庵。","泉声冷尽高僧锡，满地花香雨一龛。"]},{"t":"游白牛岩用前游韵 其二","f":"七言绝句","c":["万方多难此登楼，眼底云山翠欲流。","欲吊红棉旧吟客，落花飞絮满江头。"]},{"t":"白牛岩次季平韵","f":"七言律诗","c":["寺楼悬踞最高层，路转松阴百级升。","山为出云常作雨，人虽辟佛不嫌僧。","散花丈室泉声古，落日空江练色澄。","我自擎天拜柱石，爱他风骨独崚嶒。"]},{"t":"金顶寺赠僧能意二首 其一","f":"七言律诗","c":["但有名僧山便灵，宝通禅派未凋零。","诸天花雨蒲团坐，大海潮音贝叶经。","古寺寻碑金顶冷，空岩说法石头听。","重来看卓泉边锡，云掩寒关佛火青。"]},{"t":"金顶寺赠僧能意二首 其二","f":"七言律诗","c":["浴佛才过客此游，禅花开落剧清幽。","西来劫火遮灵鹫，南下宗风衍白牛。","文字前因僧有幸，沧桑满眼佛无愁。","乾坤何处藏吾拙，戎马书生句又留。"]},{"t":"游西山海潮岩用前游韵二首 其一","f":"七言律诗","c":["梅雨初过浴佛天，寺门香拥稻花田。","七层金碧消砖塔，万里风潮长石泉。","楼观总含沧海气，江山还属太平年。","劫尘屡换名僧尽，唤起閒云与话禅。"]},{"t":"游西山海潮岩用前游韵二首 其二","f":"七言律诗","c":["一片斜阳入渺冥，迩来人更访山灵。","江帆叶叶收前浦，野鸟时时下古亭。","满院吉祥花气紫，半林连理树阴青。","归筇如带西来意，风送钟声下界听。"]},{"t":"叠韵答夏季平二首 其一","f":"七言律诗","c":["旧恨新愁满海天，封侯休说面如田。","凤饥何计翔千仞，龙蛰真忧到九泉。","白马潮来悲往事，红羊劫换感流年。","西山薇蕨无人问，且话莲花六叶禅。"]},{"t":"叠韵答夏季平二首 其二","f":"七言律诗","c":["寥空双鹤破苍冥，睥睨千秋佛乞灵。","霸国山川吟粤峤，翰林风月忆柯亭。","身经忧患先头白，名著文章愧汗青。","十万军声来夜半，问潮泉畔且同听。"]},{"t":"与季平访柳汀，用季平赠僧能意韵","f":"五言律诗","c":["入室古芳满，庭花连理枝。","乡音脆吴语，风格拗唐诗。","远算就时见，深尊劝客持。","千金载西子，少伯是吾师。"]},{"t":"叠前韵歔赠柳汀","f":"五言律诗","c":["冷抱香云卧，骄人花一枝。","才名高顾怪，音节变吴诗。","客至家姬出，宵征阃律持。","城南树精老，唐突化人师。"]},{"t":"与季平、柳汀饮东山酒楼 其一","f":"七言绝句","c":["岩翠潮光共一楼，江山今日顿风流。","诸天洗出云雷气，供养群仙坐上头。"]},{"t":"与季平、柳汀饮东山酒楼 其二","f":"七言绝句","c":["六百年中电掣回，东山又见状元来。","平生心醉文丞相，莫问他人借酒杯。"]},{"t":"与季平、柳汀饮东山酒楼 其三","f":"七言绝句","c":["花气濛濛酒半醺，掀髯休笑故将军。","谈兵杜牧狂言甚，只向尊前念紫云。"]},{"t":"与季平、柳汀饮东山酒楼 其四","f":"七言绝句","c":["浣花天气雨初晴，也当鳌头宴锦城。","一片千秋七星石，水帘亭畔看题名。"]},{"t":"东山酒楼次柳汀韵","f":"七言律诗","c":["第一仙人数宋郊，羊裘更说子陵高。","天公速客先风雨，山寺开门受海潮。","游迹待传文上石，边愁无计锈生刀。","狂吟且共楼头醉，酒虎诗龙各自豪。"]},{"t":"季平为书“澹定村”三大字、并书赠“马来西极、龙卧南阳”二语为楹帖赋谢 其一","f":"七言绝句","c":["三字千秋澹定村，大书留处万灵尊。","他年乞与和平里，同證名贤雪爪痕。"]},{"t":"季平为书“澹定村”三大字、并书赠“马来西极、龙卧南阳”二语为楹帖赋谢 其二","f":"七言绝句","c":["下笔真成千丈强，更将龙卧许南阳。","何当窥井重炎火，天马西来汉道昌。"]},{"t":"雨中与季平待柳汀不至，戏寄 其一","f":"七言绝句","c":["暮雨潇潇客未行，吴娘别后最关情。","玉关杨柳无消息，惆怅高楼夜笛声。"]},{"t":"雨中与季平待柳汀不至，戏寄 其二","f":"七言绝句","c":["东风吹絮点前汀，绿满龙津旧酒亭。","恼乱儿童无处促，柳花飞去作浮萍。"]},{"t":"雨中与季平待柳汀不至，戏寄 其三","f":"七言绝句","c":["无奈城南老树何，柔花弱蔓引交柯。","精灵倘识神仙过，来听江楼倚剑歌。"]},{"t":"得柳汀答诗，知方卧病，次前韵三首 其一","f":"七言绝句","c":["海天漠漠云不行，淫霖十日难为情。","何堪风雨怀人夕，更听猿啼三峡声。"]},{"t":"西园雅集作 其一","f":"七言绝句","c":["一时佳话遍江城，海上喧传击钵声。","莫怪霓裳众仙集，洞天新署小朱明。"]},{"t":"西园雅集作 其二","f":"七言绝句","c":["平地楼台气更奇，半閒遗址草迷离。","待将银汉金茎笔，重赋升庵八咏诗。"]},{"t":"西园雅集作 其三","f":"七言绝句","c":["难得平原十日留，岭梅初熟麦方秋。","剧惭秦缶乌乌语，唱向延晖楼上头。"]},{"t":"西园雅集作 其四","f":"七言绝句","c":["天上文昌气似珠，吟声万里合笙竽。","黔云台雨姑苏月，写入西园雅集图。"]},{"t":"韩祠歌同夏季平作","f":"七言古诗","c":["前溪后溪海气黄，东山西山山色苍。","临昆邑徙新兴乡，谁欤主者韩侍郎？","辟佛不得来南方，其年元和国号唐。","八千里路嗟潮阳，岭云不热关雪凉。","泰山北斗公文章，安知天使文蛮疆？","畀易椎结为冠裳，止八阅月教泽长。","风雷驱鳄宵奔亡，祷雨大湖岁乃穰。","两至相度溪山旁，乃移新邑居中央。","先立学校登秀良，馀事更为游山忙；","去乃留衣老僧堂。","公德在民民不忘，千年雄邑成金汤。","祠公东山慰民望，青山碧海开堂皇。","公衣冠坐清而刚，森森古木皆甘棠。","官吏习礼交趋跄，春秋荐馨如烝尝；","推公遗教道益彰。","讲院前辟环书廊，后翼以楼奉文昌。","祀朱子兼周程张，斋舍书声夜琅琅。","我归黔突初不遑，前年韩山留瓣香，今年东山陈脩羊。","为赵天水何敢当，海南閒弄明月光。","海水四立天苍茫，山精白日争披猖。","安得巨刃摩天扬，手馘长鲸剸封狼。","思公不见心徬徨，骑麟披发下大荒。","狮山山人何昂藏，万里访我浮海航。","宝剑夜解千金装，出示肝胆腾光芒。","相与谒公神慨慷，誓继公志回澜狂。","骨蕝仇国无能强，磨蝎厄宫无能殃。","手持芙蓉方南翔，中天霞拥双凤凰。","前山龙首扶云骧，南风吹雨声浪浪。"]},{"t":"乞夏季平重书文信国沁园春词并拙作双忠庙联语二首 其一","f":"七言绝句","c":["枯木寒鸦夕照迟，大书深刻壁间词。","淋漓元气千秋笔，俨雅堂前第二碑。"]},{"t":"乞夏季平重书文信国沁园春词并拙作双忠庙联语二首 其二","f":"七言绝句","c":["轮囷肝胆定交初，同吊双忠古愤摅。","留与南疆谈掌故，水曹楹帖状元书。"]},{"t":"棉雪歌","f":"七言古诗","c":["南天珍木瑰奇绝，花作红霞絮白雪。","文章万丈见光燄，谁意飘零更高洁。","峤南火维见雪稀，忽飘扣砌沾罗衣。","初晴林雨苞全坼，微遇山风絮竞飞。","团为雪球散雪气，海国遍寻遗种地。","炎荒得此太奇景，赤日行天雪花坠。","芦花秋雪杨花春，入眼偏惊夏雪新。","旁人莫妄疑轻薄，此花肝胆原轮囷。","入时自作风流格，尚留清白人间说。","偶教痼疾起烟霞，劫火不妨烧雪魄。","奇花曾为吟春红，长夏仍教住雪中。","英雄心性由来热，待竟苍生衣被功。"]},{"t":"五月十五夜望月","f":"五言律诗","c":["今月作古色，天涯伤客情。","不知夜景短，欲夺日华明。","千里幸犹共，一阴嗟已生。","妖蟆方内蚀，何以慎持盈。"]},{"t":"东山松石歌和郑生","f":"楚辞体","c":["大阴黑、耀灵匿，天上风云惨无色。","飞虎伏、神龙蛰，龙化为松虎化石。","君不见南海之滨、东山之阴，松苍苍兮石碧。","松石间，谁所祠？","睢阳张许双灵旗。","前游者驱鳄韩昌黎，后则啼鹃带血之文文山来题词。","诸公皆与此松此石深相知。","当松髯兮怒张、石齿兮愤吐，恍惚见斥庭凑，骂禄山而拒蒙古。","安知佛骨未焚、别出胡神欲代今天作之主。","大海茫茫，环起胡虏，叛臣不必定在节使府。","坐令绛灌无文、随陆不武，衣冠道丧道实苦。","松耶、石耶？","安得风云复奉尔为龙而为虎？","吁嗟乎！","长白山上有石虎立而参天，下为松花江，松涛万壑飞龙泉。","天昔生真人于其间，真人去今几世而几年。","漫漫者海，生尘生烟，遮山蜃气而蛟涎。","何来精卫口衔木石欲填海。","哀哉！","海深不可填。","我登东山，远睇长白，北向哀泪，匪泪伊血。","古人不我待，谁文章而谁气节。","但见石非石兮、松非松，乃古人肝胆之轮囷、冠绂之从容，愿拜石作丈、松作公。","我昔在韩山，有石曰双旌。","种松其间，畀成梁栋，支大厦之倾而惜其迟生。","松灵石顽，谁使松化石？","长此冥冥。","匪石实顽，石能补西北之天倾。","无奈娲皇日听笙簧谢不能，百神不敢言石言其事。","松声谡谡嗟天醉，风云兮不来，空山兀抱龙虎气。"]},{"t":"萧台宴月和季平韵","f":"五言古诗","c":["向夕阳燄息，赤道收热风。","高台旷登眺，疏星缀圆穹。","团团海上月，涌出东山东。","山海浩一色，凉波碧濛濛。","光华变云气，缤纷间青红。","坐对开心颜，不辞清尊空。","谁家双玉笛，吹月高城中。","同唱苏仙词，旷代情为钟。","栖乌若相答，哑哑啼烟丛。","把酒怀古人，今月仍古同。","下界劫尘灰，不到广寒宫。","欲归访嫦娥，安得桥如虹！","醉看群宾散，斜月西岩钟。"]},{"t":"夏夜与季平萧氏台听涛，追话旧事作","f":"七言律诗","c":["大海惊涛似昔时，高台同听不胜悲。","五年乡泪愁中制，半夜军声梦里驰。","铁弩何时开越国？","素车终古走灵胥。","如闻鹿耳鲲身畔，毅魄三更哭义旗。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其一","f":"七言绝句","c":["起家任子旧星郎，四省屏藩廿载强。","归去楼台无地筑，一帆春水问鸳鸯。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其二","f":"七言绝句","c":["唱彻陂塘买未能，乡心閒写大吴绫。","秋来烟雨楼头梦，饱啖蒪鲈羡季鹰。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其三","f":"七言绝句","c":["前身等是戒禅师，百八钟声入妙词。","画上湖船最风景，荷花国里写苏诗。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其四","f":"七言绝句","c":["尊前金缕按清歌，春日宜人诗意多。","更比王夫人福好，湖山偕隐傲东坡。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其五","f":"七言绝句","c":["卸帆亭畔怅离群，天末看云念卯君。","何日扁舟遂归计，联床风雨话湖云。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其六","f":"七言绝句","c":["嵩云岱雪思依依，琴鹤南来未得归。","有客西州说遗爱，十年泪满蜀人衣。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其七","f":"七言绝句","c":["欲回天地入孤舟，家住由拳古越州。","为语君王正尝胆，未容少伯五湖游。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其八","f":"七言绝句","c":["我家海上有鸳湖，烟柳风荷丙舍图。","百口渡江无宅住，绿篷鳄海念东都。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其九","f":"七言绝句","c":["窥江虏马气方骄，难遣雄心郁怒潮。","便住张融船亦好，莫教风景似南朝。"]},{"t":"题絜斋丈鸳湖舟隐图十首 其十","f":"七言绝句","c":["横流满目未能安，持节天南仗汉官。","蓑笠烟波渔父梦，不妨聊写画图看。"]},{"t":"谢诏安林呈材游戎惠画 其一","f":"七言绝句","c":["廿载承恩玉殿前，丹青气格老幽燕。","南来话雨旌门里，为写屏风鳄海天。"]},{"t":"谢诏安林呈材游戎惠画 其二","f":"七言绝句","c":["石骨松心海鹤姿，将军风格本权奇。","何当挥洒惊人笔，画出登坛拜将时。"]},{"t":"送季平之澳门，兼订来约 其一","f":"五言律诗","c":["别我向何处，临歧殊怅然。","群夷濠镜宅，千里火轮船。","互市开明代，飞机近百年。","茫茫众忧集，竟在有生前。"]},{"t":"送季平之澳门，兼订来约 其二","f":"五言律诗","c":["预计重逢日，归途六月中。","山川仍古越，人物几英雄。","把酒酹江月，卸帆谈海风。","行期早吾告，慎勿惜邮筒。"]},{"t":"答柳丞","f":"古风","c":["二松之间屋压头，老丞哦诗夜不休。","新篇连牍晓寄我，爽气欲扑山中楼。","楚山矗矗楚水流，楚材自昔推奇尤。","但使能坚季布诺，人间何患无曹丘。","吁嗟乎！","匈奴嫚书姿嘲弄，季布之言竟何用。","樊哙方行十万众。"]},{"t":"春感次许蕴伯大令韵 其一","f":"七言律诗","c":["一夜东风满凤城，春愁黯黯共愁生。","新年莺燕他乡感，落日鲸鲵故国情。","款局有人通秀吉，残疆无计守延平。","天涯何限哀时泪，洒向花前月不明。"]},{"t":"春感次许蕴伯大令韵 其二","f":"七言律诗","c":["浮云飞絮澹春前，梦忆虮臣吁九天。","照海旌旗忠义社，渡江帆楫永嘉年。","遗殃箕子明夷地，并割颜回负郭田。","独对东风倍惆怅，故山回首郁愁烟。"]},{"t":"春感次许蕴伯大令韵 其三","f":"七言律诗","c":["沉郁雄心苦未灰，他年卷土傥重来。","愁人断句悲青坂，战地残枪卧绿苔。","梦里国仇惭越报，眼前儿戏感吴呆。","故知块垒浇难尽，且为看花借酒杯。"]},{"t":"春感次许蕴伯大令韵 其四","f":"七言律诗","c":["濛濛海气遍东西，何日干戈许再提！","华表空闻丁鹤语，乱萌先兆子规啼。","饮河腹懑千年浊，问道心惊七圣迷。","五载伤春复伤别，忏除绮语未重题。"]},{"t":"春感次许蕴伯大令韵 其五","f":"七言律诗","c":["谁遣风雷起蛰龙，冥冥愁夜递秋冬。","梦回香国春三月，极目蓬山海万重。","置酒未闻平寿勃，奉书还见卓徵邕。","欲将笔削修花史，坠溷飘茵听所逢。"]},{"t":"春感次许蕴伯大令韵 其六","f":"七言律诗","c":["九州无地不胡尘，难觅名山老此身。","屡划鸿沟开鬼国，更移犴狱避祅神。","论文竞凿中央帝，抟土先愚上古人。","莫向武陵寻旧梦，桃花零落不成春。"]},{"t":"春感次许蕴伯大令韵 其七","f":"七言律诗","c":["动地春江走怒流，秀才心事惯先忧。","越兵屡入灵胥眼，孔履同焚逆莽头。","白马沸唇呼跸至，青牛弭耳化胡游。","最怜十万横磨剑，炼作人间绕指柔。"]},{"t":"春感次许蕴伯大令韵 其八","f":"七言律诗","c":["谶秦何必定归胡，谁遣关中缺挽输。","独客春心怜望帝，参军蛮语叹娵隅。","沉沉大泽狐能语，黯黯钟山鸟自呼。","欲取奇胲察时变，登台先验海星图。"]},{"t":"春感次许蕴伯大令韵 其九","f":"七言律诗","c":["敢吟绵葛谓人昆，典礼崇隆念本根。","都下愁春黄雾塞，日边望气赤云奔。","惊沙捲塞朝呼鹘，吹浪空江夜有豚。","唱彻得脂新乐府，鲜卑闻说最承恩。"]},{"t":"春感次许蕴伯大令韵 其十","f":"七言律诗","c":["顾曲当筵唤奈何，春江愁饫木鱼歌。","奔天素女月华冷，话海麻姑霜鬓多。","断续乡心车铎语，暖寒天气酒杯和。","故人勾漏今仙令，欲乞丹砂治睡魔。"]},{"t":"舟泊凤皇台寄怀季平","f":"楚辞体","c":["乐莫乐兮新相知，悲莫悲兮初别离。","鮀江水黄海水绿，与君一夜东西驰。","凤皇台边客帆卸，遥忆维舟九龙夜。","欲知别后相思深，茫茫江海愁人心。"]},{"t":"凤皇别寄季平","f":"五言古诗","c":["大鹏海上居，南徙乘天风。","抟扶不得力，坠落荒山中。","郁郁无可语，大鹏良自苦。","群鸟怪大鹏，将毋客傲主。","丹山有异鸟，其名曰凤皇。","出为天下瑞，世但惊文章。","凤皇翔八极，南与大鹏遇。","无以栖凤皇，且借梧桐树。","乌鸢尔勿嚇，鸴鸠尔勿笑。","毛羽虽尔同，嗟尔不同调。","凤皇语大鹏，冲天终有时。","勉哉培风力，慎勿负所期。","六月息不得，大鹏心自热。","茫茫九天云，独与凤皇别。"]},{"t":"叠望月韵答柳汀","f":"七言律诗","c":["閒愁万种扫难清，漠漠蛮江雨又晴。","归国人才辛弃疾，通天心事沈初明。","停云八表思朋好，朗月三生发古情。","书罢逍遥鸴鸠笑，剧怜愤世有庄生。"]},{"t":"潮州东门城栖寄怀梁仲遂二首 其一","f":"五言律诗","c":["万国无安土，东楼纵目初。","独怜沧海客，不得广州书。","忌讳文章少，穷愁问讯疏。","五噫歌自苦，旅抱近何如！"]},{"t":"潮州东门城栖寄怀梁仲遂二首 其二","f":"五言律诗","c":["傥上朝台望，应怜去雁迟。","三年今不见，千里每相思。","客枕新愁重，佣书旧业卑。","梁鸿仍海曲，与尔负明时。"]},{"t":"芷谷居士画大幅水墨云山、瀑布二图，并题句见赠，长句赋谢","f":"七言古诗","c":["墨风一夜驱云起，龙气濛濛万山里。","轩窗如闻瀑布声，天下奇观宁有此？","纷纷众史画格卑，嗟君抗古森雄奇。","下追西庐上北苑，中间直蹑黄大痴。","填胸磊块化丘壑，臆造桃源付耕凿。","胡尘不到画里天，如此江山殊不恶。","平生画山不画人，四海无人堪写真。","此图忽著人者两，草庐对语空山春。","口读君诗目君画，众木槎枒群石怪。","动摇古壁愁欲飞，骇视云中忽龙挂。","岂惟城市生山林，风云惨澹开胸襟。","可怜祗向画图见，孤负苍生霖雨心。"]},{"t":"观芷谷居士画，有怀其兄菽蕃先生","f":"七言律诗","c":["梅水东流系别思，披图如见古须眉。","遥知忆弟看云日，应是疲农待雨时。","寥落音书黄耳犬，艰难世局白衣夔。","画中省识桃源路，聊寄陶潜写意诗。"]},{"t":"己亥五月二日东山大忠祠祝文信国公生日 其一","f":"五言古诗","c":["岩岩古潮阳，有山峙其东。","下为信国祠，额榜曰大忠。","丹青半剥落，冠笏犹清雄。","我来主此山，私淑怀愚衷。","载稽登科记，降神缅维崧。","是为夏五月，万树榴花红。","令辰纪端二，致祝叩寝宫。","忆公昔驻此，酹张许二公。","祠碑俨在壁，马冢荒原中。","炎精忽不祀，支天难为功。","我今酹公酒，司令仍祝融。","胡风西北来，边愁浩无穷。","河山易破碎，回顾忧心忡。","何以邀公灵，海气天濛濛。","寒鸦几夕阳，懔懔思英风。"]},{"t":"己亥五月二日东山大忠祠祝文信国公生日 其二","f":"五言古诗","c":["公生端平间，厥岁曰丙申。","谁云火德衰，魁杓指朱鹑。","郁郁富田乡，紫云气氲氤。","日月既合朔，其夕生伟人。","天鸡声一鸣，龙挟云而神。","安知阳九厄，遂肇揽揆辰。","朝纲正颓坠，正士多丧沦。","真魏两大儒，不使秉国钧。","震电惊明堂，天意为之嗔。","空下罪己诏，满目嗟胡尘。","咄咄蒙古师，迫人过女真。","是岁楚蜀吴，将帅奔命频。","所幸奇渥温，斥地北海滨。","姑缓南牧师，匪曰虏气驯。","小朝誇天堑，文学仍彬彬。","公生二十年，宝祐纪丙辰。","一举冠东南，对策登紫宸。","忠肝发古谊，识者王应麟。","蹉跎二十年，遂成不朽身。","得年四十七，为寿千万春。"]},{"t":"己亥五月二日东山大忠祠祝文信国公生日 其三","f":"五言古诗","c":["公生阅己亥，逮今十有二。","公甫四龄时，头角已顿异。","屠维大渊献，于时岁方次。","念天生公心，畀出为国瑞。","安知国多难，飘萍感身世。","艰难道路间，将相名空寄。","当题词东山，已表殉忠志。","天倾不可拄，孔孟付仁义。","溯题词距今，六百廿一岁。","三豕又渡河，来公驻师地。","春水和平桥，读公碑上字。","东山拜公祠，红棉昼飞絮。","一朵莲花峰，海风吹欲坠。","落日望帝啼，血洒英雄泪。","宜振者人心，宜作者士气。","所愿藉公灵，斯道或不匮。","寿酒跻公堂，敬表希贤意。","此意良无穷，种树为之记。","桂蕴九天香，松郁千年翠。","夜望魁斗光，正照南离位。"]},{"t":"己亥五月二日东山大忠祠祝文信国公生日 其四","f":"五言古诗","c":["公诗纪生日，实始山中作。","客聂、谢朱、萧，唱酬夕飞爵。","筑堂面大江，文笔峰崿崿。","自号曰文山，姑写山中乐。","于时军国事，平章付秋壑。","茫茫天下计，铁铸六州错。","浮沉一麾守，山居未能廓。","白雁渡江来，皋亭北风恶。","嗟公困奔走，百折志不弱。","辛苦立二王，海滨足难托。","流涕赴燕时，哀歌日光薄。","指南与吟啸，两集未零落。","屡吟初度诗，乾坤声寂寞。","四年五章在，俯仰感今昨。","即今为公寿，宁止陈杯杓。","华表倘归来，请赋南飞鹤。"]},{"t":"己亥五月二日东山大忠祠祝文信国公生日 其五","f":"五言古诗","c":["庭蕉实方黄，荔子丹离离。","撷之用荐馨，薄寄千秋思。","有明萧黄门，实肇为斯祠。","去今三百年，往烈谁攀追？","兰陵二生者，为我陈牲牺。","祝公自公义，繄我宁独尸。","佳客万里来，新射策丹墀。","与公天上名，俱书白玉碑。","此来上公寿，香火缘可知。","彬彬潮人士，登堂同观仪。","肃雍俎豆间，如见天人姿。","左张而右陆，磊落雄须眉。","东山富奇石，为虎为龙螭。","石气上为星，寒燄生尾箕。","睢阳两忠臣，半夜来灵旗。","比邻倘相呼，应诉君国悲。","愿公勿复悲，来歆此寿卮。","同堂祝公者，愿公为之师。","同持忠义心，以为治平基。","运会值大同，一统兼华夷。","岁岁此祝公，清芬生鼎彝。","勿诵炎午文，勿歌皋羽辞。","渊渊金石声，风雨方催诗。"]},{"t":"东山酒楼放歌","f":"楚辞体","c":["丈夫生当为祖豫州，渡江誓报祖国雠，中原不使群胡留。","不然当作李邺侯，翩然衣白与帝游，天家骨肉畀无尤。","胡为祗学谪仙醉，到处吟诗题酒楼。","今日何日东山陬，云阴阴兮风飕飕，山中五月如清秋，补禊曲水觞可流。","座中主客清且修，黄公后人今状头，裴中令裔新政优。","兰陵诸萧才力遒，人师我愧东家丘。","儒书无能解国忧，仡仡食古心不休。","飞蓬自转落叶下，谁实作俑为车舟。","坐令机械生西欧，古制破裂不可收，天地日月驱作球。","小儒咋舌大儒叹，径欲问天穷所由，天公方醉了不酬。","万事变灭如浮沤，山川虽缺仍金瓯。","陇头飞鸟入妖梦，夜半鸣狐思火篝。","何如沉醉与天共，乞君大白为我浮。","浮之不尽群客醉，何妨呼酌车前驺。","自有此山数游者，昌黎文山皆吾俦。","彼皆身取千古去，乃畀我任今日愁。","海门西望海色幽，眼中一醉无五洲。"]},{"t":"凤皇道中 其一","f":"五言律诗","c":["磴道千回转，连峰接凤皇。","山深民气朴，秋近谷风凉。","瀑布穿危石，梯田播晚秧。","数家临水住，羡尔好林塘。"]},{"t":"凤皇道中 其二","f":"五言律诗","c":["山中五六月，云过雨来时。","岚气阴晴变，秋衣早晚宜。","畲民安世业，茶客话墟期。","行道未应倦，夕阳蝉满枝。"]},{"t":"凤皇山下投宿文氏家，询之，盖信国公裔也，出其庐陵所刊族谱及公诗文集、自订年谱、遗像三、手书一幅见示，感而有作","f":"七言律诗","c":["凤皇山下野人村，中有庐陵旧德门。","世系一编唐相表，衣冠廿代信公孙。","画图重省云中梦，剪纸曾招海上魂。","惭愧斩蛟长剑在，千秋心事共谁论？"]},{"t":"抵饶平作 其一","f":"五言律诗","c":["群峰青不断，叠磴出林间。","雨洗飞龙径，云藏大鸟山。","南流收粤海，北峤拱闽关。","精舍何年筑，秋风有客还。"]},{"t":"抵饶平作 其二","f":"五言律诗","c":["鼓角声何处，残碑不可寻。","田功迫秋急，山气入城深。","旧俗仍高髻，遗民半客音。","驱车来访古，空作绣衣吟。"]},{"t":"饶平杂诗 其一","f":"七言绝句","c":["梦醒三更画角吹，万山深处客来时。","坏墙半堵双流寺，重出梅溪旧勒碑。"]},{"t":"饶平杂诗 其二","f":"七言绝句","c":["战裙化蝶野云香，百丈埔前废庙凉。","碧绣苔花残瓦尽，更无人拜许娘娘。"]},{"t":"饶平杂诗 其三","f":"七言绝句","c":["海云南护六龙奔，凄绝辞郎酒满尊。","一曲平元万行泪，红螺洲上望崖门。"]},{"t":"饶平杂诗 其四","f":"七言绝句","c":["二凤杨家旧有声，薛家父子亦知名。","祗今谁讲阳明学，莫怪南来道不行。"]},{"t":"饶平杂诗 其五","f":"七言绝句","c":["循名曾记御屏留，龙眼城中故宅秋。","残局庙堂多水火，苦将遗句忆廉州。"]},{"t":"饶平杂诗 其六","f":"七言绝句","c":["程斋残稿付虫鱼，逸老堂空冷故居。","未敢乡词荐蘋藻，千秋遗议两尚书。"]},{"t":"饶平杂诗 其七","f":"七言绝句","c":["山城落叶客衣单，海气阴阴夕照残。","愁向尊君台上望，九秋风雨北来寒。"]},{"t":"饶平杂诗 其八","f":"七言绝句","c":["东南风急怒潮雄，此去闽关有路通。","望海峰头秋满眼，故乡遥隔战云中。"]},{"t":"饶平杂诗 其九","f":"七言绝句","c":["翠柏森森岭势回，九仙亭畔绣衣来。","空严铁佛冷无语，笑指山花落复开。"]},{"t":"饶平杂诗 其十","f":"七言绝句","c":["南坛墓碣蚀苔斑，华表飘零怅鹤还。","欲觅先臣旧精舍，西风残照满金山。"]},{"t":"饶平杂诗 其十一","f":"七言绝句","c":["班春车畔紫芝新，梦入黄山夜有神。","爱说吾家两贤令，胜朝循迹话遗民。"]},{"t":"饶平杂诗 其十二","f":"七言绝句","c":["椎结遗风尚宛然，凤皇山畔种畬田。","山中自作槃瓠国，更在佗王左纛前。"]},{"t":"饶平杂诗 其十三","f":"七言绝句","c":["古洞云深锁百花，香泉飞饮万人家。","春风吹出越溪女，来摘山中待诏茶。"]},{"t":"饶平杂诗 其十四","f":"七言绝句","c":["莫笑山农语不经，豆棚閒话倚锄听。","量沙测水关何术，争说潭灵井更灵。"]},{"t":"饶平杂诗 其十五","f":"七言绝句","c":["山中城雉郁嵯峨，山外长鲸万里波。","休向麻姑买沧海，桑田变后战争多。"]},{"t":"饶平杂诗 其十六","f":"七言绝句","c":["径畔行人拜更勤，中原灾旱正如焚。","九龙潭畔呼龙起，重向人间作雨云。"]},{"t":"黄子惠曾由沪上同舟至直沽，一别十年矣，相见饶平县廨，尊酒话旧，赋此为赠","f":"七言律诗","c":["剪烛衙斋岁欲周，十年郭李记同舟。","飞凫仙令循良治，戎马书生汗漫游。","析木津潮寒旧雨，大金山月照清秋。","南来喜听舆人诵，赢得廉声岭外州。"]},{"t":"百丈埔为宋张丞相世杰夫人许氏大战元兵殉节处，旧有祠，废久矣，子惠署县为商复旧迹","f":"七言律诗","c":["灵旗半夜偃胡风，百丈埔前战血红。","异代双忠更张许，男儿千古逊英雄。","麻沙故乘讹遗迹，禾黍秋原失寝宫。","重表幽芳关庙貌，浮山南望夕阳中。"]},{"t":"山村即目 其一","f":"七言绝句","c":["轧轧车声水满陂，溪山佳处客行迟。","林腰一抹炊烟淡，知是人家饭熟时。"]},{"t":"山村即目 其二","f":"七言绝句","c":["一角西风夕照中，断云东岭雨濛濛。","林枫欲老柿将熟，秋在万山深处红。"]},{"t":"山村即目 其三","f":"七言绝句","c":["山田一雨稻初苏，村景宜添七月图。","鸡犬惊喧官牒下，农忙时节隶催租。"]},{"t":"神龟祠","f":"五言古诗","c":["峨峨飞凤岭，凤去巢不留。","迢迢飞龙径，龙睡空山秋。","道逢山中叟，古意何绸缪？","贶我以神龟，云昔嘉林游。","误落世网中，灵囿怀故俦。","再拜谢佳贶，出山云幽幽。","细观背上文，纵横成九畴。","神灵具四目，乃与仓圣侔。","幸未逢刳钻，导引故自优。","区区忧养生，何事劳蜉蝣？","老桑不尔祸，灵蓍行尔求。","愿尔安食息，千岁一出头。","无须左胁书，重光瑞王侯。","吾生似放翁，筑堂思山陬。","三复蒙庄言，曳尾行归休。"]},{"t":"三饶述怀","f":"古风","c":["三饶设治初，颇用忧山贼。","孤城依山立，陶筑资民力。","至今古砖文，分堵姓名勒。","倭寇海上来，东风战云黑。","濒海虽蹂躏，严城晏游息。","百里控山川，亦古诸侯国。","王公设险心，实用辅其德。","同治元二间，黄巾势危迫。","距关民气勇，乃过丸泥塞。","承平岁已久，生齿益繁殖。","吏治浸不修，宽假恣奸慝。","外教乘隙来，从者纷相惑。","山川固云险，寇已入门阈。","山田岁两熟，民生在稼穑。","年荒百货贵，菜茹当肉食。","道上逢老农，喘汗有饥色。","谁为富教谋？","用奏循良绩。","为尔祝坻京，为尔云螟?。","驱车过山邑，怀古心焉恻。","峨峨望海岭，秋风浩无极。"]},{"t":"闻童谣作","f":"古风","c":["柑花开，吴王来；","柑结子，吴王死。","吴王一死不复生，西风吹入童谣声。","我有射虎之弓斩蛇剑，独立回顾贼星敛。","柑花年年落复开，满林柑子金累累。","尔身自文发自断，白马潮来吴命短。"]},{"t":"七月十五日饶溪舟次","f":"五言律诗","c":["南国中年节，西风下水船。","溪声喧百里，峰影蘸双莲。","野祭人呼鬼，温汤客试泉。","团栾明月上，照梦鹤山前。"]},{"t":"过黄冈","f":"七言律诗","c":["落日孤城望里遥，北来山势接三饶。","隔林野店人沽酒，拢岸溪船客候潮。","官狃承平兵气弱，地当冲要市声嚣。","秋风吹梦黄冈路，海色濛濛夜未消。"]},{"t":"寄怀谢四颂丞台湾 其一","f":"五言律诗","c":["独听荒鸡夜，天涯忆故人。","烟霞仍痼疾，雷雨负经纶。","梦寐孤灯影，文章断发身。","相思隔沧海，极目叹扬尘。"]},{"t":"寄怀谢四颂丞台湾 其二","f":"五言律诗","c":["文武新茶火，君臣旧药笼。","泉香乖昔嗜，方古误书穷。","索醉归谋妇，佯痴近作翁。","信陵醇酒意，潦倒几英雄。"]},{"t":"寄怀谢四颂丞台湾 其三","f":"五言律诗","c":["秋水芙蓉国，斜阳燕子家。","青衫封敝簏，红烛赏残花。","历劫多情在，寻春故约差。","壶芦墩畔月，冷照旧琵琶。"]},{"t":"寄怀谢四颂丞台湾 其四","f":"五言律诗","c":["遥忆登临处，今应付卧游。","吹云孤笛夜，落月万山秋。","挂壁舆图改，寻碑屐齿留。","年来腰脚健，还似旧时不？"]},{"t":"题画梅石 其一","f":"五言绝句","c":["石抱太古春，花作香雪海。","不知天地心，倚杖空山待。"]},{"t":"题画梅石 其二","f":"五言绝句","c":["瘦石护寒梅，盎盎回春意。","借君铁笛声，吹起群山睡。"]},{"t":"东山景贤楼","f":"七言律诗","c":["双旌五马旧登临，北斗文章自古今。","新邑弦歌开瘴户，大湖云气起甘霖。","留衣偶共山僧话，建校谁知刺史心。","独上景贤楼上望，红棉花发练江深。"]},{"t":"东山秋晚","f":"七言律诗","c":["庭柯策策动商音，紫翠连峰夕照沉。","秋色西来山郭暮，大江东去海门深。","空崖石抱阴阳气，古洞泉流冷暖心。","苦盼银河乌鹊信，望仙桥畔客愁深。"]},{"t":"追和裴君晚登阜民台之作","f":"七言律诗","c":["斜阳满目起城笳，天末吴云点暮鸦。","醇酒醉寻公瑾宅，远山晴入小乔家。","高台春晚愁铜雀，废署年深长石花。","怀古登临倍惆怅，东风何处戟沉沙。"]},{"t":"东山感秋词，次康步崖中翰题壁韵五首 其一","f":"七言绝句","c":["痛哭秋风又一年，觚棱梦落练江天。","拾遗冷作诸侯客，袍笏空山拜杜鹃。"]},{"t":"东山感秋词，次康步崖中翰题壁韵五首 其二","f":"七言绝句","c":["天涯心逐白云飞，瑟瑟秋芦点客衣。","回首大宛山上月，更无缄札问当归。"]},{"t":"东山感秋词，次康步崖中翰题壁韵五首 其三","f":"七言绝句","c":["斜日江声走急滩，残棋别墅局方难。","后堂那有閒丝竹？","陶写东山老谢安。"]},{"t":"东山感秋词，次康步崖中翰题壁韵五首 其四","f":"七言绝句","c":["寒蛟海上趁人来，漠漠秋尘扫不开。","满目桑田清浅水，五云楼阁失蓬莱。"]},{"t":"东山感秋词，次康步崖中翰题壁韵五首 其五","f":"七言绝句","c":["冷落山斋运甓身，天门八翼梦无因。","西风吹起神州恨，麈尾清谈大有人。"]},{"t":"寄怀晓沧上杭兼示族人 其一","f":"五言律诗","c":["落日琴冈路，秋风练水潮。","寄书迟远道，拔剑舞中宵。","当世自饥溺，此行何寂寥！","阳明碑下过，大树影萧萧。"]},{"t":"寄怀晓沧上杭兼示族人 其二","f":"五言律诗","c":["磊落吾宗彦，因君寄远思。","云山千里梦，花草六朝诗。","东观仍家学，南州共火维。","渡江惭旧族，一席尚经师。"]},{"t":"寄怀晓沧上杭兼示族人 其三","f":"五言律诗","c":["何处梅花洞，寒香不计年。","人稀集灵怪，山古足云烟。","安得夸娥力，为开混沌天。","呼龙种瑶草，游戏老芝田。"]},{"t":"寄怀晓沧上杭兼示族人 其四","f":"五言律诗","c":["漠漠江湖梦，秋心落百蛮。","藜床支北海，棋局隐东山。","沧海波无极，浮云影自閒。","汀州有芳草，愁采白蘋还。"]},{"t":"寄家果园孝廉","f":"七言律诗","c":["回首东风倍黯然，春江曾拜孝廉船。","马蹄去踏燕台雪，鸥梦空沉玉溶烟。","故国流移仍作客，远书珍重到经年。","白头二老诗豪甚，更益相思海上天。"]},{"t":"寄兰史、晓沧、菽园用晓沧韵 其一","f":"七言律诗","c":["窟室闻钟酒正酣，将军组练罢西龛。","已忧朋党逾河北，更遣王庭渡漠南。","急政谁求梅尉传，祸萌何止霍侯骖！","汉家未有登封日，留滞休嗟太史谈。"]},{"t":"寄兰史、晓沧、菽园用晓沧韵 其二","f":"七言律诗","c":["军中草檄笔空酣，神理虚存暴未龛。","祗见螺舟来海外，未容马柱表交南。","瑶章竞托三青鸟，羽卫翻劳二白骖。","收拾皋言注孙子，更无兵许牧之谈。"]},{"t":"寄兰史、晓沧、菽园用晓沧韵 其三","f":"七言律诗","c":["台上歌声起半酣，茫茫项定与刘龛。","岂真汉厄逢三七，终见尧封暨朔南。","誓罢猫仍容武鼠，梦回虎已齧嬴骖。","百王道在焚难尽，数典偏怜有籍谈。"]},{"t":"寄兰史、晓沧、菽园用晓沧韵 其四","f":"七言律诗","c":["天浆倾倒帝沈酣，西奈神来佛让龛。","自转双轮删合朔，别传十诫贬和南。","寻山久已逃灵鹫，问道真疑到剧骖。","至竟大同新运在，老生莫自厌常谈。"]},{"t":"寄兰史、晓沧、菽园用晓沧韵 其五","f":"七言律诗","c":["唱月呵云兴正酣，颇闻海上有仙龛。","置身敢在中贤下，避地仍居北斗南。","石室搜残神禹简，金天留驻蓐收骖。","欲将虎鼠龙猪意，唤起东方与释谈。"]},{"t":"题菽园看云图","f":"楚辞体","c":["看云不作狄梁公，屈身几以牝朝终。","看云不作杜陵翁，许身稷契仍诗穷。","男儿生果抱雄志，眼光到处古人避。","我所思兮大海南，岛上看云有奇士。","丹青貌形不貌神，茫茫四海谁写真。","直取乾坤万古眼，写入一气相氲氤。","阳云出冬阴云夏，鲁马赵牛物交化。","置身云外看云中，云之君兮纷来下。","眼前所见云非云，中有看者精神存。","古今万事云变灭，嗟哉郁郁何纷纷！","不见卿云峦缦色，但见浮云蔽西北。","坐令下士怀百忧，高天无青日不白。","平生长剑空倚天，未能划断云连绵。","亦知阴霾势非久，其奈勃郁当吾前。","登高丘兮望远海，八表停云有人在。","世间难得吉祥云，望气空怜成五采。","九渊沉沉蛰者龙，云兮虽起当谁从？","雷霆收声电收影，眼见闭塞将成冬。","天地心留画图里，云生海山吸海水。","淋漓元气大九州，霖雨苍生卧龙起。"]},{"t":"次韵答兰史中秋有怀","f":"七言律诗","c":["水调歌残酒正中，浮云遮住月当空。","江湖归梦怜坡老，宾从清谈愧庾公。","谁把哀弦开上界，自携长剑倚崆峒。","人间枉作孀娥怨，玉宇沉沉路不通。"]},{"t":"刘慧君廿年旧友，曾从余义军，内渡寓漳，来潮见访，赋赠","f":"七言律诗","c":["义旗风卷海东云，零落登坛十万军。","幕府昔曾惊杜牧，名场久已重刘蕡。","青山故国馀哀涕，黄叶清秋下夕曛。","閒煞钤韬无用处，可怜尊酒更论文。"]},{"t":"重阳作","f":"七言古诗","c":["秋风万里南归客，欲耕无田住无宅。","重阳无酒无黄花，更嗟不及陶彭泽。","五年客里逢重阳，江山信美嗟吾乡。","黄花犹向战场发，次公虽醒何能狂？","青山入城誇富贵，卜居已失山家味。","每逢佳节欲登高，却嫌山有金银气。","湘子桥颓石欲枯，文公祠古寒秋芜。","潮州老守挂冠去，南来吾道行益孤。","海气昏昏天欲坠，且食蛤蜊知许事。","满城风雨铸新诗，幸无败兴催租吏。"]},{"t":"朱梅农来访，手诗集见赠，用集中李子黼题词韵","f":"七言律诗","c":["吟鞭遥指海云开，且借官书觅句来。","岭路晓收鹦母瘴，秋风人上凤凰台。","客帆影里追前梦，官鼓声中老此才。","昨过东山辱相访，水帘亭畔负流杯。"]},{"t":"朱梅农以兰史书至，叠前韵寄兰史","f":"七言律诗","c":["五岭苍凉霸气开，一书迢递海天来。","秋风试马刘王埒，落日呼鹰赵尉台。","各抱古愁观世界，自携新史数人才。","何时同纵登高目？","笑指沧溟水一杯。"]},{"t":"题寒机课子图","f":"七言律诗","c":["慈竹斑斑满地阴，乌衣门巷雪华深。","机声古屋三迁梦，灯影寒窗五夜心。","晚节终怜范滂传，春晖长入孟郊吟。","流传不待甘泉画，彤管先教写德音。"]},{"t":"果园见访潮州，次前寄怀韵","f":"七言律诗","c":["空江渔火夜初然，有客新停鳄渚船。","水阁芙蓉秋坠露，金城杨柳夕愁烟。","旅鸿消息来今日，戎马纵横话昔年。","莫向乘风亭畔望，九州南尽海浮天。"]},{"t":"寄怀黄公度二首 其一","f":"七言律诗","c":["茫茫远道九秋思，渺渺凉波万顷陂。","八月灵槎虚汉使，三闾奇服怨湘妃。","醉倾沧海麻姑酒，劫入商山橘叟棋。","铁汉高楼閒怅望，岭云南护党人碑。"]},{"t":"寄怀黄公度二首 其二","f":"七言律诗","c":["万木萧森夜有霜，登高怀古客心伤。","斜阳澹作黄昏色，残月遥分大白光。","卧病梦持明主节，起居缄费远人珰。","著书閒对秋灯影，独乐园中漏点长。"]},{"t":"寄马介堂高州 其一","f":"七言绝句","c":["莽莽罗浮别旧封，将台移筑武坛峰。","乡心万里怀金马，军令三秋肃石龙。"]},{"t":"寄马介堂高州 其二","f":"七言绝句","c":["洗太营边锦伞收，潘仙亭畔石船留。","一条丁水铜鱼寨，照见将军仗钺游。"]},{"t":"寄马介堂高州 其三","f":"古风","c":["翠水西流铁舰通，?州极目海云红。","弓刀小驻元戎队，满地秋芜宋故宫。"]},{"t":"寄马介堂高州 其四","f":"七言绝句","c":["金城秋柳碧毵毵，久罢军中扪虱谈。","何日伏波酬大志，更携铜柱表交南。"]},{"t":"题禾梅农白云修禊图","f":"七言律诗","c":["鹤舒台边蹑紫烟，龙泉寺畔斟碧泉。","千峰云气酿秋色，踏云访客安期仙。","湖菊流黄涧蒲翠，花簇秋觞修禊事。","斜阳一角明玉虹，满目白云下山去。"]},{"t":"朱梅农归羊城，三叠前韵为送","f":"七言律诗","c":["十幅蒲帆鳄渚开，行装捆载好诗来。","人归国子先生庙，秋在蛮夷大长台。","珠海群花供客笑，金山明月照论才。","平生我最思张翰，跌宕千秋一酒杯。"]},{"t":"沈艾孙为刻石章三，赋此为谢二首 其一","f":"七言绝句","c":["奏刀劳琢寿山云，古色斑斓缪篆文。","留与后贤珍印谱，便应传是汉将军。"]},{"t":"沈艾孙为刻石章三，赋此为谢二首 其二","f":"七言绝句","c":["西风万里客登台，如斗黄金愧此才。","睥睨千秋仗神笔，狼居胥石勒名来。"]},{"t":"东柳汀","f":"七言绝句","c":["板桥斜日柳毵毵，秋入蛮乡客兴酣。","休唱前溪后溪曲，六朝金粉忆江南。"]},{"t":"访柳汀","f":"五言律诗","c":["远水空江静，斜阳小市迟。","我来寻范蠡，久未见西施。","旧事翻诗卷，新愁集酒卮。","东山少丝竹，羡尔有花枝。"]},{"t":"游双髻山 其一","f":"五言律诗","c":["绝代双鬟影，曾从海上看。","入山群石怪，倚树一庵寒。","岭瘴消文贝，岩香孕素兰。","飞鸦如喜客，啼出古林端。"]},{"t":"游双髻山 其二","f":"五言律诗","c":["古刹何年建，苔荒磴道斜。","双峰出霄汉，一室贮烟霞。","石气瘦崖树，泉香流涧花。","山僧忘梵诵，云卧冷袈裟。"]},{"t":"游灵山护国禅院作 其一","f":"七言绝句","c":["十月虹桥买棹行，临昆山色眼中横。","更无东晋残碑在，一抹寒芜故县城。"]},{"t":"游灵山护国禅院作 其二","f":"七言绝句","c":["漠漠荒山仗佛开，千年古木半摧颓。","惟应一勺灵泉水，曾照元和太守来。"]},{"t":"游灵山护国禅院作 其三","f":"七言绝句","c":["便访山僧亦偶然，何曾同證石头禅？","三书难定儒林案，笑看中天北斗悬。"]},{"t":"游灵山护国禅院作 其四","f":"七言绝句","c":["铜壶水竭荔无阴，镜塔荒凉古藓深。","妙法莲华随劫尽，萧萧落叶写经心。"]},{"t":"游灵山护国禅院作 其五","f":"七言绝句","c":["唐颠宋蹶电中过，佛法其如世运何？","一例称师更称祖，可怜人拜大峰多。"]},{"t":"游灵山护国禅院作 其六","f":"七言绝句","c":["难振宗风似昔年，两山狮象卧寒烟。","佛门各斗无边法，僧讼传家袖影田。"]},{"t":"游灵山护国禅院作 其七","f":"七言绝句","c":["无复山神护法时，萧条赐额冷云楣。","重扶一片空山石，来读先朝运使碑。"]},{"t":"游灵山护国禅院作 其八","f":"七言绝句","c":["山钟飞作郡楼声，访古人来百感生。","叶叶莲花开怪石，留衣亭畔独题名。"]},{"t":"游灵山护国禅院作 其九","f":"七言绝句","c":["閒向山僧理旧闻，佛楼携客话秋云。","谁知八部天龙力，曾护昌黎谏佛文。"]},{"t":"游灵山护国禅院作 其十","f":"七言绝句","c":["寒钟声送暮云飞，铜绣桥边客棹归。","极目隔江烟树里，峡山孤塔上斜晖。"]},{"t":"客窗夜话，同王晓沧作","f":"五言律诗","c":["通国正酣睡，忧时人独醒。","月怜今夕黑，天失古来青。","闭塞穷冬运，光明海上星。","荒鸡声满野，倚剑此同听。"]},{"t":"有感书赠义军旧书记四首 其一","f":"七言绝句","c":["拜将坛高卓义旗，五洲睽目属雄师。","当时力保危台意，只有军前壮士知。"]},{"t":"有感书赠义军旧书记四首 其二","f":"七言绝句","c":["宰相有权能割地，孤臣无力可回天。","啼鹃唤起东都梦，沈郁风云已五年。"]},{"t":"有感书赠义军旧书记四首 其三","f":"七言绝句","c":["凤凰台上望乡关，地老天荒故将閒。","自写鄂王词在壁，从头整顿旧河山。"]},{"t":"有感书赠义军旧书记四首 其四","f":"七言绝句","c":["谁能赤手斩长鲸，不愧英雄传里名。","撑起东南天半壁，人间还有郑延平。"]},{"t":"题画竹","f":"古风","c":["冉冉古琅玕，结根广莫野。","取之作律筒，持用觉天下。","当世无伦伶，谁是知音者？","空教二帝女，攀枝泪如泻。","竹枝有叶叶有阴，云封嶰谷无凤吟。","九嶷山高湘水深，题君此图伤我心。"]},{"t":"己亥除夕","f":"五言律诗","c":["君国无穷感，乾坤此夕心。","纷纭新旧事，慷慨短长吟。","家宴喧儿女，门符阅古今。","围炉閒守岁，莫负酒杯深！"]},{"t":"送李伯质太守归里","f":"七言古诗","c":["船头伐鼓升船旗，潮州老守今南归。","天公予閒兼予健，人生七十古所稀。","方今中朝重耆硕，衮衮公卿头毕白。","但非策免皆固留，夜望三台自深惜。","如公此行今所难，文书十上辞一官。","即论知止亦高绝，况复远识时能观？","大海茫茫正龙战，老眼饱看犹健饭。","布帆无恙归去来，且喜春江鱼价贱。","公家旧住蕲黄间，结庐更向霍太山。","儿孙教识忠孝字，馀事广种山中田。","公归自得山中乐，累我中年别怀恶。","何时寄我山居图，相思远慰南飞鹤。"]},{"t":"次韵答兰史香江见赠","f":"七言律诗","c":["乾坤何地许扬眉，海上逢君泪满衣。","泥饮已虚蝴蝶会，寄愁惟咏杜鹃诗。","平陵松柏人谁问？","京雒风尘客自知。","拟约子猷重过访，扁舟春雪预相期。"]},{"t":"早春有怀兰史，用高常侍人日寄杜拾遗韵","f":"七言古诗","c":["东风夜入说剑堂，引杯自醉梅花乡。","韩江有客远相忆，江声正搅愁人肠。","闻鸡欲舞谁相与，神州陆沈剧堪虑。","祗今海上无仙山，缥缈飞楼寄何处？","蟠桃花发天为春，安知沧海方扬尘？","与君行觅咏诗地，我亦苍茫独立人。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其一","f":"七言绝句","c":["故人天末缄诗至，格似龙标供奉多。","不愧南中称十子，一时人望属西河。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其二","f":"七言绝句","c":["笔端浩气满乾坤，桑海归来义愤存。","碎破河山同感慨，更将忠迹表蚝墩。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其三","f":"七言绝句","c":["当时痛哭割台湾，未肯金牌奉诏还。","仓葛哀呼竟何补，全军难保武峦山。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其四","f":"七言绝句","c":["英雄愧说郑延平，目断残山一角青。","何日天戈竟东指，誓师海上更留铭。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其五","f":"七言绝句","c":["黯黯归云拥海槎，浪纾筹策事量沙。","岛中义士依然在，伏腊年年奉汉家。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其六","f":"七言绝句","c":["经史无功世贱儒，空山披褐感潜夫。","斩新花样愁经眼，颠倒天吴紫凤图。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其七","f":"七言绝句","c":["尊酒东山拜大忠，浩歌人尚气如虹。","残篇重检王炎午，来祭庐陵信国公。"]},{"t":"林氅云郎中寄题蚝墩忠迹诗册，追忆旧事，次韵遥答 其八","f":"七言绝句","c":["徙尽虹桥桥畔蚝，北风吹客冷萧骚。","沁园一阕君须记，落木斜阳句更豪。"]},{"t":"蓝溪烈妇篇为上杭族人德祥妻廖氏作","f":"古风","c":["蓝溪水，清而蓄，中有双鸳鸯，旁有连理木。","上多贤者居，吾丘世聚族。","岁在蛇，贤人嗟，秋风吹折连理花。","文鸳一夜死，鸯殉其雄死自矢。","于时九月天雨霜，月魄将死未死尚有光如珥，流照人间烈妇里。","妇年三八缺未完，千古完名付彤史。","夫有烈妇夫不死，妇死先令夫有子，去夫之死三日耳！","蓝溪水，清且长，滨溪行建烈妇坊；","上书天语为褒扬，下书妇氏廖夫曰丘德祥。","海可枯，石不烂，巍坊永永蓝溪岸。"]},{"t":"崧里烈妇篇为门下士大埔何寿慈妻萧氏作","f":"古风","c":["吾门有何生，其才清且美。","弱冠赫有声，不愧名家子。","火色法宜贵，祗忧不寿尔。","奈何衿未青，一鸣竟长已。","有妇氏曰萧，从容殉之死。","吁嗟乎！","造物忌才尤忌名，何生惟有才，不幸与之撄。","烈哉妇！","乃以一死婉婉上与造物争。","才虽可死名不死，岂非赖此闺中英？","君不见崧里之山高嶪嶪，崧里之水扬益洁。","中有峨峨双绰楔，天荒地老名不灭。"]},{"t":"和晓沧岁暮感怀次元韵 其一","f":"七言律诗","c":["万里边声倚枕听，盗羊何止有丁零！","将军妄托天公号，术士虚谈地母经。","剩有封章说初月，可无杯酒劝长星。","空山汉腊依然守，目断中原一发青。"]},{"t":"和晓沧岁暮感怀次元韵 其二","f":"七言律诗","c":["轮转谁知地四游，踆乌冷入北门幽。","秘书无效嗟刘向，秽史能传笑魏收。","消歇国谣王共马，支离党局李仇牛。","枝枝向背分寒暖，且看梅花为小留。"]},{"t":"将之南洋，留别亲友 其一","f":"七言律诗","c":["一水茫茫络五洲，此行心已遍全球。","衣冠异代图王会，书剑平生快壮游。","花幔俗探柔佛国，锦袍人上谪仙舟。","要知吾道其南意，鲁叟先言海可浮。"]},{"t":"将之南洋，留别亲友 其二","f":"七言律诗","c":["书生三十旧登坛，落拓防身剑气寒。","异国谈瀛誇海客，中天列宿愧朝官。","千年鹤爪书何苦？","一卷虬髯传未残。","独上柁楼看象纬，东南风急送青翰。"]},{"t":"将之南洋，留别亲友 其三","f":"七言律诗","c":["五载金城客闭门，拍天海气昼昏昏。","九边田牧思班壹，二帝遨游笑马援。","地陷东南浮大岛，天留豪杰救中原。","抚髀漫下英雄泪，新野应容一旅屯。"]},{"t":"将之南洋，留别亲友 其四","f":"七言律诗","c":["破荒文字走风雷，草昧思从海外开。","挟策九夷嬉凤去，携竿三岛钓鳌来。","天回博望乘槎路，人陋相如谕蜀才。","无限抱孙椎结辈，待教绝徼筑朝台。"]},{"t":"将之南洋，留别亲友 其五","f":"七言律诗","c":["万里南车过越裳，春风原不阻炎荒。","虚无龙鼎讹黄帝，郑重麟书拜素王。","骠国乐来天酒醉，鲛人市罢海珠光。","蛮花万树开如雪，难遣填胸热血凉。"]},{"t":"将之南洋，留别亲友 其六","f":"七言律诗","c":["极外占星计水程，天门残梦搅涛声。","青牛道远流沙阻，白马经荒劫火生。","看日果逢人北向，行云如送客南征。","亶洲洲上瞻尼父，海燕春风正满城。"]},{"t":"将之南洋，留别亲友 其七","f":"七言律诗","c":["骊歌声里即天涯，胡越何妨竟一家！","大海从新开世界，群山依旧拱中华。","贡金待铸先朝史，碾玉教图异域花。","岛国王侯看下拜，书生此念太豪奢。"]},{"t":"将之南洋，留别亲友 其八","f":"七言律诗","c":["南溟从古是天池，笑看鲲鹏变化时。","已遣少师先入海，可容箕子独明夷。","人来上国仍冠冕，诗出中原更鼓旗。","箧有中朝新乐府，遍传骑象戴花儿。"]},{"t":"寄答陈梦石明经即题其东溪吟章 其一","f":"七言绝句","c":["床头莸草参诗草，门外松声答水声。","坐对溪山安砚席，方田如罫赋春耕。"]},{"t":"寄答陈梦石明经即题其东溪吟章 其二","f":"古风","c":["身原博士非关{具}，天遣穷人最是诗。","消受时名但馀技，空山谁识老经师？"]},{"t":"初发韩江","f":"七言律诗","c":["韩山云气拥双旌，江上扁舟第一程。","四海客怀鸿鹄志，三春人别凤凰城。","九州有九徵吾说，南斗以南快此行。","无限雄心消不得，倚篷閒看暮潮生。"]},{"t":"次鮀浦，叠前韵","f":"七言律诗","c":["一夜东风送客旌，海门人暂驻征程。","山回阁石青连岸，江绕篷洲绿到城。","看雨市楼呼酒醉，冶春官舫载花行。","同舟共济艰难日，未免茫茫百感生。"]},{"t":"东山重修景贤楼大忠祠，次第落成，喜而有作","f":"七言律诗","c":["东山曾过昌黎伯，信国勤王更驻师。","呼石与谈前代事，铸金重拜昔贤祠。","春风游女飘遗帨，落日行人读断碑。","忠节文章坊宛在，千秋来话此心期。"]},{"t":"咏史四绝句和晓沧四首 其一 鲁仲连","f":"五言绝句","c":["六国不帝秦，赖有布衣在。","怀古独登台，斜阳满东海。"]},{"t":"咏史四绝句和晓沧四首 其二 田横","f":"五言绝句","c":["有士五百人，岛中犹可国。","何事奉头来？","秋风洛阳陌。"]},{"t":"咏史四绝句和晓沧四首 其三 赵佗","f":"五言绝句","c":["终筑朝汉台，未预诛秦会。","吕雉不能臣，伟哉南武帝。"]},{"t":"咏史四绝句和晓沧四首 其四 钱镠","f":"五言绝句","c":["十四方州富，三千战弩强。","平生愧昭谏，独未讨朱梁。"]},{"t":"鮀浦将发，寄许韫伯","f":"七言绝句","c":["别怀难共海云开，更向何人借酒杯？","本领依然心计拙，可怜还唱渭城来。"]},{"t":"哭李芷汀","f":"七言律诗","c":["布衣牢落病兼贫，南徼惊闻噩耗真。","四海名流同哭寝，千秋文苑此传人。","谈兵慷慨曾前席，钩党纷纭竟洁身。","地下鬼雄应问讯，中原如沸未维新。"]},{"t":"酒楼题句","f":"七言绝句","c":["红云四照酒光浓，开宴蓬莱顶上峰。","手拨劫尘看世界，茫茫人海战群龙。"]},{"t":"澳门有赠","f":"七言绝句","c":["海上我来寻大侠，如君何让古朱家。","北胡南越英雄在，落日萧萧广柳车。"]},{"t":"澳门杂诗 其一","f":"七言绝句","c":["五百年中局屡新，两朝柔远畅皇仁。","自颁一纸蠲租诏，坐看江山换主人。"]},{"t":"澳门杂诗 其二","f":"七言绝句","c":["遮天妙手蹙舆图，误尽苍生一字租。","前代名臣先铸错，莫将割地怨庸奴。"]},{"t":"澳门杂诗 其三","f":"七言绝句","c":["不是花门也自留，中朝全盛有人忧。","当时但笑书生见，非策方今信鹿洲。"]},{"t":"澳门杂诗 其四","f":"七言绝句","c":["大西洋国竞惊奇，前代文人易受欺。","一笑于今不相称，可怜穷已似波斯。"]},{"t":"澳门杂诗 其五","f":"七言绝句","c":["冶叶倡条编茁芽，双瞳剪水髻堆鸦。","春风吹化华夷界，真见葡萄属汉家。"]},{"t":"澳门杂诗 其六","f":"七言绝句","c":["两园新旧傍山开，花下轻车走若雷。","逢著人天安息日，亚当亲挟夏娃来。"]},{"t":"澳门杂诗 其七","f":"七言绝句","c":["天主堂高十字支，筑从新教未行时。","嵌空万石玲珑甚，独少流传景教碑。"]},{"t":"澳门杂诗 其八","f":"七言绝句","c":["谁从异代纪倭氛，曾比欧西早驻军。","犹有蜻蛉洲上客，残坊剔藓读和文。"]},{"t":"澳门杂诗 其九","f":"七言绝句","c":["白鸽巢高万木苍，沙梨兜拥水云凉。","炎天倾尽麻姑酒，选石来谈海种桑。"]},{"t":"澳门杂诗 其十","f":"七言绝句","c":["四山高拱炮台尊，海气空濛晚角喧。","落落老兵扶醉去，斜阳一抹望霞村。"]},{"t":"澳门杂诗 其十一","f":"七言绝句","c":["覆路榕阴接海堤，望洋东转望洋西。","马蛟石上看潮立，十万军声战水犀。"]},{"t":"澳门杂诗 其十二","f":"七言绝句","c":["谁报凶酋发冢冤，宝刀饮血月黄昏。","要携十斛葡萄酒，来酹秋原壮士魂。"]},{"t":"澳门杂诗 其十三","f":"七言绝句","c":["楼台金碧拥南环，灯火千门夜不关。","满地烟花春似海，三更人立磨盘山。"]},{"t":"澳门杂诗 其十四","f":"七言绝句","c":["银牌高署市门东，百万居然一掷中。","谁向风尘劳物色？","博徒从古有英雄。"]},{"t":"澳门杂诗 其十五","f":"七言绝句","c":["仙洞云封万竹深，隔江胜地负登临。","倚楼幻作蓬瀛想，一角青洲出海心。"]},{"t":"叠韵答潘兰史送别 其一","f":"七言律诗","c":["潮气濛濛岛屿青，客心南去极沧溟。","人逢裸国章缝贱，山入蛮荒草木腥。","兵火未消天狗劫，风雷犹奉野狐灵。","无穷万里乘槎意，不为来看海上星。"]},{"t":"叠韵答潘兰史送别 其二","f":"七言律诗","c":["刀光寒闪鸊鹈膏，侠胆消沉客路劳。","禁卫全军归吕禄，中原重镇付朱滔。","金牛假道愁归蜀，石马传文诧共槽。","海外且寻徐福去，蓬莱极目五云高。"]},{"t":"叠韵答陆敬南","f":"七言律诗","c":["亚雨欧风郁不开，闻鸡人正渡江来。","箧留表饵平戎策，梦绕旌旗拜将台。","地尽中原逢大海，天当乱世出奇才。","填胸垒块浇难化，百尺楼高借酒杯。"]},{"t":"答敬南见赠，次原韵 其一","f":"五言绝句","c":["一石天下才，敢云独八斗。","郁郁信陵君，平生付醇酒。"]},{"t":"答敬南见赠，次原韵 其二","f":"五言绝句","c":["名士刘景升，世家袁公路。","把酒论英雄，彼哉何足数！"]},{"t":"答敬南见赠，次原韵 其三","f":"五言绝句","c":["世无仓海君，谁发诛秦意？","一击天下惊，奋起龙虎气。"]},{"t":"答敬南见赠，次原韵 其四","f":"五言绝句","c":["尉佗昔帝粤，独为陆生折。","宝剑千金装，南来景前哲。"]},{"t":"题兰史望罗浮图，次原韵","f":"七言律诗","c":["奇峰四百三十二，别后相思不计年。","寻梦客迷蝴蝶洞，看山秋上老龙船。","前身葛令仙为耦，左股蓬莱海化田。","风雨迷离图未得，诗魂寒渡瀑云边。"]},{"t":"题兰史西樵揽胜图","f":"七言古诗","c":["山气化云云化水，玉龙飞挂空山里。","七十二峰云水中，仙人夜半呼龙起。","空山有客晨搜奇，濛濛龙气寒须眉。","消遥台上吸云水，散作人间无数诗。","我来寻山看龙挂，犹幸读诗如读画。","朅来复见揽胜图，置身忽入清凉界。","此山自合巢古仙，谁教凿险通人烟？","世人奔走仙人笑，山中讲学声琅然。","奇峰尽矗青莲朵，何意人间飞劫火。","神仙楼变豪客居，古洞碑流党人祸。","山中流水长潺潺，山云一出何时还。","我披画图望云水，七十二峰相对閒。","安得将山还大古，谢绝时人作山主。","餐云饮水吟仙诗，呼龙耕烟垦瑶圃。"]},{"t":"欧冶子歌","f":"古风","c":["噫嘻乎嗟哉！","魔风夜扇大海水，妖鸟西飞金两翅，飞啄群龙龙半死。","神龙不死何时起，金仙铅泪流不止。","此劫茫茫古无似，不数汉家燕啄矢。","谁为铸剑歼厥妖？","当代吾思欧冶子。","于时日蚀团黄月华紫，乃采天精抉地髓。","天帝下观万灵侍，雷公、电母、风伯、雨师听驱使。","祥金跃出洪炉里，铸成双剑神无比。","昆崙为砺沃礁砥，陆斩虎狮水剧兕。","妖鸟哀号张大嘴，群魔乞命等羊豕。","一挥再挥试神技，乃使五洋沉军舰、六洲平战垒。","于是天地乃清宁，璧合二仪珠五纬。","告太平者有太史，一统之朝古无此。","神剑依然发刃始，老我不才称剑士，布衣长揖归田里。","噫嘻乎嗟哉！","当代吾思欧冶子。"]},{"t":"题骆宾王集 其一","f":"七言绝句","c":["义师散后遁僧寮，老抱雄心托浙潮。","此笔江河流万古，多因曾檄伪临朝。"]},{"t":"题骆宾王集 其二","f":"七言绝句","c":["凤阁鸾台宰相忙，此才竟令落蛮荒。","若将文字论知己，惟有当时武媚娘。"]},{"t":"九龙有感","f":"七言绝句","c":["群峰叠翠倚楼间，一角颓云夕照殷。","忽忆去年春色里，九龙还是汉家山。"]},{"t":"纪事 其一","f":"七言绝句","c":["阊阖沉沉路不通，封章空自效愚忠。","人间漫诧朝阳凤，已落罗钳吉网中。"]},{"t":"纪事 其二","f":"七言绝句","c":["何止诛求在市租，上供祗道急军需。","相公南下纡筹策，报国居然仗博徒。"]},{"t":"七洲洋看月放歌","f":"楚辞体","c":["一舟之外天连水，万里空明月轮起。","七洲洋里看月行，数遍春宵古无此。","舟行双轮月只轮，青天碧海无纤尘。","茫茫海水镕作银，著我飞楼缥缈独立之吟身。","少陵太白看月不到处，今宵都付渡海寻诗人。","月轮天有居人在，中间亦有光明海。","不知今宵可有南去乘舟人，遥望地球发光彩。","地球绕日日一周，日光出地月所收。","此时月光照不到，尚有大地西半球。","此时月光随我来南游，大千界中有此舟。","更著此月来当头，舟中吴讴答越讴。","月光夜照花枝幽，中有蛮姬十队并作天魔舞。","东音西音四起声咿嚘，嫦娥应自怨幽独，不及人间儿女同无愁。","安知人海群龙方血战，蜗国蚊巢纷告变。","月光遍照六大洲，万怪千奇机械见。","剩此同舟胡越犹一家，各抱月华共欢宴。","自从中朝海禁开，年年月月泛月有人来。","忽然今月属吾有，此时此地此景真奇哉！","吸月屡罄葡萄杯。","独惜南溟岛国尽隶他人属，坐叹热带之下无雄才。","人间万事纷变灭，方见月圆旋月缺。","四万八千修月仙，玉斧长劳竟何说。","固知盈亏之理原循环，大地山河终古不改色。","即今圆相虽未全，一出已令天下悦。","天上之月海底明，上下两月齐晶瑩。","两月中间一舟走，飞轮碾海脆作玻璃声。","月兮西落而东生，北舟莽莽方南行。","天经自纵地纬横，此时吐吞八极诗方成，天鸡喔喔呼潮鸣。","自是诗中海权大，万里南天开海界。","月华夜夜供豪吟，月神不怪海神怪。","明朝待看海上无数之奇峰，明宵舟泊宾童龙。","澜沧江头看月去，江花江柳春溶溶。"]},{"t":"昆崙","f":"七言绝句","c":["茫茫天水气相吞，大海中浮独岛尊。","不见神龙见神鸟，七洲洋外望昆崙。"]},{"t":"二月十五日抵西贡作","f":"七言律诗","c":["楼台金碧国旗飘，吹角江头虏气骄。","地极南交逢热带，人来西贡作花朝。","椰林草屋蛮跳月，绿舫红灯客守潮。","走遍香车堤岸路，不曾辜负好春宵。"]},{"t":"西贡杂诗 其一","f":"七言绝句","c":["七洲洋外海程遥，竟夕扬轮趁晓潮。","九十九湾春水曲，澜沧江上作花朝。"]},{"t":"西贡杂诗 其二","f":"七言绝句","c":["岂独开疆自汉秦，南车久已载皇仁。","谁知富贵誇真腊，竟属黄须碧眼人。"]},{"t":"西贡杂诗 其三","f":"七言绝句","c":["力遣孱王摄虎威，残疆何止割南圻。","云山北向空挥泪，孤负遗民望黑旗。"]},{"t":"西贡杂诗 其四","f":"七言绝句","c":["未肯洋装换越装，金环椎髻素衣裳。","传经但读祛卢字，遗教无人说士王。"]},{"t":"西贡杂诗 其五","f":"七言绝句","c":["水程几日达高棉，山势南趋尽越边。","一夜黄花江水长，满堤金塔卖鱼船。"]},{"t":"西贡杂诗 其六","f":"七言绝句","c":["绿树双堤护走车，隔帘鹦鹉听呼茶。","独怜呜咽琵琶语，半是珠江落后花。"]},{"t":"西贡杂诗 其七","f":"七言绝句","c":["槟榔红嚼蛎灰腥，粲露瓠犀醉半醒。","交趾不逢逢黑齿，大荒重记百虫经。"]},{"t":"西贡杂诗 其八","f":"七言绝句","c":["吾乡大令昔生还，风土蛮荒记最娴。","江上愁吟香祖句，不堪回首念家山。"]},{"t":"西贡杂诗 其九","f":"七言绝句","c":["多少蛮姬理夜香，当门红烛荡花光。","可怜膜拜西天佛，管领真归大法王。"]},{"t":"西贡杂诗 其十","f":"七言绝句","c":["金碧楼台眼界新，竞将工巧诧西人。","竹篱茅舍清江上，几树幽花本色春。"]},{"t":"舟中望茶盘山","f":"七言绝句","c":["沧波无际夕阳红，孤屿苍茫大海中。","水墨痕浓云脚矮，茶盘山外雨濛濛。"]},{"t":"饮新嘉坡觞咏楼，次菽园韵 其一","f":"七言绝句","c":["春风海上客徵歌，消受群花眼福多。","我比石斋尤豁达，不妨坐抱顾横波。"]},{"t":"饮新嘉坡觞咏楼，次菽园韵 其二","f":"七言绝句","c":["风云万里郁神州，人醉天南第一楼。","唱遍南朝新乐府，最难天子是无愁。"]},{"t":"天南第一楼放歌","f":"七言古诗","c":["亚洲一片云头恶，群花摧折雌风虐。","护花幡立海东南，裼裘公子方行乐。","千红万紫开春中，团圆月照何王宫。","粗豪莫笑虬髯客，妩媚全胜羊鼻公。","第一楼头人第一，天女散花香满室。","中宵醉卧海云红，梦遣黄人捧朝日。"]},{"t":"星洲喜晤容纯甫副使，即送西行 其一","f":"五言律诗","c":["吾国有爹亚，将为欧美游。","艰危天下局，慷慨老成谋。","新运开三世，雄心遍五洲。","南华楼上话，一夕定千秋。"]},{"t":"星洲喜晤容纯甫副使，即送西行 其二","f":"五言律诗","c":["七十尚如此，吾徒愧壮年！","排云叩阊阖，救日出虞渊。","异域扶公义，神州复主权。","柬之原未老，终仗力回天。"]},{"t":"星洲喜晤容纯甫副使，即送西行 其三","f":"五言律诗","c":["廿载知名久，相逢瘴海春。","亚洲数先达，岭表有奇人。","南出终张楚，西行更哭秦。","风云看勃郁，万里送飞轮。"]},{"t":"答叶季允见赠 其一","f":"七言绝句","c":["平生风义柳堂门，雄直依然粤派存。","谁料南荒柔佛国，听松庐更有诗孙。"]},{"t":"答叶季允见赠 其二","f":"七言绝句","c":["万里飞腾志未乖，海山苍莽遣吟怀。","他年岛国传流寓，诗屋人寻豆腐街。"]},{"t":"答叶季允见赠 其三","f":"古风","c":["廿载风尘粤客装，?公山远郁苍苍。","自来海外称诗老，更望佗城作故乡。"]},{"t":"答叶季允见赠 其四","f":"七言绝句","c":["劳赠才人绝妙词，天涯有客遍搜奇。","独怜荒峤来相语，绝少韩陵一片碑。"]},{"t":"舟过马六甲 其一","f":"七言绝句","c":["南风吹雨片帆斜，万叠山青满剌加。","欲问前朝封贡事，更无人说故王家。"]},{"t":"舟过马六甲 其二","f":"七言绝句","c":["碧眼胡儿拜武皇，贡书犹托岛中王。","直陈藩国流离状，曾有吾家侍禦章。"]},{"t":"舟过马六甲 其三","f":"七言绝句","c":["荒山中尚有遗民，一死居然与古邻。","赢得盖棺遮短发，四方平定铁崖巾。"]},{"t":"由星嘉坡抵槟榔屿舟中口号","f":"七言绝句","c":["柔佛国中逢上巳，槟榔屿里作清明。","匆匆雾鬓风鬟影，饱看春山两日程。"]},{"t":"游阿易意淡观音阁，次壁间韵","f":"七言律诗","c":["不使南荒劫火燃，流沙黑水且安禅。","六时梵呗潮音静，千眼灵光宝相圆。","出洞猿携山果献，归巢鹤抱海云眠。","诸天也藉黄金力，变现西方九品莲。"]},{"t":"槟榔屿杂诗 其一","f":"七言绝句","c":["谷绣林香万树花，青崖飞瀑落谽谺。","谁知地下潜流出，散作春泉十万家。"]},{"t":"槟榔屿杂诗 其二","f":"七言绝句","c":["海外居然谱学通，衣冠休笑少唐风。","黄金遍铸门楣字，不数崔卢郡望崇。"]},{"t":"槟榔屿杂诗 其三","f":"七言绝句","c":["一轮月照万花娇，歌管声中长夜潮。","宝马香车春似海，打球场外看元宵。"]},{"t":"槟榔屿杂诗 其四","f":"七言绝句","c":["走马交衢碾白沙，椰阴十里绿云遮。","晓风吹出山蜂语，开遍春园豆蔻花。"]},{"t":"槟榔屿杂诗 其五","f":"七言绝句","c":["雾阁云窗启道场，不须极乐数西方。","山僧指引频誇客，顶礼曾来白象王。"]},{"t":"道君岩","f":"七言律诗","c":["论治人方咎祸胎，化胡更向海天来。","青牛西域流沙远，朱鸟南荒古洞开。","聚窟乳泉飞法雨，空岩蛮语答春雷。","独怜混沌年年凿，谈道难教劫运回。"]},{"t":"南道院 其一","f":"七言律诗","c":["宝气搜残剩石头，石玲珑化洞天幽。","三分得水知鱼乐，九曲看人作蚁游。","荒外有山容道侣，海中无地不瀛洲。","他年补入神仙传，曾费骖鸾半日留。"]},{"t":"南道院 其二","f":"七言律诗","c":["林外方塘塘外山，洞门高下锁烟鬟。","藤阴满院闻蝉语，云气当轩待鹤还。","绝妙文心惟曲折，最难仙福是清閒。","海天归去犹留梦，他日相思浩渺间。"]},{"t":"自题南洋行教图 其一","f":"七言绝句","c":["莽莽群山海气青，华风远被到南溟。","万人围坐齐倾耳，椰子林中说圣经。"]},{"t":"自题南洋行教图 其二","f":"七言绝句","c":["二千五百馀年后，浮海居然道可行。","独倚斗南楼上望，春风回处紫澜生。"]},{"t":"留别晓沧，次题行教图韵","f":"五言古诗","c":["南风吹大海，日轨走南陆。","我行君尚留，慷慨念时局。","神方置不用，谁起国病笃？","同抱救世心，栖栖行海曲。","空言要何补？","长身祗食粟。","此来已三月，共惜流光速。","群山送我行，海气清而肃。","眷念君平生，抱道过王蠋。","临歧为我歌，高响振林木。","林中双异鸟，飞鸣正相逐。","勉哉保令名，何必愧异服。"]},{"t":"舟泊吉隆","f":"七言绝句","c":["巴丁江上驻游踪，倚柁微吟望远峰。","一夜双轮乘月去，计程明日到芙蓉。"]},{"t":"芙蓉 其一","f":"七言绝句","c":["林里交柯万树花，出林楼阁倚朱霞。","一生长在芙蓉住，羡煞江头卖酒家。"]},{"t":"芙蓉 其二","f":"七言绝句","c":["海山缥缈客心分，锦字天涯隔暮云。","独向芙蓉江上望，远峰眉黛忆文君。"]},{"t":"客楼夕感","f":"七言律诗","c":["海色天容入望遥，凭阑心事涌如潮。","茫茫泥雪徵鸿急，隐隐车雷虏马骄。","万叠蛮云开热带，一轮娥月送凉霄。","好风不为吹愁去，银烛清樽伴寂寥。"]},{"t":"南还抵汕头埠，闻琰儿、球儿殇耗，哀感书此 其一","f":"七言绝句","c":["频年痛哭为哀时，谁料今朝更哭儿。","拟遣灵龟向天问，挑灯和泪读韩诗。"]},{"t":"南还抵汕头埠，闻琰儿、球儿殇耗，哀感书此 其二","f":"七言绝句","c":["扁舟劫外侍东还，投劫安知在此间。","阿弟六龄兄十六，九泉风雨念家山。"]},{"t":"南还抵汕头埠，闻琰儿、球儿殇耗，哀感书此 其三","f":"七言绝句","c":["望尔成人竟不成，中年哀感倍伤神。","青山何处埋儿骨，黯黯愁云隔凤城。"]},{"t":"南还抵汕头埠，闻琰儿、球儿殇耗，哀感书此 其四","f":"七言绝句","c":["全家避地古梅州，独客南归尚滞留。","夜夜雏魂梦中见，寒潮呜咽浪西楼。"]},{"t":"南还抵汕头埠，闻琰儿、球儿殇耗，哀感书此 其五","f":"七言绝句","c":["食厉偏难恃女媊，便非英物也悽然。","欲呼群力新中国，已失人间两少年。"]},{"t":"南还抵汕头埠，闻琰儿、球儿殇耗，哀感书此 其六","f":"七言绝句","c":["弧矢男儿志四方，河山北望战云黄。","可怜竟背爷娘去，不共汪锜作国殇。"]},{"t":"秋日藕华枉过山居，次元韵四首 其一","f":"七言绝句","c":["混俗仙人钟颖阳，劫尘世界少班行。","骑驴晓入秋山里，来看丹枫万树霜。"]},{"t":"秋日藕华枉过山居，次元韵四首 其二","f":"七言绝句","c":["天冠山下野人居，除却渔樵少往来。","今日谪仙劳过访，看山还费赋诗才。"]},{"t":"秋日藕华枉过山居，次元韵四首 其三","f":"七言绝句","c":["拟种山中万树梅，花时香雪定成堆。","如何尚未锄明月，已有神仙跨鹤来。"]},{"t":"秋日藕华枉过山居，次元韵四首 其四","f":"七言绝句","c":["满路秋花散晚香，一尊人醉万松堂。","呼云送客出山去，金简峰头初夕阳。"]},{"t":"阴那山行","f":"古风","c":["五岭东来势忽止，阴那山自云中起。","山在云中不可见，得云山乃留真面。","我生爱山尤爱云，策马寻山看云变。","阴那之奇无不有，擎空突兀拿云手。","大云放作天下雨，小云留赠山中友。","登山不学昌黎哭，游山岂作开云祝？","高秋十日云沉沉，山灵知客嫌秋阴。","狞云忽散秋宇净，古柏荣枯护禅定。","倚天五叶开青莲，奇峰顿落琳宫前。","上有飞仙来往之天桥，下有茶香万斛之流泉。","山中寺古逾千年，开山何人潘了拳。","金光明现身丈六，昔曾入梦来清源。","吁嗟乎！","占山须占天下奇，作佛须作云雨师。","万里中原腾旱气，愿驱群云出山去。","留云不遣遣云阴，山与祖师俱惭愧。"]},{"t":"灵光寺晚眺 其一","f":"七言绝句","c":["般若台荒噪暮鸦，香炉峰冷挂残霞。","夕阳尽作燕支色，染出秋林树树花。"]},{"t":"灵光寺晚眺 其二","f":"七言绝句","c":["三柏生枯气郁苍，沉沉紫殿梵云凉。","绿杉野屋隔溪水，牧笛数声山月黄。"]},{"t":"灵光寺晚眺 其三","f":"七言绝句","c":["尽洗苏王伪体篇，空山飞瀑泻寒烟。","山灵自展凌云手，妙写馀霞散绮天。"]},{"t":"灵光寺晚眺 其四","f":"七言绝句","c":["将军席罢梅仍落，学士轩空柏自留。","犹有旧时明月在，照人来作闰中秋。"]},{"t":"王寿山诗十首 其一","f":"七言绝句","c":["百盘路尽是山门，避世人犹宅址存。","消受桃花千万树，梵王宫占武陵源。"]},{"t":"王寿山诗十首 其二","f":"七言绝句","c":["广福庵寒锁落花，开山初祖属吾家。","欲寻凤髻峰前塔，斜日秋林噪暮鸦。"]},{"t":"王寿山诗十首 其三","f":"七言绝句","c":["下方僧院众山巅，百折林梢路更前。","绝顶别开新世界，濛濛花雨散诸天。"]},{"t":"王寿山诗十首 其四","f":"七言绝句","c":["秋河挂树露华浓，残月衔山起听钟。","花影满身寒不寐，不知身在最高峰。"]},{"t":"王寿山诗十首 其五","f":"七言绝句","c":["仙人去后碧云寒，丹灶无烟玉井乾。","留得残棋一枰石，秋风吹客话长安。"]},{"t":"王寿山诗十首 其六","f":"七言绝句","c":["眼底闽山与粤山，霸图山色有无间。","老僧不管人间世，黄叶满林秋闭关。"]},{"t":"王寿山诗十首 其七","f":"七言绝句","c":["鸣鸠春路忆幽探，耆旧遗闻选石谈。","埋碧千年应不化，重镌诗碣蔡梅庵。"]},{"t":"王寿山诗十首 其八","f":"七言绝句","c":["遗墨残山觅旧劖，空林凉碧坠松杉。","珊瑚宝玦消磨尽，满目寒云帝子岩。"]},{"t":"王寿山诗十首 其九","f":"七言绝句","c":["何处寒薇问首阳，名山竟遣落蛮荒。","秋心瘦入诗人骨，箬笠峰头夕照黄。"]},{"t":"王寿山诗十首 其十","f":"七言绝句","c":["万方多难此登临，满径幽兰石气阴。","欲把离骚当梵唱，谶除香草美人心。"]},{"t":"画兰曲","f":"七言古诗","c":["秋风吹冷松江水，谢览兰芳仍竟体。","晴窗搦笔写秋英，芳心不向霜前死。","眼中九畹无閒田，突兀拳石安花间。","花幽石瘦各自媚，风茎露叶何娟娟？","北平今日谁飞将？","一枕幽香酣玉帐。","借花陶写英雄心，岂特离骚当梵唱？","梦破中原夕照红，幽兰开落荒山中。","莫教无土孤根露，花里残经写大空。"]},{"t":"题叶婉仙女史古香阁集三首 其一","f":"七言绝句","c":["修竹娟娟翠袖单，六铢衣薄不胜寒。","新词一卷疏香阁，煮梦仙人叶小鸾。"]},{"t":"题叶婉仙女史古香阁集三首 其二","f":"七言绝句","c":["福慧双修竺落宫，玉楼人去锦屏空。","翩翩独立人间世，赢得香名饮粤中。"]},{"t":"题叶婉仙女史古香阁集三首 其三","f":"七言绝句","c":["滴粉搓酥绮意新，溶溶梅水写丰神。","桐花阁外论词笔，更遣香闺作替人。"]},{"t":"天上","f":"七言律诗","c":["天上何曾可寄愁，逍遥聊学漆园游。","云山北向迷三晋，禾黍东迁痛二周。","漠漠虫沙仙脱劫，冥冥龙夜客哀秋。","荒鸡风雨无人语，四海当时一子由。"]},{"t":"古大夫宅下马石歌","f":"古风","c":["七百年来掩尘土，石与大夫俱氏古。","大夫何许人？","乃是紫虚仙人四世孙。","宅在梅州州北门。","眼前不见大夫宅，止见大夫下马石。","石立宣和之四年。","大夫手铸镇宅钱。","古钱出土铜锈紫，留与后人知宅址。","钱铸何年石能语，此石不刻党人碑，又不贡筑艮岳兼花移。","大夫五马何逶迤？","留题七星岩石方来归。","大夫归来立石日，天子尚未蒙尘时。","当国者谁蔡太师。","吁嗟时事已可知。","大夫下马心应悲，朝更代改宅何有？","大夫名在马骨朽。","惟有此石长不刓，大书深刻苔花寒。","摩挲欲具袍笏拜，当作到氏奇礓看。"]},{"t":"南汉敬州修慧寺千佛铁塔歌","f":"七言古诗","c":["五金之用铁为广，惜哉竟付降王长。","上供铸柱下铸床，更铸贪痴佞佛想。","有铁不遣铸五兵，又不铸器资民生。","峨峨两塔奉敕造，民间观者如风倾。","梅水东来避灾地，上有先朝修慧寺。","眼中突兀窣堵波，不惜乌金铸文字。","谁欤铭者工祝词，贤劫千佛森威仪。","皇图欲仗佛力固，安知天降香孩儿。","一铁围山一世界，劫火中烧万法坏。","巍然此塔九百年，相轮夜转罡风快。","岂惟牛角难长延，眼看宋蹶元明颠。","敬州遗事共谁说，塔端铃语缺不圆。","塔铸何时岁乙丑，有大力者负以走。","十五乙丑塔乃倾，敢信佛缘能不朽。","自从象教嗟中衰，中分净土参耶回。","竞假天堂地狱说，乘虚与佛争东来。","东来明星张国燄，炮雨枪云铁飞舰。","天经唪罢万灵噤，海旂飐处千官谄。","与之抗者谈真空，白莲万朵开魔风。","谁云此獠有佛性，妖腾怪踔巾何红？","此亦当今一张角，满地黄花乱曾作。","国成谁秉邪召邪，聚铁群惊铸此错。","黄金台边铁血殷，六龙西幸趋函关。","麻鞋何日见天子？","小臣足茧哀荒山。","梅山苍苍梅水碧，雄心陶写付金石。","眼駴残铁南汉年，古锈斑斓铁花积。","当时铸者知何人，寺荒塔坏朝屡新。","小南强花空供养，即今诸佛无完身。","铁不得用铁之辱，海风夜啸蛟涎浊。","神州莽莽将陆沉，诸天应下金仙哭。","谓佛不灵佛傥灵，睡狮一吼狞而醒。","破敌神兵退六甲，开山力士驱五丁。","五岭雄奇积煤铁，矿政未修民曷殖！","地不爱宝资中兴，会须富国兼强国。","吾国平等存佛心，纷纷种教休交侵。","行看手铸新世界，采山有诏需南金。","人天同庆回末劫，王气宁容霸气杂。","神力永镇阎浮提，何须四万八千塔？"]},{"t":"重晤梁辑五光禄话旧 其一","f":"七言绝句","c":["铜狄重摩定惘然，春明旧梦岁周天。","与君同话沧桑劫，已抵仙人五百年。"]},{"t":"重晤梁辑五光禄话旧 其二","f":"七言绝句","c":["风雅都从变后奇，古来词客惯哀时。","可怜倒海倾河泪，独立苍茫但咏诗。"]},{"t":"戏为张叟题麻姑进酒图 其一","f":"七言绝句","c":["人间游戏太风情，混沌初分蝙蝠精。","勾引麻姑来侍酒，须妨妒煞老方平。"]},{"t":"戏为张叟题麻姑进酒图 其二","f":"七言绝句","c":["多恐麻姑鬓亦霜，蓬莱清浅海栽桑。","还丹要乞馀杭姥，三少鸡皮却老方。"]},{"t":"戏为张叟题麻姑进酒图 其三","f":"七言绝句","c":["不须成佛不生天，纳纳乾坤任放颠。","解识妇人醇酒趣，英雄退步便神仙。"]},{"t":"观澜亭题壁，亭旁有庵供佛 其一","f":"七言绝句","c":["万山难阻水宾士，地陷东南出百夷。","不信狂澜回不得，西风倚剑独题诗。"]},{"t":"观澜亭题壁，亭旁有庵供佛 其二","f":"七言绝句","c":["我佛如怜国债深，山河大地变黄金。","莲台冷袖兜罗手，半壁尘丝古殿阴。"]},{"t":"久旱得雨初霁，饮人境庐，时闻和局将定二首 其一","f":"七言律诗","c":["忍把乾坤付醉乡，登楼休负好秋光。","黄龙约改清钟酒，白雁声催故国霜。","老树半凋开远目，菊花无恙展重阳。","美人消息来何暮？","怅望秦云各尽觞。"]},{"t":"久旱得雨初霁，饮人境庐，时闻和局将定二首 其二","f":"七言律诗","c":["得雨虽迟也胜无，东皋预计麦苗苏。","青天转粟趋行在，黄海传烽迫上都。","已叹鳌翻难立极，岂容龙醒更遗珠。","至尊薪胆劳明诏，醉抚横腰玉鹿卢。"]},{"t":"用前韵赋答人境卢主见和之作 其一","f":"七言律诗","c":["无物消愁且举觞，自拚千日醉程乡。","谁张仙乐迎金母？","漫诧神兵下玉皇。","竭井难医狂国病，剪灯空吊女宫殇。","白莲飘尽黄莲死，惆怅尊前说酒王。"]},{"t":"用前韵赋答人境卢主见和之作 其二","f":"七言律诗","c":["百二河山未定都，金鳌戴主谶原诬。","日回旧驭长安远，月送残更太白孤。","钩党重翻十常侍，玺书新款五单于。","群公休守偏安局，推背犹存一统图。"]},{"t":"三用前韵奉答 其一","f":"七言律诗","c":["浮云西北郁苍苍，残角秋城泪万行。","朋党祸仍流丑相，太平功竟录申王。","眼中木槿花荣落，身后梧桐树短长。","自把千秋付杯酒，湖山无恙脍莼香。"]},{"t":"三用前韵奉答 其二","f":"七言律诗","c":["狼星妖燄压威弧，八部群龙护曼殊。","朱果在天持剥运，黄花满地祸神都。","入山我自寻青主，望海人谁鉴黑奴？","汉德未衰豪杰出，不须重唱鼓咙胡。"]},{"t":"四用前韵奉答 其一","f":"七言律诗","c":["沧海尘蒙镜殿光，公卿同哭牝朝亡。","河阴兵问充华罪，乐府歌残妩媚章。","往事数钱怜奼女，异邦传檄过宾王。","枉崇圣母无生法，难遣神兵禦列强。"]},{"t":"四用前韵奉答 其二","f":"七言律诗","c":["延秋门冷夜啼乌，宝玦王孙泣路隅。","已弃此身同腐鼠，有威平日假妖狐。","北庭飞雪行头远，南斗流星应象殊。","待唱迎鸾收野哭，五陵佳气未全无。"]},{"t":"雨中游祥云庵五用前韵 其一","f":"七言律诗","c":["九州谁土是吾乡，无地埋忧问佛忙。","黯黯山容都入睡，冥冥云气果何祥！","当关虎豹愁逢石，在水鼋鼍懒架梁。","忽策青骡思蜀道，雨中铃语太郎当。"]},{"t":"雨中游祥云庵五用前韵 其二","f":"七言律诗","c":["未解天心悔祸无，干戈满地客愁孤。","分争净土魔何众，遁守荒山佛太愚。","家法老僧惟托钵，人言群盗尚偷珠。","西风泪洒山门柳，蚀尽秋虫守旧株。"]},{"t":"六用前韵奉答 其一","f":"七言律诗","c":["秋色西来接太行，故乡回首虏尘黄。","凄凉汾水沾衣泪，仓卒芜亭煮麦香。","岁币桧伦迟款敌，军书操绍托勤王。","斜阳万里桥边路，谁奉当归祝上皇。"]},{"t":"六用前韵奉答 其二","f":"七言律诗","c":["纵不人诛亦鬼诛，生灵百万死何辜！","断难大义容三叔，休遣清谈禦五胡。","行在阳秋书待著，广明庚子事原殊。","中朝国法兼家法，遏必隆刀可在无！"]},{"t":"游西岩灵境院七用前韵 其一","f":"七言律诗","c":["七百年中电火忙，元城游处佛灵彰。","后来鹦鹉新禅长，曾忤猢狲旧队王。","山尚有神能迓客，僧关何党亦投荒。","行人难解衰朝恨，黄叶空林话夕阳。"]},{"t":"游西岩灵境院七用前韵 其二","f":"七言律诗","c":["绿失榕阴老树枯，津梁疲后佛心孤。","劫尘西起遮灵鹫，禅派东来出野狐。","何事挥拳学僧耳，共惊遗教演鸿儒。","登高欲写哀时意，十里残山叫蟪蛄。"]},{"t":"闻歌有忆，八用前韵 其一","f":"七言律诗","c":["碧落归来旧侍郎，钧天寻梦泪沾裳。","皇娥倚瑟歌何艳！","王母开筵乐未央。","龙汉劫深愁魃舞，蚩尤兵迫罢娲簧。","瑶池小队停仙俸，齐向西华祝吉祥。"]},{"t":"闻歌有忆，八用前韵 其二","f":"七言律诗","c":["渺渺瑶京帝所都，霓裳故部尚存无？","九龙欲窃天公位，四象全翻太极图。","此劫本来关运会，诸仙平日太嬉娱。","可哀休唱人间曲，颠倒先将斗柄扶。"]},{"t":"九用前韵 其一","f":"七言律诗","c":["满目狮章更鹫章，沉沉龙气不飞扬。","秋风石马昭陵恸，夜雨金牛蜀道长。","元老治军收白虢，中朝厄闰等黄杨。","若教死殉论忠义，何止区区李侍郎！"]},{"t":"九用前韵 其二","f":"七言律诗","c":["金币全输玉并俘，止兵幡未下驺虞。","六宫急作抛家髻，三界难飞召将符。","殿下雷颠尝大敌，军中风角走妖巫。","即今神圣犹争颂，莫笑当时莽大夫。"]},{"t":"十用前韵 其一","f":"七言律诗","c":["一笑当时果灭洋，红巾白帽满朝堂。","花门首出中兴将，米贼兼封异姓王。","铜版令严诛异教，铁牌制毁奏权珰。","可怜刻木牵丝拙，袍笏空登傀儡场。"]},{"t":"十用前韵 其二","f":"七言律诗","c":["竟难赤黑辨狐乌，眼底云成万变图。","名士穷搜呼作贼，王孙苦道乞为奴。","茝兰沉恸留湘水，禾黍馀哀恋亳都。","涕泪新亭果何益，有人江左薄夷吾。"]},{"t":"十一用前韵 其一","f":"七言律诗","c":["不须复古但尊王，一旅终兴夏少康。","菜叶西风今冷落，茄花满地旧披猖。","传书漫遣三青鸟，贡品休徵四白狼。","马上黄尘犹眯目，早教帘撤圣神皇。"]},{"t":"十一用前韵 其二","f":"七言律诗","c":["河山北戒郁盘纡，天险关门旧备胡。","九庙未迁先世鼎，两京谁扫故宫芜！","悲歌易水无豪侠，买骨金台有钝驽。","往事怕谈元代史，曾收西域略忻都。"]},{"t":"重游清凉洞，呈钟藕华二首 其一","f":"七言绝句","c":["五年梦绕清凉洞，猿鹤青山待我来。","添得两行家国泪，西风吹上会仙台。"]},{"t":"重游清凉洞，呈钟藕华二首 其二","f":"七言绝句","c":["缤纷花雨散瑶林，持帚仙童倚树吟。","莫扫天香落人世，中原逐鹿劫尘深。"]},{"t":"燕子岩","f":"五言古诗","c":["佛寺藏山间，仙岩伏寺后。","世少好事人，奇境閟荒陋。","白昼秉烛游，青山携鹤友。","入寺复出寺，呀然见洞口。","守门无仙犬，容我踏云走。","引人渐入胜，平步势不陡。","殿宇当中开，千人坐能受。","远怀混沌初，巧出造化手。","万石造一洞，一洞含万有。","备具人物形，胚胎脱怪丑。","藏之九地底，遂致长不朽。","涉冬石气温，留观遂能久。","石燕殊骄人，钟乳富自守。","举族作仙禽，得天抑何厚？","谁实开杀机，采捕入药臼。","为袪六气淫，致损千年寿。","嗟尔洞天居，安乐焉可狃。","大声自何来，隐作风雷吼。","疑为地轴转，否或潜龙斗。","我欲往探之，阴沉不可究。","于时烛见跋，天光时隐漏。","入洞复出洞，石云湿两袖。"]},{"t":"钟文南太守自美洲回里赋赠二首 其一","f":"七言绝句","c":["九万里程环地底，四千年史创皇初。","别开揖让征诛局，山海重编化益书。"]},{"t":"钟文南太守自美洲回里赋赠二首 其二","f":"七言绝句","c":["纽约铁桥天下稀，男儿壮志未应违。","班超万里封侯去，陆贾千金奉使归。"]},{"t":"次韵奉答藕华 其一","f":"七言绝句","c":["烈烈南风沙扑天，武陵安稳种仙田。","桃花流水无今古，閒过苍鹅出地年。"]},{"t":"次韵奉答藕华 其二","f":"七言绝句","c":["伴食纶扉几日开，紫垣惊见坼三台。","东门黄犬华亭鹤，都入香山感事来。"]},{"t":"次韵奉答藕华 其三","f":"七言绝句","c":["响遏珠尘落殿楹，瑶池春宴按歌情。","不知零落云韶部，可向秦楼逐凤鸣。"]},{"t":"次韵奉答藕华 其四","f":"七言绝句","c":["啄屋乌多燕子稀，黑云如墨压城围。","寻常百姓无家别，不独乌衣巷已非。"]},{"t":"次韵奉答藕华 其五","f":"七言绝句","c":["休向人间更赋哀，迢迢云汉待昭回。","擎天各展黄人手，重捧红轮出海来。"]},{"t":"南岩均庆寺诗四首 其一","f":"五言古诗","c":["万山围一城，闽粤此钥锁。","一岩瞰城立，一佛踞岩坐。","旁立古女仙，遣容何婀娜？","传闻昔争墩，此语恐未果。","如何岩巅石，莲印遍磊砢。","入岩岩转深，岩势侧而椭。","岩居金色身，炉烟袅古火。","岩腹蓄乳泉，时作天花堕。"]},{"t":"南岩均庆寺诗四首 其二","f":"五言古诗","c":["昔值蒙古世，曾有化人师。","说法动帝听，天龙护南归。","乃从万石腹，手辟招提基。","一狮作佛吼，万象咸佛皈。","竞传古佛身，应化来南维。","弹指五百年，时代纷传疑。","问佛佛不言，问僧僧岂知。","上有延祐钟，下有至治碑。"]},{"t":"南岩均庆寺诗四首 其三","f":"五言古诗","c":["入冬万化闭，群山惨澹色。","我来逢睡狮，对佛坐叹息。","虎狼方满野，杀气黯西北。","岂无干净土，恐化虎狼国。","何时一吼威，竟使群凶踣。","春雷万蛰动，阳和转东极。","会须起睡狮，诸天奋神力。"]},{"t":"南岩均庆寺诗四首 其四","f":"五言古诗","c":["吾祖昔入粤，五世乃始昌。","当时佛抱送，坠地腾佛光。","以寺名厥名，至今留馀庆。","我从海上来，五载离闽疆。","此行访佛迹，再见闽山苍。","闽山连粤山，遥控东南洋。","长蛟率悍类，毒雾遮日光。","安得佛金钟，覆使毋披猖。","欲读金字经，贝叶无遗藏。","谁传神山笔，父老思先皇。","入寺考故名，剔藓残碑旁。","手携石墨归，满路昙花香。"]},{"t":"寄怀公度二首 其一","f":"七言律诗","c":["梅花消息最分明，已报山中岁欲更。","野草初苏呼鹿友，江波微长受鸥盟。","高门盘菜神京梦，伏枕炉香画省情。","一卷公羊宜起疾，先春重与订王正。"]},{"t":"寄怀公度二首 其二","f":"七言律诗","c":["北风吹雪昼纷纷，盼得微晴日未曛。","扫血故巢归蜀帝，招魂香草待湘君。","惊回夜豹寒中吠，唤起春牛梦里文。","无限登高赋诗意，况因八表怅停云。"]},{"t":"立春前一日侍家大人游薯村题宗人山楼二首 其一","f":"七言绝句","c":["不晴不雨酿春寒，万里归承膝下欢。","亲侍罗浮万年杖，湖山无恙故乡看。"]},{"t":"立春前一日侍家大人薯村题宗人山楼二首 其二","f":"七言绝句","c":["近约山村作近游，看山今始快登楼。","停栏忽动飞熊感，西望长安渭水流。"]},{"t":"游姜畬，题山人壁二首 其一","f":"七言绝句","c":["春山草浅畜宜羊，山半开畬合种姜。","比较生涯姜更好，儿童都唱月光光。"]},{"t":"游姜畬，题山人壁二首 其二","f":"七言绝句","c":["东风吹暖好年光，正月蟾蜍已落塘。","更乞天公三日雨，山田高下有新秧。"]},{"t":"雨宿新步，次韵答子华三首 其一","f":"七言绝句","c":["四姑嶂下花始开，九子岭边闻晚雷。","濛濛细雨一帆重，人向春云来处来。"]},{"t":"雨宿新步，次韵答子华三首 其二","f":"七言绝句","c":["不羡封侯入玉门，中原未靖虎狼群。","欲呼力士携锥出，谁是人间仓海君。"]},{"t":"雨宿新步，次韵答子华三首 其三","f":"七言绝句","c":["春江欲济苦无舟，滚滚清流变浊流。","醉看蛟龙挟云去，临池且为学书留。"]},{"t":"重帘","f":"七言绝句","c":["重帘不捲久留香，压院云阴漏晚光。","是雨是晴浑未定，碧桃花下看斜阳。"]},{"t":"虬枝","f":"七言绝句","c":["虬枝十丈老槎枒，迸出烘天万朵霞。","惜我来迟春已暮，东山开过木棉花。"]},{"t":"三月初八夜","f":"七言律诗","c":["十二年前此夜中，白袍人正试南宫。","惊心胡马蹂春甸，矫首孤罴忆故丛。","何日扫尘迎警跸，当时入彀枉英雄。","万言策在嗟无用，冷对山堂烛泪红。"]},{"t":"褚渊","f":"七言绝句","c":["西风吹泪石头城，老作中书转损名。","自是毫无丈夫气，山阴此语定平生。"]},{"t":"梦觉","f":"七言绝句","c":["梦觉游仙天欲明，东窗一角白初生。","梅花纸帐春慵起，卧听山禽奏乐声。"]},{"t":"东山谒韩祠毕，得子华长句，次韵寄答","f":"七言古诗","c":["新市楼头和诗毕，舟师告行仗风力。","谁知大句捷于风，六百里程远追及。","于时我正从韩公，捕逐八荒两翅疾。","乾坤雷琅摆光燄，青莲乐府少陵律。","时虞仙官敕六丁，白日青天起霹雳。","岛瘦郊寒湜籍走，落落人才困驰骤。","终须载笔缚元济，岂惟奋舌诛庭凑。","偶语龙湫窥舑舚，群鬼闻之惊破胆。","不知此特不平鸣，愚儿但妒词何赡。","古人馀韵吁莫追，嗟我与君犹斗险。","书生今日良可哀，有策难上黄金台。","燕赵曾闻古多士，悲歌慷慨安在哉！","空谈横磨十万剑，言者自愤旁人咍。","汉家不出卫霍才，西极天马何时来！"]},{"t":"东山寄怀南海裴伯谦县令二首 其一","f":"七言律诗","c":["水帘亭畔倚阑干，倦客重来拾坠欢。","南海月明千里共，东山云卧一春寒。","神仙从古多为令，名士何曾竟负官！","应有新诗写新政，可能遥寄练江看。"]},{"t":"东山寄怀南海裴伯谦县令二首 其二","f":"七言律诗","c":["横流无地可安居，身愧王尼尚有车。","残月啼鹃家国泪，断云归雁友朋书。","论交四海心犹热，独立三边愿已虚。","为语修龄益愁索，故人仁祖近何如？"]},{"t":"眉仙为作独立图，三年尚未成，作此速之","f":"七言古诗","c":["三年变态无不有，世界非新亦非旧。","前颠后仆人几何，新不能维旧难守。","此时独立苍茫人，诗且罢吟合呼酒。","可怜磊块浇难消，谁能写向丹青手？","荷君诺我颊添毫，如何阁笔三年久？","幸不障面羞彦回，更不函头哀㑌冑。","还我堂堂地做人，所贵完身成不朽。","平生儒冠久自厌，长剑横腰衣短后。","不妨图我作老兵，天下于今武方右。","乞君速践息壤言，勿使神龙空见首。"]},{"t":"晨起书所见","f":"五言古诗","c":["晨阴盼庭树，有雀拳高枝。","老鸦尔何来？","欲攫充朝饥。","雀惊飞且噪，乞救声何悲！","一雀噪未已，百雀噪而随。","雀亦有侠肠，不忍同类危。","群雀禦独鸦，力小心则齐。","竟令远引避，不敢复来窥。","惟独力无大，惟群力无小。","嗟哉不能群，人而不如鸟。"]},{"t":"杂诗四首答郑生 其一","f":"五言古诗","c":["洪水昔降灾，天下困沉溺。","上巢下营窟，非不工避匿。","大鸟呼大兽，出与人相迫。","死者鱼鳖游，生者鸟兽食。","天生群圣人，畀各尽天职。","水平鸟兽去，用教民稼穑。","茫茫大地中，乃始有中国。","此岂托空言，要在奋神力。","蚩蚩者彼民，实具愚下质。","嬉游幸无事，事至徒叹息。","由来天下事，任者在豪杰。"]},{"t":"杂诗四首答郑生 其二","f":"五言古诗","c":["饕鸱甘腐鼠，仰视嚇鹓雏。","鹓馈有竹实，彼鸱安得知？","天生物惟万，物物性不齐。","持海语井蛙，持天语醯鸡。","徒烦告者劳，终受听者嗤。","圣人物万物，不与物性违。","使鸟宅深林，使鱼室深池。","是之谓物化，毋失化者机。","惟物有蠢灵，惟人有智愚。","治君子以德，治小人以威。","物物性不齐，何用多言为？"]},{"t":"杂诗四首答郑生 其三","f":"五言古诗","c":["百禽中有鹤，自是禽中仙。","胡为俯求食？","而受鸡鹜嗔。","凤凰帝百禽，尔鹤尔臣邻。","高飞就凤凰，孰能为鹤先！","凤凰方渴睡，训狐摄厥权。","燕蝠且笑之，尔鹤何容前？","钦䲹乘凤敝，自耀文采鲜。","岂无众恶禽，推奉相圣贤。","慎哉勿妄投，庶得身名全。","凤睡有醒时，何事皇皇然？","荡荡者九皋，高高者九天。","何行不翯翯？","何飞不翩翩？","神仙自轻举，宁受凡夫怜。"]},{"t":"杂诗四首答郑生 其四","f":"五言古诗","c":["鶢鶋集鲁门，不乐钟鼓养。","鹦鹉虽人言，常有陇山想。","桑扈啄场粟，得食自俯仰。","岂愿为燕雀，处君高堂上。","笼禽厚予食，虽饱神不王。","谢安卧东山，不慕为晋相。","马援困浪泊，乃悔为汉将。","将相岂不佳？","达者非所望。","中原昔龙战，三顾起葛亮。","尽瘁五丈原，躬耕失高尚。","圣人志行道，固不计得丧。","蜚鸿已贻辱，衰凤复腾谤。","归对山梁雉，时哉发叹怅。"]},{"t":"寄怀瑞凤纶分转 其一","f":"七言律诗","c":["棨戟重临凤水湄，三年谁与共忧时。","魏糔帝问传家笏，苏轼天留过岭诗。","富国祗今先煮海，才人从古例分司。","湖山到处题名在，耿耿心应有石知。"]},{"t":"寄怀瑞凤纶分转 其二","f":"七言律诗","c":["新辟王通讲学庐，许分徐福逸篇书。","舳舻转海无消息，孛彗经天有扫除。","万里共传封事上，百年休悔树人疏。","自惭冷坐河汾席，将相终思为国储。"]},{"t":"题太白醉酒图 其一","f":"七言绝句","c":["天宝年间万事非，禄山在外内杨妃。","先生沈醉宁无意，愁看胡尘入帝畿。"]},{"t":"题太白醉酒图 其二","f":"七言绝句","c":["早年妙句擅沉香，晚作流人下夜郎。","谁识先生非酒客，当时慷慨为勤王。"]},{"t":"东山感春诗，次己亥感秋韵 其一","f":"七言绝句","c":["沧海尘生锦瑟年，明珠泪尽月当天。","人间传遍西昆体，谁解春心托杜鹃？"]},{"t":"东山感春诗，次己亥感秋韵 其二","f":"七言绝句","c":["歌残汾水雁秋飞，北望胡尘泪满衣。","愁对春风吟水调，六龙西幸不曾归。"]},{"t":"东山感春诗，次己亥感秋韵 其三","f":"七言绝句","c":["桃花春水涨前滩，待渡无舟欲济难。","落日孤云心万里，望仙桥畔望长安。"]},{"t":"东山感春诗，次己亥感秋韵 其四","f":"七言绝句","c":["衣冠南渡避胡来，凭仗双轮碾海开。","应有田横客相笑，春帆叶叶过登莱。"]},{"t":"东山感春诗，次己亥感秋韵 其五","f":"七言绝句","c":["变现诸天说法身，穗香醒梦證前因。","遍呼黄帝诸孙起，莫作华胥国里人。"]},{"t":"东山感春诗，次己亥感秋韵 其六","f":"七言绝句","c":["神丹浪说解还童，哀感中年遇谢公。","难遣故宫禾黍恨，春灯和泪写王风。"]},{"t":"题潘兰史江湖载酒图","f":"七言律诗","c":["老兰编集似朱十，旷代相感惟牧之。","何曾护惜有街卒？","但遣风流传画师。","四海亦推敢论事？","千秋岂信空称诗！","才人薄倖不自讳，何不并写江南枝？"]},{"t":"题丘园雅集图","f":"七言律诗","c":["东园西园醉未已，大雅小雅材几何！","元白即看压俱倒，丹青相与存不磨。","桃花流水客停棹，棋局空山樵烂柯。","此乐图之岂易得！","敢辞留恋佛所呵？"]},{"t":"题红拂图","f":"七言绝句","c":["平生愿作虬髯客，人道才如李药师。","独对丹青洒雄泪，不曾真受美人知。"]},{"t":"题倪县令松鹤图 其一","f":"七言绝句","c":["官思何如归思浓，采芝翁健免扶筇。","轻装只载华亭鹤，未看北山堂外松。"]},{"t":"题倪县令松鹤图 其二","f":"七言绝句","c":["曾从海鳄远趋庭，未忘鸳湖旧钓舲。","松有稚孙鹤有子，山风吹与老人听。"]},{"t":"送张别驾之官黔中","f":"七言绝句","c":["一官万里黔中去，并马看山有侍儿。","重认摩围小时月，满帘花影唱新词。"]},{"t":"次韵寄谭彤士桂林 其一","f":"七言绝句","c":["走马看花忆凤城，如烟如梦不分明。","回头十二年前事，残照西山战气横。"]},{"t":"次韵寄谭彤士桂林 其二","f":"七言绝句","c":["八桂林边多好山，一麾遥羡数跻攀。","何时携屐访君去，老我犹能腰脚顽。"]},{"t":"次韵寄谭彤士桂林 其三","f":"七言绝句","c":["怕向宣南说旧游，烽烟满目客登楼。","欧阳门下吾尤愧，但有文章放出头。"]},{"t":"次韵寄谭彤士桂林 其四","f":"七言绝句","c":["故事骖鸾推石湖，清诗美政今何如？","东江西江日夜长，双鲤休忘常寄书。"]},{"t":"汕头海关歌寄伯瑶","f":"七言古诗","c":["风雷驱鳄出海地，通商口开远人至。","黄沙幻作锦绣场，白日腾上金银气。","峨峨新旧两海关，旧关尚属旗官治。","先生在关非关吏，我欲从之问关事。","新关主者伊何人？","短衣戴笠胡羊鼻。","新关税赢旧关绌，关吏持筹岁能记。","新关税入馀百万，中朝取之偿国债。","日日洋轮出入口，红头旧船十九废。","土货税重洋货轻，此法已难相抵制。","况持岁价两相较，出口货惟十之二。","入口岁赢二千万，曷怪民财日穷匮。","惟潮出口糖大宗，颇闻近亦鲜溢利。","西人嗜糖嗜其白，贱卖赤砂改机制。","年来仿制土货多，各口华商商务坠。","如何我不制洋货，老生抵死雠机器。","或言官实掣商肘，机厂欲开预防累。","此语或真吾不信，祗怪华商少雄志。","坐令洋货日报关，万巧千奇无不备。","以其货来以人往，大舱迫窄不能位。","岁十万人出此关，偻指来归十无四。","十万人中人彘半，载往作工仰喂饲。","可怜生死落人手，不信造物人为贵。","中朝屡诏言保商，惜无人陈保工议。","我工我商皆可怜，强弱岂非随国势？","不然十丈黄龙旗，何尝我国无公使？","彼来待以至优礼，我往竟成反比例。","且看西人领事权，雷厉风行来照会。","大官小吏咸朒缩，左华右洋日张示。","华商半悬他国旗，报关但用横行字。","其中大驵尤狡狯，播弄高权遽横恣。","商誇洋籍民洋教，时事年来多怪异。","先生在关虽见惯，思之应下哀时泪。","闽粤中间此片土，商务蒸蒸岁逾岁。","瓜分之图日见报，定有旁人思攘臂。","关前关后十万家，利窟沉酣如梦寐。","先王古训言先醒，可能呼起通国睡。","出门莽莽多风尘，无奈天公亦沉醉。"]},{"t":"四月十六夜东山与台客话月","f":"七言律诗","c":["万事应教付酒杯，眼看云合又云开。","中天月色雨馀好，大海潮声风送来。","人物祗今思故国，江山从古属雄才。","飘零剩有乡心在，夜半骑鲸梦渡台。"]},{"t":"天地","f":"五言古诗","c":["天地道方否，人才散于野。","遭时乃云合，岂有平生雅？","英雄造世宙，其才自天假。","书或仅上口，名或不能写。","古来真英雄，屈指几儒者？","文人习目论，动叹人才寡。","我自不英雄，奈何责天下！"]},{"t":"舟过韩江有寄","f":"七言绝句","c":["此水东来我西上，扁舟北过江上城。","南风正利不得泊，良夜相思空月明。"]},{"t":"题画","f":"七言绝句","c":["奇峰面面入层云，长板桥西坐夕曛。","秋水一篙山九曲，放船同访武夷君。"]},{"t":"客怀","f":"五言绝句","c":["古树半秋色，西风吹客怀。","呼童扫不尽，落叶满閒阶。"]},{"t":"舟发新步","f":"七言绝句","c":["金鞍寨下溪水流，石鼓潭边雨乍收。","一叶扁舟载斜日，泽兰花发古堤秋。"]},{"t":"为潮人士衍说孔教于鮀浦，伯瑶见访有诗，次韵答之","f":"七言绝句","c":["大海潮来独倚栏，七千里外冷朝官。","重提孔子尊王义，如日中天万象看。"]},{"t":"王晓沧将之官闽中赋别 其一","f":"七言绝句","c":["六龙尚未西巡日，海外曾开万寿宫。","圣主回銮臣听鼓，一官千里入闽中。"]},{"t":"王晓沧将之官闽中赋别 其二","f":"七言绝句","c":["颇闻新政议裁官，何事卑栖令尉间？","毕竟才人裁不得，要将诗界拓闽山。"]},{"t":"王晓沧将之官闽中赋别 其三","f":"七言绝句","c":["有人图写闽山去，著色争誇势力圈。","泪洒君家故王墓，萧萧松柏锁寒烟。"]},{"t":"王晓沧将之官闽中赋别 其四","f":"七言绝句","c":["马江虽败船政在，战后依然用法人。","二十年来海权尽，浪抛财力铸官轮。"]},{"t":"王晓沧将之官闽中赋别 其五","f":"七言绝句","c":["鼓山东望龙渡处，海雨曾飘开国旗。","从古英雄论成败，不堪重话共和时。"]},{"t":"王晓沧将之官闽中赋别 其六","f":"七言绝句","c":["海山莽莽送君行，海水茫茫无限情。","未敢宝刀轻脱赠，恐教添作不平鸣。"]},{"t":"重送王晓沧次前韵 其一","f":"七言绝句","c":["江山霸气消沉尽，何处闽王有故宫？","独客寻师海天去，无诸城郭夕阳中。"]},{"t":"重送王晓沧次前韵 其二","f":"七言绝句","c":["才人从古不宜官，置汝髯参短簿间。","北望中原数豪杰，左旗右鼓眼中山。"]},{"t":"重送王晓沧次前韵 其三","f":"七言绝句","c":["一官便具奴才性，谁是英雄出此圈。","且合看山持手版，钓龙台上啸寒烟。"]},{"t":"重送王晓沧次前韵 其四","f":"七言绝句","c":["竞争世界论天演，此去闽中太有人。","唤起群龙听梵唱，诸天同转法王轮。"]},{"t":"重送王晓沧次前韵 其五","f":"七言绝句","c":["开遍岭梅日长至，霏霏寒雨飘船旗。","诗中长记送君日，此是人天剥复时。"]},{"t":"重送王晓沧次前韵 其六","f":"七言绝句","c":["落日浮云送客行，旧游回首不胜情。","海山俦侣如相问，大鸟三年尚不鸣。"]},{"t":"岁暮感怀次感春韵 其一","f":"七言绝句","c":["浪说芦灰止水年，笙簧重奏古来天。","阳枢不转春消息，老木寒巢噤帝鹃。"]},{"t":"岁暮感怀次感春韵 其二","f":"七言绝句","c":["玉龙残甲满天飞，万里寒光照铁衣。","黄竹歌中行八骏，瑶池空送穆王归。"]},{"t":"岁暮感怀次感春韵 其三","f":"七言绝句","c":["扁舟钓雪下寒滩，落日荒荒欲霁难。","满目江山沉战气，可能王业不偏安。"]},{"t":"岁暮感怀次感春韵 其四","f":"七言绝句","c":["曾从剑侠传中来，十万戈船梦里开。","把酒寒斋逢故部，海东残岛话奇莱。"]},{"t":"岁暮感怀次感春韵 其五","f":"七言绝句","c":["万梅花里问前身，我佛从来戒造因。","冷看天倾无力补，莫将黄土浪抟人。"]},{"t":"岁暮感怀次感春韵 其六","f":"七言绝句","c":["禾黍何须怨狡童，是非从古论难公。","可怜神化丹青手，剩粉零缣写北风。"]},{"t":"次韵答伯瑶","f":"七言律诗","c":["门外大海生春涛，海山矗立如墙高。","款门何人曳春袍！","兰陵夫子今诗豪。","海山自苍海水绿，对客挥毫洒珠玉。","杜陵乐府老更成，休作开元天宝声！"]},{"t":"苦旱 其一","f":"七言绝句","c":["手无寸铁诛妖魃，安得神龙出九渊？","但解乘球用今法，不妨持药炸青天。"]},{"t":"苦旱 其二","f":"七言绝句","c":["眼中赤地真千里，万首翘天望雨来。","谁叩九阊讼风伯，新云才起又吹开。"]},{"t":"喜谢颂臣由台至","f":"五言律诗","c":["鸡黍三年约，莺花二月时。","春随故人至，书慰老亲思。","海上惊相见，山中喜可知。","春篘酒方熟，莫遽数归期。"]},{"t":"次韵答宾南金陵","f":"七言律诗","c":["杨柳依依白下门，梅花历历岭头村。","南来驿信春同到，北去班声夜尚喧。","清酒黄龙半要约，素车白马几忠魂！","与君别后论身世，除却悲歌百不存。"]},{"t":"次韵再答宾南，兼寄陈伯严 其一","f":"七言律诗","c":["如此江山客闭门，有人相忆向蛮村。","神龙睡任群鱼泣，病骥喑看万马喧。","抚剑已怜消侠骨，选蓍重与揲归魂。","萧条炎运人才尽，差喜陈蕃榻尚存。"]},{"t":"次韵再答宾南，兼寄陈伯严 其二","f":"七言律诗","c":["故乡投足向何门，丁水南来绕古村。","华表鹤归山月暗，神州鳌没海涛喧。","竞争世界怜天演，寥落中原怆国魂。","手把英雄传閒读，眼中多少可儿存！"]},{"t":"次韵再答宾南，兼寄陈伯严 其三","f":"七言律诗","c":["遥怜驻马望千门，人在江南黄叶村。","鼠璞殊方名未定，蚊雷竟夕语何喧！","心关国粹谋兴学，目笑时流说重魂。","庚子陈经拜宣圣，尊王遗义故应存。"]},{"t":"次韵再答宾南，兼寄陈伯严 其四","f":"七言律诗","c":["南戒河山走越门，布衣牢落此荒村。","望中残照金轮转，意外虚声瓦缶喧。","敢信群龙终见首，竟烦大鸟屡招魂。","重阴天气怀人日，展卷吾庐春自存。"]},{"t":"与颂丞话台事","f":"七言律诗","c":["万三千尺出海面，岛国诸山无此高。","谁遣黄图易他色，空传赤制属吾曹。","梦中雄鬼哀相吊，劫后顽仙笑独逃。","收拾磨崖纪功笔，东南风急送春涛。"]},{"t":"书感与颂丞","f":"七言绝句","c":["各自行营高敞地，大宛山与大屏邻。","生儿莫作真王想，不及淮阴守冢人。"]},{"t":"论诗次铁庐韵 其一","f":"七言绝句","c":["元音从古本天生，何事时流务竞争？","诗世界中几雄国？","惜无人起与连衡。"]},{"t":"论诗次铁庐韵 其二","f":"七言绝句","c":["迩来诗界唱革命，谁果独尊吾未逢。","流尽玄黄笔头血，茫茫词海战群龙。"]},{"t":"论诗次铁庐韵 其三","f":"七言绝句","c":["新筑诗中大舞台，侏儒几辈剧堪哀。","即今开幕推神手，要选人天绝代才。"]},{"t":"论诗次铁庐韵 其四","f":"楚辞体","c":["台上风云发浩歌，不须猛士再蒐罗。","拔山妄费重瞳力，夜半虞兮唱奈何。"]},{"t":"论诗次铁庐韵 其五","f":"七言绝句","c":["北派南宗各自誇，可能流响脱淫哇。","诗中果有真王在，四海何妨共一家。"]},{"t":"论诗次铁庐韵 其六","f":"七言绝句","c":["彼此纷纷说界疆，谁知世有大文章。","中天北斗都无定，浮海观星上大郎。"]},{"t":"论诗次铁庐韵 其七","f":"七言绝句","c":["芭蕉雪里供摹写，绝妙能诗王右丞。","米雨欧风作吟料，岂同隆古事无徵。"]},{"t":"论诗次铁庐韵 其八","f":"七言绝句","c":["四海横流未定居，千村万落废犁锄。","荆州失后吟梁父，空忆南阳旧草庐。"]},{"t":"论诗次铁庐韵 其九","f":"七言绝句","c":["展卷重吟民主篇，海山东望独悽然。","英雄成败凭人论，赢得诗中自纪年。"]},{"t":"论诗次铁庐韵 其十","f":"七言绝句","c":["四海都知有蛰庵，重开诗史作雄谈。","大禽大兽今何世？","目极全球战正酣。"]},{"t":"送谢四东归","f":"古风","c":["故人访我东海来，春风万里心颜开。","故人别我东海去，临歧各短英雄气。","七年不见今再见，沧海桑田事万变。","中间不变故人心，袖手海天看龙战。","君来一月无停车，访我更访山中庐。","老亲喜君送君出，来此十日相同居。","七年乃有此十日，但觉日行比常疾。","此日不为君我留，南风日日催行舟。","舟行既速况有轮，轮转四海扬胡尘。","送君此去作胡语，乐府休唱胡无人。","我年方强君未老，惜君投身隐海岛。","亚洲大陆局日新，时势径待英雄造。","海山之高一万三千尺，当年弃去良可惜。","横来不王复不侯，为我归言岛中客。","包胥存楚约可寻，廉颇用赵原初心。","相期亚陆风云再相见，骑鲸东海来挽神州沉。"]},{"t":"纪兴宁妇女改妆事与刘生松龄二首 其一","f":"七言绝句","c":["山川奇伟数齐昌，不独男儿解自强。","要使金闺兴女学，银钗先改峒蛮妆。"]},{"t":"纪兴宁妇女改妆事与刘生松龄二首 其二","f":"七言绝句","c":["维新殊有九州风，新绾盘蛇髻更工。","预祝英雄出巾帼，武婆城在碧云中。"]},{"t":"次韵答维卿师 其一","f":"七言绝句","c":["流落天南今八载，接天海气昼昏昏。","锦袍银烛追前梦，夜半涛声倍断魂。"]},{"t":"次韵答维卿师 其二","f":"七言绝句","c":["空存扶汉分章手，无计能开日月昏。","独立苍茫发遐想，自由钟起国民魂。"]},{"t":"题画四绝句 其一","f":"古风","c":["漫天飞雪净红尘，吩咐门前扫雪人：要向梅花问消息，空山已放几分春？"]},{"t":"题画四绝句 其二","f":"七言绝句","c":["多时放牧出天閒，边事无功马自閒。","杨柳千条溪一曲，可怜神骏老空山。"]},{"t":"题画四绝句 其三","f":"七言绝句","c":["遮天浓碧老梧桐，曾种前皇旧上宫。","凤鸟不来人事改，箫声閒度月明中。"]},{"t":"题画四绝句 其四","f":"七言绝句","c":["閒敲棋子向山中，不信神仙万念空。","一局松阴未收著，人间成败几英雄。"]},{"t":"题画芙蓉","f":"七言绝句","c":["曾记花间倚醉眠，露寒风定月娟娟。","画中重见芙蓉面，酒冷香消忆少年。"]},{"t":"寄台湾栎社诸子，兼怀颂丞二首 其一","f":"七言绝句","c":["柏庄谁拾燹馀文，栎社重张劫后军。","九十九峰依旧好，尽携豪笔写秋云。"]},{"t":"寄台湾栎社诸子，兼怀颂丞二首 其二","f":"七言绝句","c":["月泉志卷凭谁定，还待当时晞发人。","遥忆参军谢皋羽，西台朱鸟独伤神。"]},{"t":"题兰史罗浮纪游图","f":"古风","c":["我阅世界大地图，罗浮一点乃在南岭之南隅。","神禹伯益导焚所未到，发见乃始汉家使者中大夫。","二千馀年在世界，为山主者仙之儒。","洞天福地收不尽，许容黄面瞿昙徒。","霸者之宫贼巢穴，仙山时亦遭点污。","游人迁客更多事，往往镌刻伤山肤。","沉迷诗酒发幻想，或突神女搪仙姑。","梅花无言翠羽笑，梦中彼美颜何姝？","天公应悔蓬莱割左股，隳落欲界非仙都。","迩来仙人所治地益窄，堑山跨海来群胡。","各思圈地逞势力，此邦多宝尤觊觎。","此时傥有豪杰出，岂能揖让无征诛！","此时若作厌世想，纵成仙去胡为乎？","潘生昔游半球万里路，海山看尽呼归桴。","中间锡兰岛上逢佛睡，一任释种为人奴。","佛犹如此仙可想，但有沉醉醪何酥。","仙人醉生佛梦死，世间学者宁非愚。","留名山石石且枯，岂有丹青能不逾？","人生若作千秋万岁想，固应自立昂藏躯。","黄河、扬子、珠江判流域，文明之运方南趋。","天道由来后起胜，以中證外原非诬。","但须世界有豪杰，太极虽倒人能扶。","南界之山走百粤，如罗浮者雄非粗。","奇峰四百瀑九百，慎勿但作诗人娱。","上有神桂下有湖，洞中仙蝶不可呼。","题君此图正风雨，想见罗浮离合云模糊。"]},{"t":"梦题岳阳楼壁","f":"七言律诗","c":["梦拥灵旗宝纛行，鸾骖小驻岳阳城。","濛濛云气开南极，浩浩江流作楚声。","衡岳雁归秋万里，洞庭龙卧月三更。","他年记取题诗处，南纪群真抗手迎。"]},{"t":"次韵答友人 其一","f":"七言绝句","c":["天遣诸夷不乱华，自应骠骑不为家。","独怜已似骑驴将，閒看西湖十里花。"]},{"t":"次韵答友人 其二","f":"七言绝句","c":["傥容儒术济时艰，老抱遗经岂听閒。","河镇未归金世界，大师犹解荐龟山。"]},{"t":"次韵答友人 其三","f":"七言绝句","c":["庾信江南早赋哀，平生萧瑟漫论才。","百王道尽焚书日，谁遣窥江虏马来。"]},{"t":"次韵答友人 其四","f":"七言绝句","c":["遣日将诗也自宜，故乡犹幸有新知。","吟成自漉炉头酒，权当黄龙痛饮时。"]},{"t":"饮镇平都司署赏菊，为题宋人所画报捷图","f":"七言律诗","c":["已过重阳菊尚开，霜天赏菊此衔杯。","人饶韬略来香国，花亦英雄上将台。","粤水闽山文武会，酒龙诗虎主宾才。","西风吹解黄金甲，醉看红旗报捷来。"]},{"t":"次韵和友人除夕自寿","f":"七言律诗","c":["笑数雌雄几甲辰，梅花预报来年春。","祭诗岛佛才如故，守岁坡仙语更新。","自把屠苏开寿宴，兼持吟稿馈交亲。","东风更送明朝喜，戴胜何妨属老人。"]},{"t":"过三河，吊翁襄敏墓","f":"七言律诗","c":["落日青山虎气沉，河流还啮故城阴。","地埋一代名臣骨，天鉴三边守将心。","人物岭东前史在，关山直北战尘深。","英灵异代应相感，一片寒云绕墓林。"]},{"t":"题画 其一","f":"七言绝句","c":["玉带犹留此结缘，金山楼殿耸云烟。","何当自碾龙团饼，来试江心第一泉。"]},{"t":"题画 其二","f":"七言绝句","c":["何处瓜牛旧结庐，六时宫殿震钟鱼。","大江东去月西上，自闭山门读道书。"]},{"t":"题画 其三","f":"七言绝句","c":["金山看罢看银山，宫殿崔巍紫翠间。","领略江南好风景，散花人去老僧閒。"]},{"t":"题画 其四","f":"七言绝句","c":["虎踞龙蹯迹未消，尚留古刹话前朝。","老僧不省英雄恨，夜夜寒江咽暮潮。"]},{"t":"题菊花诗卷 其一","f":"七言绝句","c":["北痛逆胡南篡贼，渊明心事菊花知。","看花不尽千秋感，残照西风又一时。"]},{"t":"题菊花诗卷 其二","f":"七言绝句","c":["谁吟金甲战秋风，黄败朱成事不同。","傥有閒情来吊古，合编花史记英雄。"]},{"t":"题菊花诗卷 其三","f":"七言绝句","c":["宁向枝头死抱香，不曾吹坠北风凉。","如何海上新花样，化作东夷大宝章。"]},{"t":"题菊花诗卷 其四","f":"七言绝句","c":["也知晚节留香好，独惜军中少一韩。","任是黄花比人瘦，西风还拟卷帘看。"]},{"t":"题菊花诗卷 其五","f":"七言绝句","c":["百尺澄台对落晖，旧吟花处地都非。","重寻十七年前梦，飘尽黄金泪满衣。"]},{"t":"赠谢生","f":"古风","c":["人言谢生颠，吾未敢从众。","与言世界事，谈言动微中。","即令能颠亦复奇，终胜老生了无用。","神州大陆殊可哀，纷纷老朽无人才。","眼中突兀少年在，令我郁郁心颜开。","即今时事须放手，安得人尽颠如雷。","谢生言论自由耳，已令世人骇欲死。","丈夫何止用口舌，治世界事从今始。","时哉时哉不可失，东南风吹大海水。"]},{"t":"题兰史香海填词图 其一","f":"七言绝句","c":["南宋国衰词自盛，各抛心力斗清新。","零丁洋畔行吟地，又见江山坐付人。"]},{"t":"题兰史香海填词图 其二","f":"七言绝句","c":["此是本朝初割地，年来见惯已相忘。","重吟整顿乾坤句，谁更雄心似鄂王？"]},{"t":"题黄生印谱 其一","f":"七言绝句","c":["铭雀砚斋新印谱，七年前见景韩楼。","萧萧风雨鮀江上，夜半题诗四壁秋。"]},{"t":"题黄生印谱 其二","f":"七言绝句","c":["五洲莽莽起风云，待扫亡秦旧篆文。","留与他年添印谱，九头狮纽大将军。"]},{"t":"题刘铭伯制科策后二首 其一","f":"七言律诗","c":["米雨欧风捲地来，有人策马上金台。","空弹贾谊忧时泪，共惜刘蕡下第才。","书剑南归沧海阔，河山北望战云颓。","太平策在终须用，且抱乡心付岭梅。"]},{"t":"题刘铭伯制科策后二首 其二","f":"七言律诗","c":["早闻声价重龙门，一疏轰传叩九阍。","吾辈当为天下计，此才岂藉特科尊！","愁边在陆龙蛇起，梦里当关虎豹蹲。","诵罢高文鸡喔喔，何时对舞共刘琨！"]},{"t":"君山","f":"七言绝句","c":["君山自是众山君，卓立中峰上插云。","曾上君山最高顶，东南一气荡氤氲。"]},{"t":"百字令 次廖伯鲁韵","f":"古风","c":["峤南人物，问当今谁是曲江风度？","万劫不磨雄直气，空剩屈陈词赋。","秦戍哀云、越台吊月，愁听秋虫诉。","南宗未坠，菩提何碍无树？","历历弹指光阴，论橙品荔，乡味将人误。","潦倒英雄成末路，饱领凉情热趣。","倒海浇天、剖云行日，梦里留奇句。","功名尘土，浩歌还谱朱鹭。"]},{"t":"满江红 越王台，次伯鲁韵","f":"古风","c":["逐鹿中原，问何故闭关自域？","思旧事，登高吊古，五羊城北。","椎结雄称南武帝，抱孙左纛朝仪赫。","笑此台高瞰百蛮天，何因设？","甘心受，新王职；","弹指顷，千年隔。","访霸图一片，夕阳无极。","残缺不完南越国，老夫心事何人识？","祗江山雄绕古台基，今犹昔。"]},{"t":"题马生美人宝剑图","f":"七言古诗","c":["万方仪态天风生，素女始教轩皇兵。","长兵戈矛短兵剑，剑花夜发芙蓉燄。","越王铸剑光满池，天遣素女为之师。","亡吴霸越赖有此，世人但道有西子。","南风烈烈扬胡尘，雌雄剑化延平津。","可怜歌舞太平日，卧薪尝胆今无人。","我来吊古越台下，眼中突兀扶风马。","苦将古事作今图，宝剑非真美人假。","下穷九地上九天，转劫将逢龙汉年。","且寻南岳夫人去，唤起千秋女剑仙。"]},{"t":"与高啸桐同客广州","f":"七言绝句","c":["平生我愧杜工部，喜见高三十五才。","四海风尘双鬓白，斜阳同上越王台。"]},{"t":"赠秦人毛生","f":"七言绝句","c":["直从南北两戒首，走遍胡门到越门。","一发青山残照里，尉陀台上望中原。"]},{"t":"对月，同王户部","f":"五言律诗","c":["一片长安月，随人万里寒。","独怜沧海客，同向越台看。","肝胆光能照，河山影未残。","浮云自西北，惆怅倚阑干。"]},{"t":"龙门之桐行，赠刘铭伯","f":"七言古诗","c":["龙门之桐斲为琴，冰丝玉徽音古音。","琴师携奏九天上，繁弦急管声为瘖。","百神觞帝宜有此，不信天乐翻崇今。","五尺之囊裁古锦，韬以南下江湖深。","明堂清庙非不用，且用邦国坊民淫。","鸱鸮在泮鹙在林，凤皇不来愁人心。","谁扶孤阳抑群阴，嗟哉琴德何愔愔！"]},{"t":"送朱古薇学使乞病旋里二首 其一","f":"七言律诗","c":["三年持节远朝班，要乞君恩更赐閒。","人既读书同博塞，天将盛业付名山。","右军誓墓心谁白？","永叔归田鬓未斑。","惆怅閒鸥沧海上，也随桃李惜春还。"]},{"t":"送朱古薇学使乞病旋里二首 其二","f":"七言律诗","c":["参苓药笼富收藏，只有当归切病方。","卿贰中朝虚位望，科名末造贱文章。","千金行橐馀仙茧，五月徵轺照佛桑。","至竟汉廷思汲黯，未容移疾老江乡。"]},{"t":"醉歌示徐生","f":"七言律诗","c":["天下汹汹党人死，神师一呼群盗起。","此时理乱都不闻，心醉君家老孺子。","欲为孺子吾不能，短衣匹马呼秋鹰。","袖中一卷英雄传，落日来登汉帝陵。"]},{"t":"放歌与陈伯贞","f":"七言古诗","c":["南飞乌鹊栖无枝，老骥伏枥悲鸣时。","明明如月不可掇，江头横槊来赋诗。","大江东去流战血，明月依然作古色。","可怜暮年烈士心，夜半高歌唾壶缺。","文王周公安在哉！","古人已去今人来。","三分未定天下局，一将正少当时才。","我爱陈琳工草檄，居然解愈头风疾。","世间力足生杀人，武士之刀文士笔。","且须饮酒休谈兵，英雄儿女同多情。","二乔已向吴宫老，铜雀年年空月明。"]},{"t":"送长乐学生入陆军学校二首 其一","f":"七言绝句","c":["蛮夷大长作尉地，犹有当时武士风。","今日推翻古人局，要看时势造英雄。"]},{"t":"送长乐学生入陆军学校二首 其二","f":"七言绝句","c":["若从中国论古学，文武由来本不分。","终使西人遘黄祸，吁天早出学生军。"]},{"t":"越台书感","f":"七言律诗","c":["漠漠南云倦眼开，十年三度此登台。","地随落日天边尽，人共秋潮海上来。","木石尚留仙佛气，江山不称霸王才。","倚阑欲遣茫茫感，更向何人借酒杯！"]},{"t":"南园","f":"七言绝句","c":["玉带河边万柳丝，跨河楼阁郁参差。","重来祗恐风光异，再为南园住少时。"]},{"t":"寄刘铭伯","f":"七言绝句","c":["昨梦君从海上归，十峰轩畔解征衣。","觉来江浦潮初上，夜半开门月满扉。"]},{"t":"题王寿山先生人心尽如此图","f":"古风","c":["人心不和平，天下乱未已。","谁言治天下，不自人心始。","图中之人盖知此，偶出鸣琴作宰官。","作诗作画皆琴理，诗臻清品画逸品。","琴韵泠泠满山水，山虚水深吏归矣。","我居君山西，君居君山东；","相去百里近，相隔百年中。","百年未满万事变，人心非复君时同。","此时张弦论天下，自非更改难为功。","奈何古乐付俗手，一任繁急乖商宫。","题君此图心忡忡，安得瑶琴一曲鸣熏风？"]},{"t":"赠伯澜","f":"七言绝句","c":["乘兴曾游大海东，樱花开处唱秦风。","归来小试经纶手，一卷周官补考工。"]},{"t":"珠江夜送啸桐之梧州 其一","f":"七言绝句","c":["年年代作嫁衣裳，涂抹今为新妇妆。","莫道女儿羞未学，教儿忙比养儿忙。"]},{"t":"珠江夜送啸桐之梧州 其二","f":"七言绝句","c":["送人作郡鬼揶揄，同是当时旧酒徒。","能唱尊前渭城曲，故应心计未全粗。"]},{"t":"珠江夜送啸桐之梧州 其三","f":"七言绝句","c":["江山风月好亭台，觞咏应须老守才。","一语叮咛君记取，莫因官贵少书来。"]},{"t":"珠江夜送啸桐之梧州 其四","f":"七言绝句","c":["后夜相思益渺然，苍梧遥隔夕阳边。","他年傥忆今宵会，此是当时载鹤船。"]},{"t":"寄张坚白桂林","f":"五言律诗","c":["一别一年久，相思日几回。","桂林多胜境，藩伯况雄才！","未敢论时局，惟应借酒杯。","寄书无别语，千里索诗来。"]},{"t":"长句与晴皋索普洱茶","f":"古风","c":["滇南古佛国，草木有佛气。","就中普洱茶，森冷可爱畏。","迩来入世多尘心，瘦权病可空苦吟。","乞君分惠茶数饼，活火煎之檐卜林。","饮之纵未作诗佛，定应一洗世俗筝琶音。","不然不立文字亦一乐，千秋自抚无弦琴。","海山自高海水深，与君弹指一话去来今。"]},{"t":"陈伯潜学士以路事来粤，相晤感赋二首 其一","f":"七言律诗","c":["三十年来万事非，天涯沦落识公迟。","横流沧海无安处，故国青山有梦思。","铸铁屡闻成错字，造车此是出门时。","他乡同纵登高目，斜日黄龙上大旗。"]},{"t":"陈伯潜学士以路事来粤，相晤感赋二首 其二","f":"七言律诗","c":["台岭岧峣海气昏，贞元朝士几人存！","秋江漠漠鱼龙夜，上界沉沉虎豹尊。","分野直疑连鬼宿，买山何处觅公墩。","乾坤整顿关吾辈，先遣南车走越门。"]},{"t":"沈爱苍于皋署新作小亭","f":"七言律诗","c":["涛园佳话吾能说，还合题名作沈亭。","海上月华连夜白，天涯草色为谁青？","偶收弃地成奇境，尽借群山作画屏。","他日五羊图故事，也应添写少微星。"]},{"t":"次韵南园小山遇雨","f":"七言律诗","c":["横看成岭侧成峰，怪石参差地足容。","正喜园林饶气象，忽惊雷雨起蛟龙。","半池新水花初落，旧壁残题藓未封。","归去更欣逢夕霁，东南回首海云浓。"]},{"t":"梦中","f":"七言律诗","c":["绣旗犹飐落花风，不信楼台是梦中。","十二阑干摇海绿，八千子弟化春红。","奔驰日月无停轨，组织河山未就功。","车下懒龙呼不起，钧天罢奏太匆匆。"]},{"t":"南园对月","f":"七言律诗","c":["南园一片娟娟月，曾照诗人更美人。","穷海未应人物尽，中天还见月华新。","百年耆旧谁高咏？","万劫光明此法轮。","应有珊珊环佩影，夜归来吊柳梢春。"]},{"t":"题沧海遗民台阳诗话","f":"七言律诗","c":["如此江山竟付人，干戈留得苦吟身。","乱云残岛开诗境，落日荒原泣鬼燐。","埋碧可怜黄帝裔，杀青谁作素王臣？","请将风雅传忠义，斑管重回故国春。"]},{"t":"送夏同甫还浙，兼讯汤蛰仙","f":"七言律诗","c":["玉带河边折柳条，送君归看浙江潮。","九秋雕鹗诗心健，万变鱼龙海气骄。","吾辈尚谋文字乐，何人解向国魂招？","归舟倘见山阴客，为道雄心郁未消。"]},{"t":"寄和崔兰西七夕感怀","f":"七言律诗","c":["玉合金针故事遥，离人自写可怜宵。","沉沉旧院收鱼钥，隐隐星河梦鹊桥。","天上双星窥分野，人间万感溢思潮。","柳州屡乞仍难巧，聊报瑶章作解嘲。"]},{"t":"宿西校书堂","f":"七言绝句","c":["迢迢银汉自横天，隐几西堂客未眠。","潮信入城知夜半，橹声摇月过帘前。"]},{"t":"题王寿山先生钓月图","f":"五言律诗","c":["得水月光活，能诗画意深。","直将垂钓意，自證妙明心。","残魄支天地，扁舟阅古今。","秋江妙无际，何处访拿音？"]},{"t":"中秋白云山能仁寺看月有怀覃孝方、周立之二首 其一","f":"七言绝句","c":["袖君诗入白云去，吟向白云山上头。","潭底睡龙惊起听，万峰明月一轮秋。"]},{"t":"中秋白云山能仁寺看月有怀覃孝方、周立之二首 其二","f":"七言绝句","c":["苦口人间度有情，一微尘里万魔生。","于今铲却机锋语，宴坐空山看月明。"]},{"t":"题平远凌生自作壮游图 其一","f":"七言绝句","c":["自从蒸气走车舟，万里都成庭户游。","安得壮行兼绝技，遍将名胜写全球。"]},{"t":"题平远凌生自作壮游图 其二","f":"七言绝句","c":["未能游屐遍人寰，归隐何妨且闭关。","奇绝南台五指石，不妨图写好家山。"]},{"t":"法政学堂宴日本法学博士梅谦次郎，同行结城琢，即席有诗，因次其韵","f":"七言律诗","c":["沉沉大陆宝华饶，南岭秋迎国士轺。","海上钓鳌三岛近，人间相马九方遥。","烟云过眼资探讨，珠玉挥毫破寂寥。","自笑捉刀閒处立，西风长啸越江朝。"]},{"t":"送王铁珊 其一","f":"七言绝句","c":["定交倾盖立谈时，此意难教世俗知。","同抱奈何天地感，五年前已远相思。"]},{"t":"送王铁珊 其二","f":"七言绝句","c":["秋风落日五羊城，一舸西南客送行。","别后苍梧劳远梦，青山万叠暮云横。"]},{"t":"题潘鸿轩百花卷","f":"七言绝句","c":["即教论画亦名家，墨气蒸成五色霞。","展卷如逢仙世界，令人长见四时花。"]},{"t":"次韵答友人","f":"七言律诗","c":["横槊当歌万虑空，复闻吐哺有周公。","挥金径欲求奇士，好色何曾讳国风？","百万逢场仍纵博，十千沽酒更新丰。","平生整顿乾坤手，要见神州日再中。"]},{"t":"重阳日傍晚登粤秀山","f":"七言律诗","c":["萧瑟秋心付五羊，尉佗台上作重阳。","西风吹帽林容老，落日平栏海气凉。","城郭晚来烟雾合，江山前代战争忙。","野僧不解登高意，自杵寒钟礼梵王。"]},{"t":"次韵答周立之","f":"七言律诗","c":["地老天荒不爱才，呱呱哭后已留哀。","千年狗曲亡生气，一夜龙雷起死灰。","乱世诗书儒发冢，中原旗鼓将登台。","茫茫四海无安处，且醉新亭浊酒杯。"]},{"t":"送岑云阶移督滇黔 其一","f":"七言律诗","c":["诏领兼圻即故乡，一时家国并荣光。","古来百粤文身地，再见千秋昼锦堂。","郭令门庭多节钺，晋公勋业有文章。","谁知中外声华满，裘带雍容四十强。"]},{"t":"送岑云阶移督滇黔 其二","f":"七言律诗","c":["南天一柱靖边尘，武纬文经百政新。","辽主能教戒生事，邺侯安得乞閒身？","云中守自须名将，河内人犹借重臣。","乡国三年功百世，讴歌何止晋秦民？"]},{"t":"送岑云阶移督滇黔 其三","f":"七言律诗","c":["西江一水接牂牁，帝念先臣旧部多。","俎豆千秋崇庙貌，河山百战定干戈。","车前父老扶鸠拜，徼外蛮王贡象过。","等是黔宁仍世镇，滇池无恙但微波。"]},{"t":"送岑云阶移督滇黔 其四","f":"七言律诗","c":["曾拜先公丱角时，当年何武解歌诗。","郎君行马偏忘贵，文字雕虫尚见知。","铃阁看移陶侃甓，戟门留读广平碑。","此邦宰相回翔地，愿祝重来啖荔枝。"]},{"t":"秋怀 其一","f":"七言律诗","c":["万里风云愿竟酬，军前歌舞作中秋。","黄金铸阙开藩部，碧玉通江建节楼。","十道分封诸将爵，五湖归老美人舟。","年来此意成萧瑟，匹马西风莽浪游。"]},{"t":"秋怀 其二","f":"七言律诗","c":["昆崙山势走中华，赴海南如落万鸦。","缩地有人工幻术，通天何处觅灵槎！","沈冤鸟口空衔石，酣梦人心久散沙。","弹指光阴秋又老，长绳难系夕阳斜。"]},{"t":"秋怀 其三","f":"七言律诗","c":["中原王气黯东迁，叹凤嗟麟意惘然。","人物真成一丘貉，文章更噪六朝蝉。","绕篱晚菊寒谁采？","补屋秋萝冷自牵。","消尽美人迟暮感，素书一卷独编年。"]},{"t":"秋怀 其四","f":"七言律诗","c":["斜阳围听说场词，我亦曾驱十万师。","破碎河山开国史，飘零风雨出军诗。","海中故部沈苍兕，云里残旌失素蜺。","岁自周天天自醉，红墙银汉隔秋思。"]},{"t":"秋怀 其五","f":"七言律诗","c":["山南山北枉张罗，云路冥冥鸟去多。","四海论交几投契，千秋自命未蹉跎。","中原麟凤陈陶叹，大漠牛羊斛律歌。","老我秋风无一事，十年雄剑不曾磨。"]},{"t":"秋怀 其六","f":"七言律诗","c":["名驹未悔困鞯鞍，鸷鸟何曾惜羽翰！","人到穷愁思著述，天留豪杰济艰难。","衣冠文武浮云变，雷雨蛟龙大海宽。","不信平生飞动意，但将文字救饥寒。"]},{"t":"秋怀 其七","f":"七言律诗","c":["明明如月拨愁开，欲取黄金更筑台。","朱鸟莫将歌当哭，红羊休信劫留灰。","著书覃子原仙骨，顾曲周郎有将才。","收拾雄心且行乐，五云多处觅蓬莱。"]},{"t":"秋怀 其八","f":"七言律诗","c":["酒迫桓温走老兵，诗看秦系破长城。","英雄失路群儿笑，独客逢秋百感生。","沧海桑沈栽后影，钧天乐断梦时声。","尉佗台上西风急，来写登高送远情。"]},{"t":"叠前韵 其一","f":"七言律诗","c":["凤舞鸾歌自酢酬，蟪蛄莫漫话春秋。","人间佳丽黄金屋，天上神仙白玉楼。","弹指华严成幻相，侧身尘海有虚舟。","西风阊阖无消息，且作卢敖汗漫游。"]},{"t":"叠前韵 其二","f":"七言律诗","c":["旧事重重托梦华，六朝金粉剩寒鸦。","山中小有留人桂，海上虚无泛月槎。","故国音书迟雁帛，残军屯落满虫沙。","金乌太是无情物，才写秋心影已斜。"]},{"t":"叠前韵 其三","f":"七言律诗","c":["天时人事互推迁，窥井明看火不然。","上地徘徊来怪鸟，故家沦落有穷蝉。","梧桐未老心先死，牛马无能鼻任牵。","欲诉閒愁寄明月，不知天上是何年？"]},{"t":"叠前韵 其四","f":"七言律诗","c":["落叶声中酒不辞，海天遥韵托琴师。","无边风月供伤别，如此江山合赋诗。","五夜壮心消鼓角，九秋残影失虹霓。","相看但作凄凉色，难向芙蓉忏绮思。"]},{"t":"叠前韵 其五","f":"七言律诗","c":["亭亭海树立波罗，瓣瓣天花散贝多。","丹穴求君太唐突，雪山成佛已蹉跎。","双龙输酒夷徵约，么凤收香客按歌。","镂鉥五中无限恨，不随金石共消磨。"]},{"t":"叠前韵 其六","f":"七言律诗","c":["红锦障泥七宝鞍，拓弦天半落飞翰。","贵游风气豪原易，衰世人才侠亦难。","燕市博徒空自负，汉家文网几曾宽？","剧怜变徵歌声歇，白日萧萧易水寒。"]},{"t":"叠前韵 其七","f":"七言律诗","c":["愁城欲藉酒杯开，中有周王避债台。","搜尽黄金空铸泪，谤深白骨易成灰。","龙蛇起陆宁关运，鸡犬登天各自才。","欲就麻姑同语海，等閒清浅到蓬莱。"]},{"t":"叠前韵 其八","f":"七言律诗","c":["别遣蚩尤作五兵，火攻无术保坚城。","中原不信消王气，上帝何曾爱众生？","地下干戈龙战血，天中丝管凤鸣声。","大雄冷洒慈悲泪，疲尽津梁度有情。"]},{"t":"再叠前韵 其一","f":"七言律诗","c":["碧海兰苕偶唱酬，诗人从古例悲秋。","千林落日僧归寺，一笛西风客倚楼。","尘世折磨增老境，江天空阔有渔舟。","不须浪跕飞鸢日，已念平生马少游。"]},{"t":"再叠前韵 其二","f":"七言律诗","c":["满地凉云漾月华，古堤疏柳已栖鸦。","玄霜夜捣姮娥药，银汉秋回海客槎。","饮酒且同陶靖节，上书不慕贾长沙。","梧桐院宇清阴减，卧看天边雁字斜。"]},{"t":"再叠前韵 其三","f":"七言律诗","c":["江山不共岁时迁，看到秋容也黯然。","漠漠平沙飞独鸟，萧萧落叶咽哀蝉。","高楼绿酒金龟换，古井青丝玉虎牵。","锦瑟春心无处托，冷抛弦柱感华年。"]},{"t":"再叠前韵 其四","f":"七言律诗","c":["泪洒千秋绝妙辞，风流何处有吾师。","一编断烂前朝报，百感凄凉乐府诗。","梦里藏舟移夜壑，醉中呼剑斫雌霓。","秋江冷共鱼龙卧，不尽平居故国思。"]},{"t":"再叠前韵 其五","f":"七言律诗","c":["漫随鹞子过新罗，定后禅心入妙多。","贤圣与人同寂寞，英雄何事悔蹉跎？","色身优钵花重现，乐谱迦陵鸟自歌。","风浪不生云不起，青天碧海镜双磨。"]},{"t":"再叠前韵 其六","f":"七言律诗","c":["年年乡梦阻归鞍，恨不随风化羽翰。","捲土重来心未已，移山自信事非难。","雨馀玳瑁潮初落，月下珊瑚岛渐宽。","地老天荒留此誓，义旗东指战云寒。"]},{"t":"再叠前韵 其七","f":"七言律诗","c":["铜鼓声中海雾开，大江东去客登台。","素车白马千秋泪，红粉青衫万念灰。","逃酒未应衰凤德，读书谁信卧龙才？","文章刊落身将隐，不待山妻劝老莱。"]},{"t":"再叠前韵 其八","f":"七言律诗","c":["未得萧郎作骑兵，已教鲍照赋芜城。","枯桑摇落天风急，残夜苍凉海日生。","怖鸽露寒依佛影，愤鼍潮起应军声。","新歌懒付珠儿女，自写崟崎历落情。"]},{"t":"三叠前韵 其一","f":"七言律诗","c":["忍把河山作报酬，五陵佳气郁清秋。","参差碧瓦何王殿，零落璇题故相楼。","遗幕逃亡驱鹿部，禁池阑入打鱼舟。","百年父老关东尽，无复秋风望豫游。"]},{"t":"三叠前韵 其二","f":"七言律诗","c":["烽火关山驻翠华，月明宫树有啼鸦。","海神连弩邀秦辇，天女支机落汉槎。","环卫千牛归素仗，窥边万马蹴黄沙。","行人莫问前朝事，秋草离离御路斜。"]},{"t":"三叠前韵 其三","f":"七言律诗","c":["沙堤走马几除迁，烜赫声华顿寂然。","丛棘墓门无大鸟，古槐台省有寒蝉。","升沈粟羡侏儒饱，歌哭丝将傀儡牵。","坐致三公待佳传，白头閒过太平年。"]},{"t":"三叠前韵 其四","f":"七言律诗","c":["五等勋庸费制词，廿年强寇滞王师。","乾坤几见回元气，箕斗频闻入怨诗。","故事空文悬日月，极天荒象阻云霓。","长星劝汝惟杯酒，戎马关河扰梦思。"]},{"t":"三叠前韵 其五","f":"七言律诗","c":["谁持铃铎召修罗，白日荒荒鬼气多。","地火动摇阿耨达，天龙奔走跋难跎。","十方已竭降魔法，八部犹喧赞佛歌。","依旧宝光璎珞相，故应尘劫不能磨。"]},{"t":"三叠前韵 其六","f":"七言律诗","c":["河声岳色送征鞍，宫扇云移彩凤翰。","载宝尚闻朝络绎，要盟谁念事艰难。","双悬日月天如故，百战河山地本宽。","留与四方哀痛诏，莱芜风雪话饥寒。"]},{"t":"三叠前韵 其七","f":"七言律诗","c":["海气阴阴昼不开，秋生辽后旧妆台。","黄金天长修宫价，黑土人讹止水灰。","凤阁平章新改制，龙门游幸各呈才。","春风回首华清浴，白玉莲花没草莱。"]},{"t":"三叠前韵 其八","f":"七言律诗","c":["猎猎牙旗北府兵，将军授钺拥连城。","材官并用蠕蠕国，幕府兼罗触触生。","岂有梦工详坼翼，更无故伎识雌声。","太冲长揖归田日，不尽秋风咏史情。"]},{"t":"四叠前韵 其一","f":"七言律诗","c":["眉史修成待酒酬，江南花草不曾秋。","牙樯锦缆三千里，淡粉轻烟十二楼。","水阁笙歌开曲宴，河桥灯火数行舟。","龙蟠虎踞应犹昔，惆怅西风白下游。"]},{"t":"四叠前韵 其二","f":"七言律诗","c":["竹西歌吹旧繁华，落日雷塘噪暮鸦。","绿舫呼筝歌玉树，青帘沽酒醉银槎。","才人十错猜新谜，游女双弯踏浅沙。","欲写古欢隋苑夕，二分明月玉钩斜。"]},{"t":"四叠前韵 其三","f":"七言律诗","c":["夫差不愿甬东迁，吊古苏台意惘然。","香径有花栖晚蝶，梧宫无树语哀蝉。","凄凉儿女千秋泪，佳丽江山万念牵。","何处夜深腾剑气，虎丘衰草自年年。"]},{"t":"四叠前韵 其四","f":"七言律诗","c":["才人例喜骋雄词，此水能当十万师。","南渡君臣多失策，西湖风月最宜诗。","梅边移舫飘香雪，柳外通桥落彩霓。","未许吴山轻立马，等閒留作画中思。"]},{"t":"四叠前韵 其五","f":"七言律诗","c":["谁遣西施出苧萝，兴亡事在女戎多。","卧薪夜室仍教舞，采蕺春山更试歌。","千古风流成怨毒，廿年雪耻未蹉跎。","浣沙溪女应相忆，一舸鸱夷恨不磨。"]},{"t":"四叠前韵 其六","f":"七言律诗","c":["流落英雄老据鞍，能教龙凤起鳞翰。","江山残局三分定，豚犬诸郎一战难。","名士鲫来春水长，女儿花发大堤宽。","千秋形胜荆襄在，落日城头画角寒。"]},{"t":"四叠前韵 其七","f":"七言律诗","c":["扶桑日出海云开，来访琅琊刻石台。","北徙河流关王气，东封泰岱忆雄才。","少年结客黄金尽，方士求仙白骨灰。","极目青齐平野阔，莫教形势失登莱。"]},{"t":"四叠前韵 其八","f":"七言律诗","c":["中原百战未消兵，落日黄河绕汴城。","道士坠驴天下定，香孩夹马圣人生。","重苏地脉金刀梦，遍散春风玉笛声。","周鼎已沈何日起，洛阳回首不胜情。"]},{"t":"五叠前韵 其一","f":"七言律诗","c":["客怀难借越装酬，雁翅城荒海气秋。","铃语颠风六榕塔，帘钩落日五层楼。","雕青侠少鹌鹑会，拾翠佳人孔雀舟。","消耗壮心无处著，十年閒作岭南游。"]},{"t":"五叠前韵 其二","f":"七言律诗","c":["珠江从古号繁华，都付斜阳万点鸦。","霸主宫庭馀断柱，仙郎河汉歇浮槎。","黄金铸橘公孙树，碧海栽桑子母沙。","欲写美人香草恨，秋芜满地素馨斜。"]},{"t":"五叠前韵 其三","f":"七言律诗","c":["罗浮春酿慰南迁，小饮酥醪意兀然。","水稻香疏栖夜鹤，木棉阴薄曳秋蝉。","趁墟货集猺人出，过滘船迟蛋女牵。","渐习土风思载笔，欲将盘古起编年。"]},{"t":"五叠前韵 其四","f":"七言律诗","c":["蛮夷大长亦工词，竟筑朝台望汉师。","生为丈夫除帝制，死留奇女报佳诗。","蛟精异代仍黄屋，龙气中天化白蜺。","一笑南强成底事，看花空发美人思。"]},{"t":"五叠前韵 其五","f":"七言律诗","c":["漫将宫历纪楼罗，歌舞江山乐事多。","石洞逢仙词恍惚，洛川置守事蹉跎。","残图牛角红云宴，遗忏羊头白雨歌。","留得镌年双铁塔，不教王梃共消磨。"]},{"t":"五叠前韵 其六","f":"七言律诗","c":["岂有奇云起马鞍，且收霸气入词翰。","分来玫瑰传宗易，醉到芙蓉救劫难。","蛮市银荒王面变，祖洲药秘鬼心宽。","登高欲纵中原目，一发青山夕照寒。"]},{"t":"五叠前韵 其七","f":"七言律诗","c":["莫言词客例能哀，潦倒秋心唱越台。","碧玉奇装颩短发，黄金淫祀荡飞灰。","九牛欲起枭雄梦，二虎终需控禦才。","那有仙山楼阁在，剧怜左股割蓬莱。"]},{"t":"五叠前韵 其八","f":"七言律诗","c":["时难年荒未罢兵，高秋骑马出佗城。","白云寺古山容瘦，黄木湾深海气生。","南雪挂松飘昨梦，西风吹荻战秋声。","大江东去人西上，难遣茫茫百感情。"]},{"t":"岭南春词 其一","f":"七言绝句","c":["万紫千红不敢开，先春独让岭头梅。","亭亭玉立天人相，天遣称尊花国来。"]},{"t":"岭南春词 其二","f":"七言绝句","c":["罗浮仙鸟声琅然，唤起春魂遍大千。","大千顿现梅花国，要把梅花作纪年。"]},{"t":"岭南春词 其三","f":"七言绝句","c":["瑶姬游戏爱春华，炼海成香转帝车。","天上玉龙三百万，一时齐化岭南花。"]},{"t":"岭南春词 其四","f":"七言绝句","c":["老干槎枒花满身，冰霜丰骨玉精神。","扫除海内风尘色，独立岭南天地春。"]},{"t":"岭南春词 其五","f":"七言绝句","c":["十年不负种花心，万玉千珠花气深。","锄罢月明吾事毕，看栽成树树成林。"]},{"t":"岭南春词 其六","f":"七言绝句","c":["千林万林落木空，空山一笑回春风。","谁知大地阳和气，都在暗香疏影中。"]},{"t":"岭南春词 其七","f":"七言绝句","c":["不知人事有冰霜，战退群阴玉魄强。","偶现色身仍本色，自开香界布天香。"]},{"t":"岭南春词 其八","f":"七言绝句","c":["开过南枝开北枝，天心冷暖花能知。","请看花落仍留子，正是人间渴望时。"]},{"t":"次韵答伯瑶","f":"七言律诗","c":["万里重阴拨不开，杜陵空剩赋诗才。","眼中王质残棋局，梦里胡僧旧劫灰。","大角气沈箕子国，落花愁上越王台。","可怜歌舞湖山乐，苦被江头战鼓催。"]},{"t":"将之岭东劝学，沈涛园廉访以长句见送，次韵奉答，兼柬岑云阶、张坚白","f":"七言古诗","c":["十年重作广州客，斜日朝台感今昔。","上将高谈横海坛，经师别换名山席。","要令五管盛文治，万派新潮海天碧。","少年豪想鲲鹏化，群蛮犷俗豚鱼格。","朝廷正用名臣后，畀养人才培国脉。","使节联翩后先至，侯伯谷蒲耀圭璧。","并念先公竹马儿，虽作荒伧犹护惜。","平生空慕仓海君，无力能褫虎狼魄。","新交子房偏我厚，卧我元龙楼百尺。","门前更留京兆马，明月清尊永佳夕。","青眼高歌送我东，惜我才薄无能役。","神州百年感桓温，广武一叹同阮籍。"]},{"t":"调颂丞 其一","f":"七言绝句","c":["新得佳人与护持，不愁撚断苦吟时。","但妨说有谈空口，怒触河东夜半狮。"]},{"t":"调颂丞 其二","f":"七言绝句","c":["我见犹怜况老奴，倾城颜色固应殊。","不知镜里新郎面，已似桓公猬磔无？"]},{"t":"调颂丞 其三","f":"七言绝句","c":["梅花开送隔林香，郁郁寒松色半苍。","若解嫦娥爱年少，龙宫先检染须方。"]},{"t":"调颂丞 其四","f":"七言绝句","c":["海外戈船忆异军，虬髯消息断知闻。","李郎一妹空惆怅，不见东风起战云。"]},{"t":"韩江有感","f":"七言绝句","c":["道是南风竟北风，敢将蹭蹬怨天公？","男儿要展回天策，都在千盘百折中。"]},{"t":"书孝方与兰西书后 其一","f":"七言律诗","c":["海外归来百感生，大江东下客西征。","沉沉广泽闻狐语，漠漠寒空过雁声。","万斛荡愁京口酒，四更残月石头城。","一书慷慨论身世，凄绝天涯此夜情。"]},{"t":"书孝方与兰西书后 其二","f":"七言律诗","c":["何方著足许吾徒，如此江山净土无。","冻雀哄群嬉坏幕，饥鹰趋食掠平芜。","干卿甚事寒池水，置我休持热火炉。","风雪满天尘满地，可容垂钓老江湖。"]},{"t":"寒入","f":"七言绝句","c":["寒入重衾睡不浓，寺楼初打五更钟。","开门忽觉前山雪，白遍东南四五峰。"]},{"t":"秋暑得雨","f":"五言律诗","c":["残暑酷未已，迫人无少休。","晚云低送日，凉雨飒生秋。","叶落声何急，苗枯病或瘳。","眼看时物变，聊用写离忧。"]},{"t":"书事","f":"七言绝句","c":["七尺珊瑚绿玉盆，宝花璀璨照天门。","洞庭新进龙君贡，压倒汪洋北海鲲。"]},{"t":"题仲迟月中课读图","f":"七言律诗","c":["一年几度见明月，况值红羊换劫年！","万里河山方破碎，一家儿女共团圆。","群龙无首今何在？","雌凤清声夜满天。","我正忧时不成寐，将诗题寄彩云边。"]},{"t":"短歌赠陈伯澜","f":"七言律诗","c":["终南大华遥相望，从天东下黄河黄。","千年王气久消歇，秋陵思哭秦汉唐。","三原陈生胸有史，东随黄河观海水。","茫茫海水扬胡尘，嗟哉何止秦无人！"]},{"t":"春阴和覃孝方 其一","f":"七言律诗","c":["极目平芜欲化烟，春愁黯黯不成眠。","半醒半醉帘垂地，微雨微晴水拍天。","望里花光浑暗淡，梦中云气太缠绵。","伏雷未起蛟龙蛰，閒过东风混沌年。"]},{"t":"春阴和覃孝方 其二","f":"七言律诗","c":["如雾如尘渺不分，碧濛濛地晕斜曛。","昏沈雷雨龙蛇气，惨澹江山锦绣文。","九锡绿章花待命，五原青幕鸟呼群。","天公懒展伤春目，俯瞰神州但密云。"]},{"t":"感春和覃孝方 其一","f":"五言律诗","c":["花发日南天，看花独惘然。","春风吹白发，海雨湿红棉。","梦落蛮云外，愁生越鸟边。","天涯鸾凤侣，飘泊又经年。"]},{"t":"感春和覃孝方 其二","f":"五言律诗","c":["春山二三月，东风桐始花。","花中么凤穴，花下美人家。","风软传吴语，溪香浣越纱。","相思寄红豆，相望隔青霞。"]},{"t":"次易实甫观察即席韵","f":"七言律诗","c":["丝竹当筵酒复醇，兹游未负岭南春。","落花风雨逢今日，香草沅湘见美人。","门第乌衣笑王谢，文章蝉噪薄梁陈。","平生雅忆横江楫，愧向江东作寄民。"]},{"t":"叠前韵 其一","f":"七言律诗","c":["贤王当代几恭醇，四海荒荒五十春。","玉斧河山非故土，金縢雷雨属何人？","杜鹃巢冷诗仍作，鹦鹉盟寒疏枉陈。","豆粥芜蒌前诏在，也曾哀恸慰臣民。"]},{"t":"叠前韵 其二","f":"七言律诗","c":["未必荀扬便大醇，悔将文字误青春。","相逢破碎支离局，如此崟崎历落人。","沧海潮流沈大陆，中天星象动钩陈。","黄龙旗飐东风急，待看雄军起国民。"]},{"t":"题易实甫所藏张梦晋岁寒三友图，实甫自言张后身也","f":"七言律诗","c":["岁寒图里松梅竹，谁遣山茶代老松？","古梦唤回缑岭鹤，仙身呼证洞庭龙。","拈花一笑人何在？","公案三生事偶逢。","悟彻画禅无我相，满天明月寺楼钟。"]},{"t":"题实甫所藏庐山开先寺宋牧仲施唐人地狱变相图并写经残卷","f":"古风","c":["金经已不完，泥犁亦残堕。","茫茫一片匡庐云，出山遍證人天果。"]},{"t":"四叠前韵","f":"七言律诗","c":["聊共曹参日饮醇，东风沉醉不知春。","此身未愿谋三窟，吾学原期敌万人。","细柳军筹寻剧孟，流苏步帐拥娇陈。","年来豪兴都消尽，已署头衔号逸民。"]},{"t":"五叠前韵","f":"七言律诗","c":["物我安能共化醇，昏昏八表也同春。","挥斤竞凿中央帝，抟土先愚上世人。","士气木鸡迟待养，儒书刍狗罢重陈。","寄愁天上愁天坠，那有星球许殖民？"]},{"t":"禽言和姚俊卿孝廉韵六首 其一","f":"古风","c":["天吊水。","元云黯黯天色死。","蓬发如霜不自理，玉榻金床卧忘起。","八柱摇摇半颓陀，佛哭仙啼怖天毁。","天公挥泪作洪水，流下昆崙为祸始。","天吊水。"]},{"t":"禽言和姚俊卿孝廉韵六首 其二","f":"古风","c":["树枝烧得著。","十日并出，轨道交错，妖光怪芒，天焚地烁。","手无后羿弓，安得九乌落？","榑桑根焦海水涸。","树枝烧得著？"]},{"t":"禽言和姚俊卿孝廉韵六首 其三","f":"古风","c":["兜兜。","汝有田畴，予用有秋。","汝车汝舟，予惟榷是求。","胥人而雠，胥鬼与谋；","山竭海枯，无孔不搜。","不竭不枯，予沽予售。","予惟鬼之酬，载冕载旒，亦莫敢予尤。","兜兜。"]},{"t":"禽言和姚俊卿孝廉韵六首 其四","f":"古风","c":["先顾！","先顾！","蹇人上天天有路，天门沉沉生紫雾，愚者不悟智者悟。","海上有秘方，黄金良可铸。","尔徒赤手谋青云，群仙不欢天亦怒。","河间车斑斑，何不谋之河间奼？","先顾！","先顾！"]},{"t":"禽言和姚俊卿孝廉韵六首 其五","f":"古风","c":["归飞！","归飞！","凤皇南飞，桐落竹稀。","集枯忍饥，水无莼菰、山无蕨薇。","芒芒四野，尔安适归？","归飞！","归飞！"]},{"t":"禽言和姚俊卿孝廉韵六首 其六","f":"古风","c":["都护！","都护！","汝屯汝戍，汝仓汝库。","饱汝潼酪，雄衣猛裤。","海不及煮，山不及铸；","赤地万里，惟汝之故。","山裂海飞，强者天仆；","我戈我矛，我剑我屦。","正我索疆，张我韶頀。","我妇我孺，十日大酺。","勿梦梦天，天今云寤。","谁为天言，朱鸟有咮。","都护！","都护！"]},{"t":"送蕴白之京二首 其一","f":"七言绝句","c":["廿载风尘两鬓丝，眼中世局太离奇。","马蹄重踏春明路，只有西山似旧时。"]},{"t":"送蕴白之京二首 其二","f":"七言绝句","c":["一官垂老如鸡肋，百口长贫借鹤粮。","犹有开元旧时曲，锦袍牙笏再登场。"]},{"t":"席上作","f":"七言绝句","c":["儿女英雄海上缘，东风吹散化春烟。","相逢欲洒青衫泪，已割蓬莱十四年。"]},{"t":"题崧甫弟遗像","f":"古风","c":["三岁识四声，七岁能文章。","十三冠童军，英声震文场。","平生性沉郁，雅不乐襮彰。","宅躬已高洁，治事尤精详。","奋起佐义师，大节何慨慷。","先忧后乐志未遂，眼看海化田栽桑。","眇眇一秀才，诏令侨海阳。","芦中之人信穷士，国仇家愤何能忘？","吃箫不为吴市乞，卜邻石户同农忙。","山中千树桐，泽中千足羊。","无聊聊读货殖传，更用陶朱公策施之商。","人生患难思骨肉，况乃兄弟非寻常。","少为失母雏，出入相扶将。","以父为之师，读书同一堂。","双峰之山何峨峨！","大甲之水何汤汤！","瑞莲王子池、古柏大部庄，何须风雨夕，始复思联床。","此情此境曾几日，君年且壮予且强。","渡江忠义人，俗口诮曰伧。","方同筹划宇宙分内事，将飞敛翼聊徜徉。","三豕渡河岁云暮，送君韩江江上风帆张。","谁知此别遂永诀？","至今每过泪洒江亭旁。","春风吹客忽出海，岂复再觅扶馀王？","临行不得一握手，心有万绪谁度量。","三书海外竟绝笔，语语真挚尤心伤。","忧患焚和抑何亟？","满腔热血冰难凉。","丈夫死牖下，恨不为国殇。","是时乾坤正翻覆，目不忍视能无盲？","飘然撒手不姑待，南溟有客方归航。","闻丧复闻乱，百感增茫茫。","谁为赋大招？","返魂终无香。","魂来夜黑晓得耗，信知梦寐非荒唐。","登坟一哭千古恸，空山转眼今几霜。","渡台船针指辰巽，山中坟向如其方。","化为黄鹄有羽翼，东南飞定还吾乡。","黄鹄能言反乎复，天荒地老此恨终须偿。","安能浪信人言已成佛，幻视世界无兴亡。","佛言我相即非相，此图何乃神飏飏！","每见此图在，不信其人亡。","其才未展肆，其貌非老苍。","丰其智慧啬其寿，生才何意吾直疑彼苍。","神龟不可呼，安得叩九阊。","吾家世忠孝，卜者言将昌。","不于其身于其子，丹山已见双凤皇。","益之一凤雏，三凤方翱翔。","视此图中人，前辉而后光。","题图者谁？","为乃兄义师故帅虞曹郎。"]},{"t":"题凌孟徵天空海阔簃诗钞并答所问台湾事三首 其一","f":"七言绝句","c":["欲问天空海阔处，来访天空海阔簃。","九江门下几人在，风雨萧萧高咏诗？"]},{"t":"题凌孟徵天空海阔簃诗钞并答所问台湾事三首 其二","f":"七言绝句","c":["多君欲问台湾事，曾作大将军现身。","满目劫尘无法说，青天碧海哭诗人。"]},{"t":"题凌孟徵天空海阔簃诗钞并答所问台湾事三首 其三","f":"七言绝句","c":["牙旗猎猎卷东风，旧事真成一梦中。","自有千秋诗史在，任人成败论英雄。"]},{"t":"送实甫游罗浮","f":"五言律诗","c":["君到罗浮去，蓬莱在眼前。","文章小虫鸟，奴隶古神仙。","呼日出云海，驱龙起洞天。","安期如可遇，休话避秦年。"]},{"t":"放歌次实甫将别岭南韵","f":"楚辞体","c":["仙不在菖蒲涧，佛不在风幡堂。","劳君打包出东林、骑鹤离武昌。","与君携手南极旁，坐看东海恶潮撼乐浪、西峤战云连点苍。","地下斗麒麟，天上笯凤凰。","有矢不得射贪狼，有弓不得挂扶桑。","三十六军尽女子，军中之气安得扬？","乘轩三百人，济济何跄跄？","江南李花河北杨，天下方歌妩媚娘。","瓮头揭取六一泥，放出北斗斟天浆。","上天谁禦蛟龙车？","渡海谁驾鼋鼍梁？","地下主者媪不翁，天上主者刘而张。","烈烈蚩尤魂，持头欲咋古帝轩辕黄。","千秋万岁心徒伤，横来小者侯而大者王。","乃今置之祝融汪，古月不凉今月凉。","不生不死，百草何用神农尝？","长剑玉珥鸣琳琅，北收黄河南收江，乾坤纳纳一钵藏。","筮亦不能短，龟亦不能长。","赤手捧出日月双，九头之纪重纪天地人三皇。","北不尽幽燕，南不尽荆扬。","呼取天孙为织裳、牵牛为服箱。","胡为乃与下界虮虱徬徨重徬徨。","古来颜回为素臣、仲尼为素王。","华衮斧钺，笔削终日忙。","有天仅倚杵，压头头不昂。","丈夫动辄计万世，毕竟几人遗臭与流芳。","麟乎麟乎逢鲁圉，凤兮凤兮趋楚狂。","僬侥之民不自小，乃与龙伯大人之国相颉颃。","天欲无三光，地欲无五常。","世间狐貉瞰人尽，更遣虎豹来九阊。","与君相逢今日竟何日，非苏非李落日吟河梁。","三万六千椰酒觞，饱有荔枝饥槟榔。","三生一穗沉水香，死不用青蝇吊仲翔，生不用金鸡下夜郎。","罗浮仙蝴蝶，作茧供衣裳。","香溪之水春可航，朱明洞天径未荒。","送君此去吾亦隐，四百三十二君待我开草堂。","麻姑、玉女、梅花、美人尽列侍，人间无此温柔乡。","噫嘻乎嗟哉！","白云乡是温柔乡。"]},{"t":"镇海楼送王豹君方伯之蜀，次壁间彭刚直韵","f":"七言律诗","c":["秦汉河山胜国楼，苍茫云物望中收。","提封五管无交趾，入梦三刀有益州。","吾辈且为文字饮，此行休负武乡侯。","眼看到海牂牁水，凭仗清尊写别愁。"]},{"t":"叠前韵重送王豹君","f":"七言律诗","c":["霸气消沈剩此楼，倚栏坐看瘴云收。","三江东下朝炎海，五岭南趋控广州。","此地古来娱越帝，有人今日饯韩侯。","相期无负千秋在，不作寻常送客愁。"]},{"t":"来诗有忧滇意，三叠前韵","f":"七言律诗","c":["吴楚青山满柁楼，江帆风利不曾收。","邮程蜀水先巴水，边塞梁州近益州。","南徼旌旗开武帝，东都弓矢锡文侯。","碧鸡金马终无恙，休向乡关起暮愁。"]},{"t":"偶思藏事，四叠前韵","f":"七言律诗","c":["筹边重筑赞皇楼，徼外河山次第收。","蜀贾早闻通大夏，唐人原惜弃维州。","金瓶遗策思先帝，铁券分藩比列侯。","此去安西劳远画，恒沙无劫佛无愁。"]},{"t":"前诗于彭及楼事殊略，为五、六叠韵申其意焉 其一","f":"七言律诗","c":["衡阳一老此登楼，廿五年来迹未收。","诗草偶镌山畔石，画梅同镇海南州。","千秋铜柱悲交趾，一疏金牌比岳侯。","霄汉此心吾亦有，倚阑斜日不胜愁。"]},{"t":"前诗于彭及楼事殊略，为五、六叠韵申其意焉 其二","f":"七言律诗","c":["天涯送客五层楼，四月黄梅雨乍收。","劫火文章谈独漉，烟云图画忆雷州。","新诗偶和衡阳叟，遗碣难寻胜国侯。","五百年来弹指顷，不应还替古人愁。"]},{"t":"七叠韵答来诗意","f":"七言律诗","c":["如此江山如此楼，黄云出地紫云收。","蠹残旧义张三世，蜂起新谈大九州。","海外虬髯空作侠，人间猿臂负封侯。","学书学剑都无用，胸有茫茫万古愁。"]},{"t":"八叠韵有感于今之言理财者，赋以示王，非专为蜀言也","f":"七言律诗","c":["金阙银宫玉作楼，飞升功效几时收？","花开果落三千岁，棘地荆天四百州。","今日如求救时相，古人原重富民侯。","剧怜已竭东南力，难解司农仰屋愁。"]},{"t":"九叠韵重送王豹君","f":"七言律诗","c":["城下清江城上楼，阳关三叠韵初收。","文星南极尊前客，白雪西山剑外州。","故事蛮夷谈大长，新封方伯帅诸侯。","蚕丛鸟道今平地，无复当年蜀道愁。"]},{"t":"是日之客王方伯外，有蒋亦贌廉访、潘左阶观察、夏用卿殿撰，而主人则丁伯厚侍讲、吴玉臣编修、汪莘伯广文及予也，十叠前韵","f":"七言律诗","c":["眼中缥缈此飞楼，一代英雄坐上收。","木石心肠歌小海，神仙名姓占高州。","黑头公望推王掾，青骨平生羡蒋侯。","太史能文广文冷，有诗排闷酒浇愁。"]},{"t":"十一叠韵兼寄怀马介堂军门成都","f":"七言律诗","c":["文章不数赋登楼，江左夷吾望早收。","洱海苍山怀故国，华阳黑水领梁州。","筹边若访征南将，被甲应逢新息侯。","为道丘迟今问讯，莺花三月寄春愁。"]},{"t":"十二、十三、十四叠韵，感喟无端，聊复成此 其一","f":"七言律诗","c":["万方多难此登楼，棋局长安劫未收。","无地罗施非鬼国，有人平乘吊神州。","指南岂复遵黄帝，袒左安能属绛侯。","洗马渡江憔悴甚，自愁原不为人愁。"]},{"t":"十二、十三、十四叠韵，感喟无端，聊复成此 其二","f":"七言律诗","c":["长笛声中客倚楼，楼前江涨未全收。","平生风义刘司户，乱世人才祖豫州。","官职郎君行马贵，功名厮养烂羊侯。","琅玕锦段思酬赠，未拟张衡赋四愁。"]},{"t":"十二、十三、十四叠韵，感喟无端，聊复成此 其三","f":"七言律诗","c":["千尺空江百尺楼，须眉七尺气全收。","酒评鲁赵尊前国，笛破伊凉曲里州。","未愿山中呼宰相，断无地下反条侯。","南朝已退临江虏，天子无愁妓莫愁。"]},{"t":"归粤十四年矣，爱其风土人物，将长为乡人，诗以志之；十五、十六、十七叠韵 其一","f":"七言律诗","c":["岭云海日署吾楼，潦倒平生万念收。","孔雀文章惭越客，鹧鸪言语爱南州。","贲隅桂树名他郡，大庾梅花姓故侯。","但解此心安处好，此间原乐未应愁。"]},{"t":"归粤十四年矣，爱其风土人物，将长为乡人，诗以志之；十五、十六、十七叠韵 其二","f":"七言律诗","c":["一曲清江几画楼，水松阴里暑全收。","孟尝去后珠仍海，宋璟来时瓦此州。","万斗量花持互市，十年种果等封侯。","粤讴听久吾能解，拚己将心与解愁。"]},{"t":"归粤十四年矣，爱其风土人物，将长为乡人，诗以志之；十五、十六、十七叠韵 其三","f":"七言律诗","c":["濛濛海气几重楼，闽海孤帆粤海收。","绝岛流离归故国，本朝豪杰数炎州。","万家楚蜀生呼佛，百战苏常死未侯。","我爱文忠更忠武，九原难起话乡愁。"]},{"t":"十八叠韵答玉臣","f":"七言律诗","c":["寥落元龙百尺楼，祗馀湖海气难收。","雄心河曲三呼渡，残梦天门八督州。","嵩室白衣归李泌，谷城黄石瘗留侯。","刘郎已悔神仙误，天上何曾可寄愁？"]},{"t":"十九叠韵，仍前居粤之感也","f":"七言律诗","c":["镇山镇海两巍楼，两镇雄观一览收。","蒟酱自来通蜀郡，荔枝原不让闽州。","荒村野祭刘岩帝，古县遗封史定侯。","十四年来无一事，愧教双鬓老边愁。"]},{"t":"二十叠韵","f":"七言律诗","c":["依旧江山旧酒楼，无多佳句锦囊收。","布金与佛谈三世，铸铁看人聚六州。","海内知交半屠贩，冢中枯骨几王侯。","五湖欲载西施去，一叶扁舟万斛愁。"]},{"t":"二十一叠韵，有忆","f":"七言律诗","c":["堤边杨柳柳边楼，六角华灯夜未收。","十里荷花梦湖舫，二分明月忆扬州。","瑶天扇掩坤灵使，银汉槎回博望侯。","今日天涯芳草路，玉珰缄札写春愁。"]},{"t":"二十二叠韵，哀粤中之穷也","f":"七言律诗","c":["三十六江江上楼，早潮未上晚潮收。","陆梁地尽秦人戍，海曲天穷汉代州。","生有蒲葵归故令，死犹薏苡谤先侯。","明珠翡翠年来竭，不信严关不税愁。"]},{"t":"二十三叠韵，学使所居为南园，豹君方伯与新学使沈君子封皆能诗","f":"七言律诗","c":["飞虹双跨隔河楼，尽把南园古迹收。","五夜德星占上界，一时名士聚南州。","风神落落王平子，文采翩翩沈隐侯。","不负昔贤坛坫地，江山休送别离愁。"]},{"t":"二十四叠韵，豹君明日行矣，书此以结前诗未尽之意","f":"七言律诗","c":["走马旋看建节楼，中原王气未容收。","同扶日月尊皇极，再拓河山画禹州。","能识此时惟俊杰，安知吾辈不公侯？","罗浮风雨峨眉月，聊写天涯小别愁。"]},{"t":"况晴皋移居清水濠招饮，次韵","f":"七言律诗","c":["闻卜新居倚碧湍，中庭地比旧居宽。","百车傢具藏书富，五月江流抱阁寒。","大字署门防误叩，浊醪祀灶祝粗安。","草堂诗就还呼饮，已拟来过看药栏。"]},{"t":"答人问澹定村","f":"七言律诗","c":["群山忽豁见山门，幽绝溪山是此村。","鸡犬云中仙气在，衣冠田舍古风存。","桂生前代成尊宿，松占高峰长子孙。","不必桃花千万树，已教人作武陵源。"]},{"t":"次韵赠亦璞廉访","f":"七言律诗","c":["笔端燕赵悲歌气，如见望诸君不亡。","迢递乡心蓟门月，清严诗律柏台霜。","当君冠豸来南越，值我骑麟下大荒。","海上相逢此高咏，料应公干许升堂。"]},{"t":"戊申广州五月五日作","f":"七言古诗","c":["南风吹沙何烈烈，抟抟大地瓦解裂。","如山火云势岿蠘，欲雨不雨天益热。","照眼榴花作午节，江上水嬉武可阅，打鼓鸣钲角优劣。","使船如马马化龙，飞龙回头笑跛鳖，百里横江渡才瞥。","嗟尔健儿好身手，慎勿思起为枭桀。","年来民穷盗益多，群盗如毛不可栉。","小犹乡落事攻剽，大且据城谋篡窃。","此方告平彼旋起，一岁之间四五发。","东南已无干净土，半壁江山半腥血。","民言官苛迫民变，官言革命党为孽。","彼哉革命党曷言，下言政酷上种别。","假大复仇作橥楬，横从海外灌海内，已似洪流不可绝。","益之民穷变易煽，鱼帛狐篝竞潜结。","事败党人辄跳免，东邻西邻相窟穴。","可怜惟尔愚民愚，身罹兵诛家立灭。","年来招兵兵益多，东征西防未容撤。","饥困兵言月饷少，罗掘官言库储绌。","嗟哉民变犹可说，祗忧兵变不可说，此事迩来已芽蘖。","民犹可煽况煽兵，庞勋之徒何代蔑？","尤难言者东西邻，公庇群凶嗾内齧，鹰瞵狼睒谋我缺。","彼谋我者原多途，既山取金路敷铁。","更乘内乱肆厥毒，坐恐吾民靡有孑。","我今内治方无人，何力能俾外谋折？","官惟露布誇贼平，功状张皇某某列。","愁来且进菖蒲觞，有荔如丹藕如雪。","龙舟归去夜微雨，仰视江天黯空阔。"]},{"t":"寄赠国学保存会诸子","f":"七言古诗","c":["文明古国五千载，中经秦火诗书在。","汉兴诸儒功最多，不有守先后何待。","西海潮流猛秦火，东风复助为妖祸。","障川挽澜今无人，后生小子忘丘轲。","昆崙山高东海深，百王千圣知此心。","终看吾道益光大，日月行天无古今。"]},{"t":"次王雪澄赠实甫韵 其一","f":"七言律诗","c":["未除鳌愤龙愁气，曾伍麖头鼠目官。","雷雨文章惊世易，云霄毛羽置身难。","千秋位业馀尘土，四海知交几胆肝。","满眼东西南北水，不妨平地看流湍。"]},{"t":"次王雪澄赠实甫韵 其二","f":"七言律诗","c":["我宁局龊人间世，不慕神仙上界官。","龙气飞腾馀剑在，蛾眉谣诼入时难。","多生磨蝎缠身命，馀技雕虫鉥肾肝。","久既心平物无竞，任他流水起惊湍。"]},{"t":"次王雪澄赠实甫韵 其三","f":"七言律诗","c":["佛为多情仍住世，人原自贵不因官。","桑田沧海蓬莱浅，井络天彭蜀道难。","万里风尘愁入鬓，百年图史视伤肝。","茫茫时局谁能挽，已似扁舟下急湍。"]},{"t":"实甫将行赋此为别 其一","f":"七言律诗","c":["同向天涯吊落晖，百年回首壮心违。","沉沉楚泽龙犹哭，漠漠辽天鹤不归。","西徼霜飞名士饼，东都云散大王旗。","不须更向新亭去，已对河山泪满衣。"]},{"t":"实甫将行赋此为别 其二","f":"七言律诗","c":["欲借仙人玉笛吹，送君五月落梅时。","英灵江汉无今古，风雨罗浮有合离。","何事黑龙逢帝怒，前身青兕愧僧知。","相思待祝衡阳雁，更向南飞寄楚词。"]},{"t":"李湘文邀同雪澄、实甫、陶阳二子上涌村啖荔枝作","f":"古风","c":["东村有荔枝，西村有荔枝，南村有荔枝，北村有荔枝，村人看客衔尾舟来时。","双轮在前画舫随，入涌涌路歧复歧，汽笛鸣使村人知。","村人有约远迎客，村童村妇纷来窥。","几成看杀卫叔宝，荔枝树下人争围。","岂知老饕苍髯已三尺，馀客亦复鬑鬑皆有须，但动食指思朵颐。","是时荔枝半生熟，青红满眼光陆离。","荷包太早桂味迟，五月黑叶方垂垂。","采之满筐出供客，更令饱饫兼僮厮。","我舟泊处上有丞相祠。","但能耕稼魏公庄，岂必识字为佳儿。","村居若有千树荔，更用千户侯何为？","维闽与粤荔枝国，各有佳品因时宜。","君谟作谱起聚讼，彼优此劣词何支。","我生于闽长侨粤，有荔枝处皆尝之。","平生嗜荔如嗜色，情人之眼皆西施。","少年最爱十八娘，至今追忆神犹驰。","自来岭南日啖三百颗，临风辄念天人姿。","门书荔子甲天下，已生荔子生梅妃。","梅妃生闽杨妃粤，杨妃宠盛梅妃衰。","人间选色论品目，两皆尤物天所遗。","亦如荔枝各具色香味，相看不厌、不见常相思。","奈何玉环不自爱乡味，坐令蜀产称珍奇。","蜀荔之佳万万逊闽粤，维髯蜀客亦谓言非欺。","惜髯但啖粤荔未到闽海湄，惟应楚客粤归足傲道州老，此来非早仍非迟。","亲解海山仙人绛罗襦，临江况复将别离？","江天过午村鸡啼，满船载得荔枝去，濛濛烟雨遮船旗。"]},{"t":"荔枝 其一","f":"七言绝句","c":["海上仙襦解绛罗，名园取次遍蒐罗。","满前姬侍皆佳丽，持较文山艳福多。"]},{"t":"荔枝 其二","f":"七言绝句","c":["天生尤物本消魂，更取增城挂绿论。","一种天然好风格，西施初出苧萝村。"]},{"t":"荔枝 其三","f":"七言绝句","c":["每将佳果比佳人，自笑多生与种因。","粤艳闽香消受遍，不曾嚼蜡视横陈。"]},{"t":"荔枝 其四","f":"七言绝句","c":["紫琼肤孕碧瑶浆，色味双佳更带香。","若援牡丹花史例，荔枝原是果中王。"]},{"t":"述灾","f":"五言古诗","c":["炎天久不雨，一雨遂汎滥。","三江势俱涨，有地皆水占。","平乡水过屋，高市水入店。","桑田尽成海，馀者山未陷。","无堤能自坚，有稻不得敛。","灾民露天宿，屡徙常倚担。","生者鹄面立，死者鱼腹殓。","天心夙仁爱，忍使民昏垫。","无家百万人，仰视宁无憾。","虽有泛舟粟，救死亦云暂。","来日良大难，安能久遍赡？","平生愧禹稷，饥溺常在念。","徬徨起中夕，侧目江云暗。"]},{"t":"五月二十八夜不寐","f":"七言绝句","c":["夜来忽忆儿时事，海沸天翻四十年。","心绪如潮眠不得，晓星残角五更天。"]},{"t":"重过感旧园 其一","f":"七言律诗","c":["水木清华负郭园，三年客梦此重温。","眼中故物诗留壁，身后浮文酒满尊。","宿草青山名士泪，落花黄土美人魂。","池台无恙仍今日，已似闻琴对雍门。"]},{"t":"重过感旧园 其二","f":"七言律诗","c":["萧疏树石与摩挲，荔子初丹载酒过。","地下英灵应有语，座中耆旧已无多。","浮萍大海重相见，折戟沈沙冷自磨。","我感兴亡过存没，东风回首万重波。"]},{"t":"送刘铭伯之美洲 其一","f":"七言绝句","c":["轻装又别五羊城，海日曈曈送客旌。","六月扶摇鹏未息，看君舟绕地球行。"]},{"t":"送刘铭伯之美洲 其二","f":"七言绝句","c":["西海之西东海东，有洲悬立地球中。","此行遍布尊亲义，为道中天日月同。"]},{"t":"送刘铭伯之美洲 其三","f":"七言绝句","c":["不敲开国自由钟，不为寻洲踵阁龙。","唤起黄人思祖国，海天长啸落机峰。"]},{"t":"送刘铭伯之美洲 其四","f":"七言绝句","c":["九万征程走使车，一言九鼎信非虚。","不须十部贤从事，齐拜刘公一纸书。"]},{"t":"赠阳湖陈生","f":"七言律诗","c":["大江浩浩趋东海，汇为大湖涵远空。","由来江左数人物，民风虽雌文则雄。","阳湖陈生三十九，手治官书百粤走。","乞我题诗写古愁，夜半携尊酌南斗。"]},{"t":"题忽来道人荡寇志后 其一","f":"七言绝句","c":["摧倒天罡地煞碑，文心绝世正而奇。","九层宝塔圆光里，看取参仙起慧儿。"]},{"t":"题忽来道人荡寇志后 其二","f":"七言绝句","c":["欲向人间告太平，中原蛇虎正纵横。","一庵雷雨罗浮霁，云白峰青访丽卿。"]},{"t":"湘文叟五月邀往上涌啖黑叶荔枝，约六月桂味熟再来，叟病不果，承画扇见予，即次扇中诗韵","f":"七言律诗","c":["到处园林叫画眉，连村黑叶正垂垂。","江山尽入龙眠画，风雨兼惊太白词。","桂味近闻千树熟，箬篷前约一舟迟。","水支已过山支好，应是维摩病未知。"]},{"t":"赠慈善会诸女士 其一","f":"七言绝句","c":["变现诸天善女身，华鬘缨络不生尘。","大千手洒杨枝水，来救龙荒百万人。"]},{"t":"赠慈善会诸女士 其二","f":"七言绝句","c":["笙簧鼓吹文明气，不让娲皇止水功。","起陆龙蛇消劫运，黄金先铸女英雄。"]},{"t":"寿兰史五十","f":"五言律诗","c":["五十尚如此，百年将奈何？","文章新岁月，涕泪旧山河。","暂作支离叟，难求安乐窝。","南飞孤鹤在，聊取祝东坡。"]},{"t":"题刘伯端德配范菱碧所画帐额二十四番花信图 其一","f":"七言绝句","c":["廿四番风转画叉，天教徐淑配秦嘉。","玉台一管生春笔，遍为人间称意花。"]},{"t":"题刘伯端德配范菱碧所画帐额二十四番花信图 其二","f":"七言绝句","c":["替花写照为花怜，六角流苏宝帐悬。","门掩东风春似海，刘纲夫妇是神仙。"]},{"t":"重阳夕作","f":"七言律诗","c":["萧萧风叶转回廊，耿耿星河夜未央。","十载龙吟双剑隐，五更虫语一灯凉。","愁边泽国飞鸿雁，梦里家山卧犬羊。","遥忆黄花吾负汝，故园今日是重阳。"]},{"t":"新乐府四章 其一 留海发","f":"古风","c":["薙发令行二百年，乃有断发新少年。","奈何当断不断、后垂长尾而留短鬣当其前。","嗟汝半边头，笑杀蓬头仙。","蓬头仙人刘海蟾，匪仙而妖、不女不男，匪蟾而兔一笑堪。","雄兔扑朔、雌兔迷离，妾发覆额为天下雌；","郎发亦覆额，问郎将何为？"]},{"t":"新乐府四章 其二 花赈会","f":"古风","c":["闻灾而喜，以赈为利。","海上善士，万贯解缠。","以赈为名，其贵可卿。","不为利名，为民疾苦。","灼灼群花，式歌且舞。","西北苦旱，为云为雨，汝为神女。","东南苦涝，芦灰止水，汝为女娲。","琐骨观音，舍身救世。","摩登迦室，为此善会。","何以报之，祝花万岁。"]},{"t":"新乐府四章 其三 万牲园","f":"古风","c":["中国所有毕罗致，中国所无求海外。","力为禽兽造世界，神禹所驱今复聚。","毛虫羽虫大和会，除却凤麟无不至。","嗟哉夥颐万其类，无良、无猛、无蠢、无灵胥目曰牲，园吏按册皆可呼其名。","食粟者粟，食肉者肉；","尔虽不能言，无不得所欲。","文禽武兽前后补，京朝之官半寒苦。","人言员外郎，不及园中虎。","尔穷民、满天下，安能上与槛猿笼鹤伍？","古来灵囿何足言？","天荒地老有此园。","长安夜半西风起，啼呼如在山林间。"]},{"t":"新乐府四章 其四 济良所","f":"古风","c":["济良所，济几何？","长安落花日日多。","不忍落花付流水，欲落不落扶之起。","今日园中桃，昨日道旁李，还汝自由自今始。","噫戏乎嗟哉！","羲轩子孙奴隶矣；","更复漂流海外作人豕，可哀岂独儿女子。","济良所，奈何许！"]},{"t":"虫豸诗八首 其一 虱","f":"五言绝句","c":["黑白亦何常，出身本不洁。","臭香任蹠回，但解嘬膏血。"]},{"t":"虫豸诗八首 其二 蚊","f":"五言绝句","c":["朋起作民贼，有何文可名？","人皆防利喙，更莫震虚声。"]},{"t":"虫豸诗八首 其三 蝇","f":"五言绝句","c":["附骥亦云幸，营营殊可憎。","未容遽集此，赖有玉壶冰。"]},{"t":"虫豸诗八首 其四 蛆","f":"五言绝句","c":["一死成水仙，谁知孙登假？","趑趄复趑趄，妄梦得天下。"]},{"t":"虫豸诗八首 其五 蜂","f":"五言绝句","c":["与君同死生，义不殊贵贱。","由来香国中，不立贰臣传。"]},{"t":"虫豸诗八首 其六 蝎","f":"五言绝句","c":["尔族本在北，与官同至南。","未能相见喜，防尔尾间钳。"]},{"t":"虫豸诗八首 其七 蚓","f":"五言绝句","c":["尔鸣亦云善，尔操亦可嘉。","心肝尔全无，老作两头蛇。"]},{"t":"虫豸诗八首 其八 蛙","f":"五言绝句","c":["占遍官私地，闻声足自尊。","有人来语海，井底笑公孙。"]},{"t":"拟杜诸将五首用原韵 其一","f":"七言律诗","c":["金瓯无缺旧河山，难效前皇复闭关。","万里边尘来海外，九天兵法出人间。","中枢龙虎神符秘，上将旌旗夕照殷。","三十六军齐忭舞，登坛封拜属那颜。"]},{"t":"拟杜诸将五首用原韵 其二","f":"七言律诗","c":["留守东都拥百城，春风燕寝动帘旌。","全收朔雪天王地，重起渔阳彍骑兵。","芒砀片云应未散，蓬莱弱水几曾清？","于今射虎谁飞将！","胡马纵横右北平。"]},{"t":"拟杜诸将五首用原韵 其三","f":"七言律诗","c":["甘泉夜半屡传烽，太息陈书动九重。","未许天山三箭定，空闻函谷一丸封。","鬼神奇秘虚前席，狼虎追呼急上供。","筹罢军储筹岁币，年年仰屋大司农。"]},{"t":"拟杜诸将五首用原韵 其四","f":"七言律诗","c":["新军成镇复成标，兵气东南郁未消。","黄口小儿何咄咄，白头诸将已寥寥。","支离残骨千金骏，照耀雄冠七叶貂。","横海楼船劳怅望，几时征讨复天朝？"]},{"t":"拟杜诸将五首用原韵 其五","f":"七言律诗","c":["汾水秋风雁复来，百年人事不胜哀。","收兵自卫元戎府，教子谁登上将台？","西极传书青鸟使，南山上寿紫霞杯。","禁中早已储颇牧，不用焦桐爨下材。"]},{"t":"张肖夫明经索序其集，为题一律","f":"七言律诗","c":["二樵五百四峰云，化作诗人腕下文。","耆旧百年求岭表，经师一席重河汾。","空山泉石传高韵，落日松杉写古芬。","今日著书休问世，西风吹海正纷纷。"]},{"t":"晴皋以平蛮三将题名及元佑党籍碑拓见赠并先以诗赋此答谢","f":"七言律诗","c":["龙隐岩坳北宋碑，劳君远拓费毡椎。","边功一代归枢密，党祸千秋怨太师。","将相由来关大局，是非原不限当时。","眼前无尽兴亡史，落日悲歌瘴海湄。"]},{"t":"赠吴玉臣太史 其一","f":"七言绝句","c":["冠冕楼高海月明，鹤书屡下未成行。","如何当代文中子，不为君王策太平。"]},{"t":"赠吴玉臣太史 其二","f":"七言绝句","c":["旧栖鸾处作球场，天上人间事渺茫。","我爱岭南吴子野，海山高卧岁寒堂。"]},{"t":"次韵答晴皋自桂林东下舟泊阳朔见寄 其一","f":"七言律诗","c":["徵帆又挂桂江头，露下秋高潦未收。","入海古来仍此水，好山多处自维舟。","画中九马逢阳朔，吟罢双鱼寄广州。","追忆故人当独夜，乱峰相对写离忧。"]},{"t":"次韵答晴皋自桂林东下舟泊阳朔见寄 其二","f":"七言律诗","c":["瘦石寒花几度秋，十峰轩畔客淹留。","鏖诗屡逐中原鹿，入世难驯大海鸥。","杨柳关河游子泪，芙蓉旌旆美人愁。","枫青月黑相思夕，此境空劳梦里求。"]},{"t":"次韵答晴皋自桂林东下舟泊阳朔见寄 其三","f":"七言律诗","c":["西水今年没渚洲，涨痕重叠水边楼。","藏蛟石洞深难伐，穴蚁金堤溃未修。","农舍荒凉场九月，炊烟延眺米千舟。","知君东下高吟处，祗有哀鸿与和酬。"]},{"t":"次韵答晴皋自桂林东下舟泊阳朔见寄 其四","f":"七言律诗","c":["幢幢灯影欲残油，喔喔鸡声起睡眸。","金鼓关山劳北望，银云河汉黯西流。","高秋鹰隼终须击，大海鳌鱼不可钩。","应有梅花开十月，不妨清梦托罗浮。"]},{"t":"秋兴次张六士韵八首 其一","f":"七言律诗","c":["茫砀云开大汉年，眼看楚蹶复嬴颠。","收兵先下三秦地，奉使遥通百粤天。","照尽古人珠海月，飘残霸气玉山烟。","英雄祗剩前朝史，怀古悲秋意惘然。"]},{"t":"秋兴次张六士韵八首 其二","f":"七言律诗","c":["黄河东下走龙门，难起中原古帝魂。","天上斗牛沈剑气，人间鸾凤扫巢痕。","狄泉故壤双鹅出，瓯脱穷边万马屯。","不信开元天宝事，但留诗史浣花村。"]},{"t":"秋兴次张六士韵八首 其三","f":"七言律诗","c":["万里西风海欲波，荒荒白日奈愁何！","美人临顈浑脱舞，壮士阴山敕勒歌。","故国千年啼蜀魄，蛮荒九死负黎涡。","梦中还作钧天奏，蒙瞍逢逢自鼓鼍。"]},{"t":"秋兴次张六士韵八首 其四","f":"七言律诗","c":["坐看桑从海上栽，群鸥见惯不相猜。","生毛有地供秦笑，呵壁无天慰郢哀。","两帝中央谋混沌，三山左股割蓬莱。","故乡游钓今何处？","空忆渔人让曲隈。"]},{"t":"秋兴次张六士韵八首 其五","f":"七言律诗","c":["荒村独树老夫家，九月东篱菊未花。","金石自应求上药，河山原不阻飞车。","禦寒岂合裘仍典，谋醉何妨酒偶赊！","未解长安西笑乐，薜萝门外是天涯。"]},{"t":"秋兴次张六士韵八首 其六","f":"七言律诗","c":["衣冠文武眼中新，晏坐空山笑此身。","割地奇功酬铁券，周天残燄转金轮。","后庭玉树仍歌舞，前席苍生付鬼神。","细柳新蒲非复昔，更无人哭曲江滨。"]},{"t":"秋兴次张六士韵八首 其七","f":"七言律诗","c":["辽东华表鹤西飞，但作神仙愿已违。","故国河山残照尽，秋风城郭旧人稀。","四郊戎马边声急，七叶金貂世谱微。","休向哀鸿谈往事，江湖满地稻粱肥。"]},{"t":"秋兴次张六士韵八首 其八","f":"七言律诗","c":["五岭南来势纠纷，百年边事漫重论。","月中潮汐争消长，天外风雷骇见闻。","上国地埋龙虎气，中原人杂犬羊群。","山飞海立今何世？","閒就安期话白云。"]},{"t":"菊花诗四律 其一 逢菊","f":"七言律诗","c":["平生遇合多乖忤，不为看花不出游。","良友偶来三径夕，美人相见一庭秋。","飞鸿故国经年别，下马荒园竟日留。","笑口自开愁眼豁，西风休更送离忧。"]},{"t":"菊花诗四律 其二 献菊","f":"七言律诗","c":["平生耻作呈身事，坐爱黄花淡不浓。","何忍投人羞晚节，不妨供佛借秋容。","飘零冷艳荆山璞，催送寒香古寺钟。","云水半瓶花一束，梵天持取对芙蓉。"]},{"t":"菊花诗四律 其三 酬菊","f":"七言律诗","c":["平生百不偿所愿，惟爱秋英愿独偿。","何以报之花九锡，谁其云者雁孤翔。","黄金战罢先皇甲，紫绶勋垂岛国章。","有酒自浇诗自唱，故园明日又重阳。"]},{"t":"菊花诗四律 其四 饮菊","f":"七言律诗","c":["平生不饮自天性，惟赏金英饮独多。","十日壶觞秋色老，满城风雨醉颜酡。","独醒漫作餐英想，相对欣逢载酒过。","我自寿花花共寿，尊前来听百年歌。"]},{"t":"晴皋诗来，兼惠黄精，次韵答之","f":"五言古诗","c":["江山不复故，岂有故城郭？","登高浩四瞩，风尘变京洛。","我怀古仙人，五云有楼阁。","安能徇利名，生命付鼎镬。","服食求神仙，此意良不恶。","平生南北走，羹蛇饮羊酪。","支离养生事，入世久飘泊。","非无合丹术，神药犹待索。","黄金未能炼，四海一空橐。","入目皆桑田，沧海已成昨。","仰天自搔首，白发不可却。","高空何泬寥！","大野何广漠！","投身坠世网，羽翼何时作？","我本江海人，出世是归著。","惟君知此意，赠我仙人药。","灵兼芝草采，冷共梅花嚼。","于时天地昏，日月嗟蚀薄。","蟠湫蛟龙战，磔肉狼虎攫。","长啸谢世氛，一任舟移壑。","相期有霄汉，云霞得所托。"]},{"t":"十一月十五夜月蚀戏作 其一","f":"七言绝句","c":["不闻金鼓代天诛，休怪妖蟆胆气粗。","天上嫦娥应叹息，人间从此救兵无。"]},{"t":"十一月十五夜月蚀戏作 其二","f":"七言绝句","c":["经坛冷落散缁黄，吩咐嫦娥自主张。","东半地球无限事，那能更替月球忙。"]},{"t":"山寺 其一","f":"七言律诗","c":["秋来何处托吟鞭，古寺寻碑踏暝烟。","柳外断霞峰十二，花间凉月界三千。","西流星汉临高塔，南戒云山倚梵天。","风定相轮铃不语，下方人望佛灯然。"]},{"t":"山寺 其二","f":"七言律诗","c":["秋入高林晓色鲜，晨钟敲彻寺楼烟。","柳边洗钵僧三两，塔顶看云象万千。","西竺尘埋三世佛，南宗花散四禅天。","风幡不动心何动，晏坐空山意黯然。"]},{"t":"旅夜书怀","f":"七言律诗","c":["一身万里云无定，孤馆残更月欲斜。","湖海频年思弟妹，干戈馀劫起龙蛇。","九秋客况愁中酒，四海人心散后沙。","倚枕不眠思故事，汉朝终始在三巴。"]},{"t":"十二月十一书事","f":"七言绝句","c":["不见高欢六镇兵，一身去国羽毛轻。","平生大志浑无著，落日荒荒夹马营。"]},{"t":"白马乡有怀明义土赖若夫先生","f":"古风","c":["万山之中小县耳，乃有须眉之男子。","山是大明山，水是大明水，明亡六年犹守此。","岂有若夫为不善，人自不识若夫豪杰士。","若先生者，乃能真不死。","忠孝节义名四旗，白马之乡良足纪，先生之风今未已。","噫嚱乎嗟哉！","当时乃已神龙见首不见尾。"]},{"t":"赠莫生","f":"七言古诗","c":["海上原多不死药，此语传自秦汉间。","安知古语今始实，不死不在求神仙。","病原不死药之死，竞咎中医失医理。","由来官失学在夷，即今论药已如此。","多君卖药高韩康，专从海上搜神方。","瓶中海水尽甘露，不须更待神农尝。","五羊城头春草发，五羊城外春潮阔。","捣药仙禽啼海云，春风过处江山活。"]},{"t":"吴顈芝太守过访兼示守廉纪事诗","f":"七言律诗","c":["风雨鸣鸡夜向晨，将诗重话峤南春。","八千里外还珠郡，十七年中珥笔臣。","编集已成前岁月，卖刀犹念旧军民。","昏昏海气仍今日，谁为天涯洗劫尘。"]},{"t":"叠前韵答颖芝 其一","f":"七言律诗","c":["天涯为客负芳晨，五岭南来几度春。","适越岂容章甫士，登台空吊老夫臣。","梦回黄屋无真帝，泪洒朱崖有弃民。","君是故游吾故国，东风愁说海扬尘。"]},{"t":"叠前韵答颖芝 其二","f":"七言律诗","c":["廿载沈冥鸡失晨，九州求友鸟鸣春。","过江人物谁伧父，度岭文章几逐臣。","缟颎纻逢吴季子，琴樽休负葛天民。","韶光未老须行乐，明日飞花化陌尘。"]},{"t":"南园感事诗五首 其一","f":"七言绝句","c":["一代风骚起海湄，千秋忠愤剩荒祠。","兴亡并作斜阳色，如此江山合赋诗。"]},{"t":"南园感事诗五首 其二","f":"七言绝句","c":["五百年间几劫灰，南园非复旧池台。","溶溶玉带河边水，曾见张乔照影来。"]},{"t":"南园感事诗五首 其三","f":"七言绝句","c":["岂独伤心为古人，五年前事迹俱陈。","青青几树河桥柳，不待飞花已送春。"]},{"t":"南园感事诗五首 其四","f":"七言绝句","c":["女墙残月度钟声，捉鼻微吟笑洛生。","不信风流今歇绝，夜乌啼雨过春城。"]},{"t":"南园感事诗五首 其五","f":"七言绝句","c":["春潮欲上水松阴，春梦迷离不可寻。","人去堂空帘不卷，碧阑干外昼沉沉。"]},{"t":"次兰史席上韵即送北上","f":"七言律诗","c":["万里难驯羡白鸥，一尊坐对瘴云收。","中年亲故尤伤别，乱世文章易写愁。","扑岸海潮新战史，隔江灯火鬼樊楼。","出门未敢轻西笑，同是清歌在漏舟。"]},{"t":"忆上杭旧游 其一","f":"七言绝句","c":["前年记作上杭游，路入林塘境便幽。","三宿空桑吾不厌，春灯山寺话神州。"]},{"t":"忆上杭旧游 其二","f":"七言绝句","c":["江随山势百千盘，江上春云酿暮寒。","满径山桃红簌簌，斜阳呼渡大姑滩。"]},{"t":"忆上杭旧游 其三","f":"七言绝句","c":["黄坑黄笋旧知名，惜我来时笋未生。","我是主人兼看竹，绿濛濛地一兜行。"]},{"t":"忆上杭旧游 其四","f":"七言绝句","c":["寻碑亲拜左丞坟，谱牒都成史阙文。","七百年来遗老尽，更无人说旧参军。"]},{"t":"忆上杭旧游 其五","f":"七言绝句","c":["春田漠漠草萋萋，油菜花开烟叶齐。","鬼谷祠边春市散，淡云微雨过蓝溪。"]},{"t":"忆上杭旧游 其六","f":"七言绝句","c":["各乡各族分房祖，各有家祠额字嵌。","龙虎朱竿狮白石，门前灯写大官衔。"]},{"t":"忆上杭旧游 其七","f":"七言绝句","c":["梅花十八洞中天，闻有桑麻未垦田。","洞口云封人不到，空中楼阁住神仙。"]},{"t":"忆上杭旧游 其八","f":"七言绝句","c":["柿叶微丹栗叶黄，园林无限好秋光。","我来刚在春风里，万树梨花玉雪香。"]},{"t":"忆上杭旧游 其九","f":"七言绝句","c":["万峰顶上访前朝，龙刨相传出禦窑。","皇觉天人遗象在，家家齐捧佛香烧。"]},{"t":"忆上杭旧游 其十","f":"七言绝句","c":["东南山豁大河通，汀水南来更向东。","四面青山三面水，一城如画夕阳中。"]},{"t":"忆上杭旧游 其十一","f":"七言绝句","c":["斗旁拜鬼都何益，且拜吾家两直臣。","百尺楼头看天象，古来豪杰尽星辰。"]},{"t":"忆上杭旧游 其十二","f":"七言绝句","c":["萧疏树石香光画，乞付装池橐载回。","残册流传佳话在，有人拚弃一官来。"]},{"t":"忆上杭旧游 其十三","f":"七言绝句","c":["偏传绝学到东夷，寥落中原事可知。","今日阳明祠下过，冥冥雷雨读残碑。"]},{"t":"忆上杭旧游 其十四","f":"七言绝句","c":["知是烟痕是露痕，四山一碧竹连村。","家家制纸临溪屋，水碓声中昼掩门。"]},{"t":"忆上杭旧游 其十五","f":"七言绝句","c":["三年不负题诗约，十日曾为置酒留。","如此溪山归未得，眼前沧海正横流。"]},{"t":"以摄影法成澹定村心太平草庐图，张六士为题长句，次其韵","f":"古风","c":["我生本在东海东，中有万三千尺出海之高峰。","此峰上有万年不化之古雪，玉立天半尤奇雄。","我生延平同甲子，坠地心妄怀愚忠。","毗耶故国不能守，脱身兵火烧天红。","坐令玉山竟落五百年后此一劫，有愧东渡沧海朱家龙。","扁舟走闽复走粤，郁然五岭佳气何葱茏？","神僧许我一片乾净土，闯然入户精灵通。","闽粤之交小卜筑，手斩荆棘披蒿蓬。","南来腾空立天马，北眺水月明石虹。","玉华金简并罗列，吾庐为主山为从。","东望军山念吾祖，勤王当日亦复师无功。","吾庐之西万松顶，大山小山森相宫。","此山乃若特为吾庐设，山名不妨偶与匡君同。","四山之中中有村，吾庐适在村当中。","人间若别有天地，桃花流水尽日声淙淙。","额吾庐以黄庭语，岂欲上蹑神仙踪？","表吾庐者奉新许，笔势劲若铭彝钟。","丙申之春吾庐寔经始，买山更在光绪乙未之初冬。","十五年中一转瞬，辋川图画久慕前贤风。","镜中谁作此狡狯，山林舍宇人物顿觉如亲逢。","堂堂乎张，文采冠吾党，前辉后光昌而丰。","人生意气潜契合，东山茯苓西山松。","为吾题图意乃在图表，证今引古词何鸿！","即以词论已超绝，直与明镜摄影齐神工。","嗟哉文学在今日，遭值世宙方昏雺。","已抑公羊作饼家，更诬孔子为儒童。","三年不飞亦已矣，岂有一举天能冲？","夐乎欲论太平世，人狙出口谁能容？","君家仲坚昔吾慕，偶然游戏海上思作虬髯公。","安知仍落此世界，儒冠复戴奄奄欲绝宁吾衷。","已无一时豪杰可摧倒，聊欲万古开拓吾心胸。","昆崙山脉走南戒，万水趋海朝祝融。","此间山水清雄良足寄怀抱，且收倚天长剑韬神锋。","太平之民或容作，教取子孙识字为耕农。","南荒丹山本凤穴，凤虽不至吾仍种竹栽梧桐。","梦中忽见海上故亲友，落月黑塞林青枫。","偶图山居志吾幸已脱劫外，乃劳翩然大句相推崇。","人生得閒无事亦仙福，黄庭此语吾所宗。","有山不归果何乐，世网一坠嗟重重。","庐山之君昨招我，云中手把青芙蓉。"]},{"t":"以摄影心太平草庐图移写纸本 其一","f":"五言古诗","c":["写影入明镜，移之尺纸间。","明镜无遁形，难得山真颜。","而况尺幅纸，欲写四面山。","山中有吾庐，更有山中田。","尝脔知大烹，见羽知吉光。","但写一角山，吾庐山之阳。","溪泉何汤汤！","树石何苍苍！","山尽补以云，中有无尽藏。"]},{"t":"以摄影心太平草庐图移写纸本 其二","f":"五言古诗","c":["天下万山祖，其名曰昆崙。","昆崙有南支，万里趋越门。","人生亦有祖，谁非黄炎孙？","归鸟思故林，落叶恋本根。","我从海上来，卜庐澹定村。","东望徵君山，吾祖祠墓存。","明夷兆谁筮？","参军墓谁题？","呀呀朱鸟咮，郁郁冬青枝。","夜半雪压庐，重撰铜弦词。"]},{"t":"以摄影心太平草庐图移写纸本 其三","f":"五言古诗","c":["绢寿八百年，纸本寿过之。","人生百年耳，写此将何为？","吾亦爱吾庐，此意陶潜知。","黄者径菊花，碧者门柳丝。","南山有佳气，松风吹酒卮。","高咏归去来，宜得图传之。","惜皆付后人，图者非当时。","十日画一水，五日画一石。","姚翁年七十，照海须眉白。","为写吾庐图，森森见松柏。","群山走腕下，万里若咫尺。"]},{"t":"以摄影心太平草庐图移写纸本 其四","f":"五言古诗","c":["昔者陆放翁，庵额心太平。","自云此三语，取自黄庭经。","放翁振奇人，平生喜谈兵。","上书论北伐，策马尝西征。","未甘以文字，供奉小朝廷。","至老志不衰，家祭诗可徵。","吾生于放翁，所遭百不同。","同者惟此心，天或哀吾穷。","有海畀不波，有岁畀常丰。","吾穷足自慰，老作太平翁。"]},{"t":"以摄影心太平草庐图移写纸本 其五","f":"五言古诗","c":["吾生寡嗜好，独嗜佳山水。","吾庐深山中，颇具丘壑美。","每咏紫芝歌，老亲色然喜。","山中白云词，时取教诸子。","虽不求神仙，亦究黄庭旨。","谁谓神仙言，治道不在此。","一心先自平，万事罔不理？","天下不太平，必自人心始。","仙者特山人，其人常葆真。","吾亦葆吾真，一室天下春。"]},{"t":"以摄影心太平草庐图移写纸本 其六","f":"五言古诗","c":["山中有老桂，已阅五百年。","不知众木中，何自全其天。","得毋月宫树，落子生此间。","亭亭十丈许，翠盖凌秋烟。","花时十里香，黄雪霏霏然。","此桂天下无，是当别作图。","上图栖翠凤，下图覆玉蜍。","再阅五千年，见桂知吾庐。"]},{"t":"叠韵再题心太平草庐图，并答温丹铭","f":"古风","c":["洪水已注沧溟东，洼者为泽高者峰。","茫茫大陆号中国，战争几辈誇英雄。","成为帝王败寇盗，佐帝王者臣称忠。","有史以来数千载，几朝战血山河红。","天地杀机不一发，草泽各倖蛇成龙。","一龙升天众蛇伏，龙居云气偏葱茏。","是时天下号一统，兵戈四海初交通。","青青战地见禾黍，遗民垦土锄蒿蓬。","威加海内猛士尽，贯日无气成长虹。","喔咻屡下宽大诏，与民休息民咸从。","词臣例上太平颂，举朝将相争言功。","迂儒掉头不肯信，手抚古瑟调商宫。","独居深念此何世，此仍据乱非大同。","亢然远慕太平世，高歌金石深山中。","山中古瀑飞潺淙，白云满径无人踪。","冥心自铸太平象，人间半夜闻清钟。","儒书自昔用者寡，况今闭塞方严冬？","匹夫慷慨念天下，我正坐有迂儒风。","挭然与世无一可，太平梦想能躬逢。","已不作太华陈希夷，又不作武当张三丰。","胡为独诵黄庭内景语，谡谡山阁风生松。","有山可隐尚不隐，秋南春北为宾鸿。","自名曰士亦求食，其术更绌农桑工。","不知挟持果何具，谓欲与世除昏雺。","太平有待吾且老，岂有丹鼎能还童？","眼中鸡鹜各争长，卧看一鹤苍霄冲。","庙堂纷纷有人在，山林养志犹吾容。","卧龙一出太多事，惜不终老从庞公。","吾庐山村曰澹定，聊付图画旌吾衷。","文昌题句叹奇绝，已若丹篆吞吾胸。","穷郊忽出八叉手，一收寒态生春融。","云龙上下吾党事，岂诧衣钵传机锋。","九原若起柳州柳，定许古调歌黄农。","春山花落桐君桐，春雨夜长枫人枫。","手披旧史发浩叹，无数神圣纷追崇。","乾坤一儒腐可笑，差喜吾党诗相宗。","画中吾庐在何许？","罗浮东望烟云重。","四百三十二峰正初日，海天朵朵金芙蓉。"]},{"t":"寄亦璞罗定军次","f":"七言绝句","c":["为问安之抑胜之，祗今此事几人知？","穷荒草木皆生意，满目春风上大旗。"]},{"t":"寄韫白三水","f":"七言绝句","c":["半晴半雨酿春和，春水溶溶绿始波。","三十六江楼上望，不知春在那江多？"]},{"t":"啸桐北上归，卧病沪渎，屡书来索诗，以纪当时之事，今春复申前约，距亡日仅浃旬耳二首 其一","f":"七言律诗","c":["牢落文章第一人，天门垂翅竟何因？","百年记注无前例，万事枢机有要津。","异日朱云空愤激，当时绛灌少交亲。","红莲幕客苍梧守，未许青蒲作直臣。"]},{"t":"啸桐北上归，卧病沪渎，屡书来索诗，以纪当时之事，今春复申前约，距亡日仅浃旬耳二首 其二","f":"七言律诗","c":["无路排云叫九阍，天涯何处与招魂。","千秋公论归风汉，四海才人哭寝门。","斗酒只鸡追夙约，尺书双鲤剩春痕。","平生风义吾尤愧，一恸荒江昼欲昏。"]},{"t":"春江","f":"五言绝句","c":["春水绿生波，春江打桨过。","阴晴浑未定，莫便脱渔蓑。"]},{"t":"宝汉茶寮歌","f":"古风","c":["青山不幸近城郭，万坟鳞葬成痏疮。","安知近郭无完坟，前者已掘后者藏。","每遭兵燹尤不幸，攻城筑垒多夷伤。","抛残万骨没秋草，圹砖墓石墙营房。","君不见五羊城外山上坟，明碑已少况宋唐！","千年忽出买地碣，玉骨久化黄尘扬。","土花洗出南汉字，传之好事珍琳琅。","当时邑里藉考證，其奈书劣文侜张！","清明风吹花草香，出门拜山车马忙。","茶寮杂坐半伧父，谁吊扶风廿四娘？"]},{"t":"孟徵以粤秀山无咎室诗见示次韵 其一","f":"七言律诗","c":["平生未悔作乖崖，亦解逢人辄道佳。","閒处看云容独立，说场论古喜相排。","一春积雨蛙生灶，满地残花蝶上阶。","自笑穷愁天海窄，输君空阔好诗怀。"]},{"t":"孟徵以粤秀山无咎室诗见示次韵 其二","f":"七言律诗","c":["楼台高占好林峦，曾写春愁此倚栏。","云物与时同变换，文章有泪下孤寒。","百年人事悲丝染，四海风尘把剑看。","休被故山猿鹤笑，罗浮归访葛洪丹。"]},{"t":"题张生所编东莞英雄遗集","f":"七言古诗","c":["榴花村人义旗起，梅蔚山下行朝峙。","桓桓仗钺熊将军，落日光回海云紫。","时先从祖判韶石，心共将军表忠赤。","嗟哉天水不复碧，热血射天天为白。","由来胡运无百年，此乡复出东莞伯。","东莞山水天下奇，英雄屡见生于斯。","天生英雄付劫运，尤伤心者袁督师。","敌方用间朝不知，长城自坏甘人欺。","朱明亡局决于此，何待粤中争立时！","北都破败南都弃，三闽四广成何事？","君臣遗冢空残碑，流花桥畔啼鹃泪。","尔伯尔侯苏与张，张家兄弟不可当。","苍黄百战野塘死，一死何止流荧光。","人言东莞古闻邑，有人吊古编遗集。","六百年来战血凉，夜半灵旗鬼雄泣。","鬼雄末造殊可哀，破碎河山莫收拾。","圆头山人尔何幸？","东南保障功名立。","我爱英雄尤爱乡，英雄况并能文章！","手持乡土英雄史，倚剑长歌南斗旁。"]},{"t":"古铜兵器歌","f":"七言古诗","c":["朱黛斑斓古铜斧，挥日断戈同出土。","就中古剑尤陆离，想见前皇奋神武。","五兵之铸铜为先，用铜尤在用铁前。","土花洗出古兵器，白日顿见三千年。","此地开疆始秦汉，此器殊难年代断。","玉鱼葬地忽有此，萧瑟河山战云散。","方今兵器尚火攻，从横海上兵尤凶。","伏尸百万闪电顷，古兵虽在皆閒铜。","藏之地下无不可，古魂夜啸青燐火。","出付人间考古人，九天日月消兵祸。"]},{"t":"秋怀八首，次覃孝方韵 其一","f":"七言律诗","c":["万古兴亡闪电过，百年人事几蹉跎。","海枯石烂英雄尽，木落江空涕泪多。","入梦人间无白日，洗愁天上有黄河。","茫茫四野穹庐底，来唱阴山敕勒歌。"]},{"t":"秋怀八首，次覃孝方韵 其二","f":"七言律诗","c":["蓬山沦没阻东归，看惯年年海水飞。","剩有壶公教地缩，更无苌叔与天违。","箖箊落日神猿哭，苜蓿秋风虏马肥。","今日秦庭非复昔，休将九顿拜无衣。"]},{"t":"秋怀八首，次覃孝方韵 其三","f":"七言律诗","c":["王母云旗缥缈间，冥冥龙去枉髯攀。","海中仙蚌流珠泪，天上寒鸦怨玉颜。","往事已沦开宝史，故宫曾唱纥干山。","剧怜未殉西陵葬，定策归来国老閒。"]},{"t":"秋怀八首，次覃孝方韵 其四","f":"七言律诗","c":["满目洪流治已迟，谁教天展九年期。","玄黄大化无今古，风雨神山有合离。","四海毕消蛟蜃气，九天同拜虎龙姿。","书生自作华胥梦，千载何妨此一时。"]},{"t":"秋怀八首，次覃孝方韵 其五","f":"七言律诗","c":["休讹舜死与尧囚，环海居然更九州。","日月不随天左转，江河还向海西流。","蛟螭国土黄金界，雕鹗旌旗白帝秋。","画革旁行新史笔，未妨荒外纪飞头。"]},{"t":"秋怀八首，次覃孝方韵 其六","f":"七言律诗","c":["秋城吹角夕阳斜，浪迹频年寄海涯。","拔后枯葹心未死，劫中残局著全差。","无聊身世文为戏，有例神州裔乱华。","不信东篱仍故节，岛夷章绂玷黄花。"]},{"t":"秋怀八首，次覃孝方韵 其七","f":"七言律诗","c":["东海求仙撰怪文，西园谐价策高勋。","眼中鸡鹜方争食，意外蛟龙未得云。","左纛岂誇蛮大长，短衣休叱故将军。","秦王梦里钧天奏，此曲人间本不闻。"]},{"t":"秋怀八首，次覃孝方韵 其八","f":"七言律诗","c":["浮云落木共飘萧，动地商音起素飙。","雷雨神龙双剑化，关河戎马一身遥。","黄天讹立多新说，赤道回流有热潮。","穷海高秋无限感，雄心依旧借诗销。"]},{"t":"秋怀次前韵 其一","f":"七言律诗","c":["三十登坛往事过，英雄儿女两蹉跎。","他乡白发愁边满，故国青山梦里多。","末劫文章龙起陆，孤星涕泪鹊填河。","弓衣绣坼秋魂冷，休唱尊前旧楚歌。"]},{"t":"秋怀次前韵 其二","f":"七言律诗","c":["东去辽城鹤不归，南来汾水雁犹飞。","玄黄残血三灵哭，苍白浮云万念违。","入世功名貂尾贱，过江风物蟹螯肥。","干戈满地吟梁父，未合隆中老布衣。"]},{"t":"秋怀次前韵 其三","f":"七言律诗","c":["丘墟只在百年间，京雒风流渺莫攀。","同化胡先亡李耳，抱头人反笑严颜。","扫除孛彗天边宿，梦寐金银海上山。","不信欢愁全不管，白云无恙道人閒。"]},{"t":"秋怀次前韵 其四","f":"七言律诗","c":["美人消息碧云迟，甲帐珠襦未有期。","江上青山名大别，穴中朱鸟号长离。","谈经鹦鹉多新语，添色芙蓉变旧姿。","欲采縻芜何处是，乱峰无际夕阳时。"]},{"t":"秋怀次前韵 其五","f":"七言律诗","c":["鸾受鞭笞凤受囚，眼中烟点失齐州。","掀翻成案无三古，抖擞群材出九流。","历历星辰天市夕，冥冥雷雨海山秋。","两头北极还南极，不在云霄最上头。"]},{"t":"秋怀次前韵 其六","f":"七言律诗","c":["北斗横天天汉斜，支机残石落天涯。","万灵雨泣三元改，六道轮回一念差。","洪水馀波湮息壤，故宫遗玉刻苕华。","瑶池欲吊西王母，簪遍人间白柰花。"]},{"t":"秋怀次前韵 其七","f":"七言律诗","c":["青骨钟山蒋子文，白头郎署杜司勋。","英雄潦倒耽声色，神女荒唐送雨云。","弹指顿成新世界，化身曾现大将军。","年来学得观空法，谢绝人天百不闻。"]},{"t":"秋怀次前韵 其八","f":"七言律诗","c":["大旗落日马萧萧，更遣轮飞海上飙。","百戏鱼龙残局短，一军猿鹤故山遥。","收雷入地藏阴火，呼月升天起怒潮。","别撰修罗新战史，钩陈兵气未能消。"]},{"t":"次韵易实甫肇庆道中","f":"七言律诗","c":["牂牁天半下飞湍，立马江头客据鞍。","疆域远通蛮部落，威容重见汉衣冠。","伤心元老骑箕去，极目层霄把剑看。","零落七星秋满地，天涯扶醉且凭栏。"]},{"t":"少瀛以诗舲自寿诗索和，走笔书此","f":"古风","c":["同年桂平黄少瀛，乞我诗寿张诗舲。","示我牛腰诗一束，寿诗舲者多公卿。","公卿满朝尽朱紫，持粱刺肥老且死。","安知海外百万天朝民，一任刲屠作人豕。","谁非黄炎之子孙，九天忍令呼无门！","上书宰相毁苛约，此议已比昌黎尊。","百年万事半颠倒，中外约章那可道？","嗟哉勿谓秦无人，我惜诗舲今已老。","侍儿能画兼能诗，专家诗画传女儿。","诗舲虽老足自遣，且姑谋乐休忧时。","少瀛一官老东粤，诗舲不官为粤客。","相逢相见五羊城，我亦忧时头早白。","海风十月寒吹人，出门欲觅梅花村。","梅花仙人傥有不老术，仙山同醉罗浮春。"]},{"t":"题陈老莲画石芝萱草","f":"古风","c":["忧来不可解，且写忘忧花。","更写石上芝，笔端英英生紫霞。","中原剩此埋忧土，纵不忘忧亦徒苦。","采芝聊作高山翁，留取丹青照千古。"]}]};